// The runtime an ESS conformance suite is run by, in TypeScript.
//
// Generated by `ess verify conform synthesize --target typescript`. Do not edit: change the
// specification and regenerate. The suite it runs is `suite.json` beside this file.
//
// # What you write
//
// One object satisfying Target, and one test that hands it over:
//
//     import test from 'node:test';
//     import { run } from './essconform/runtime.js';
//
//     test('conformance', async (t) => {
//         await run(t, () => newTarget());
//     });
//
// Nothing else. Every scenario, every assertion and every diagnostic below is derived from the
// specification, so adding a command or an invariant to the model adds checks here without anybody
// editing a test.
//
// # The runner owns every source of variation
//
// There is no clock read, no random number and no identifier minted anywhere except in Harness,
// which the runner constructs and hands to the target in each request. A target that needs a
// correlation id or a deadline is given one. This is what makes two runs over one specification
// produce the same report on any machine, at any load, on any day.
//
// Nothing sleeps. An `eventually` step asks the target again and hands it the deadline; the waiting
// happens inside the target, which is the only layer that knows what it is waiting for.
//
// # Where this differs from the Go runtime, and why
//
// The two must report the same counts, so every difference below is a difference of mechanism and
// none of them is a difference of verdict.
//
//   * `ErrUnsupported` is a sentinel `Error` and `isUnsupported` walks the `cause` chain, because
//     TypeScript has no `errors.Is`. `unsupported(reason)` is the `fmt.Errorf("%w")` of this file.
//   * The four optional capabilities are discovered by **method presence**, because an interface
//     is erased at run time and there is nothing to assert against. `isClock`, `isOrderedReader`,
//     `isPeriodicTarget` and `isEntitySetupTarget` are the only discovery in this file.
//   * Every Target method may return a promise. Go's is synchronous; a TypeScript implementation
//     of anything is not, and a runner that could not await one could not be handed a real client.
//   * A JSON number is carried as `JsonNumber`, its own digits, wherever Go carries `json.Number`.
//     `JSON.parse` collapses 9007199254740993 onto 9007199254740992 and the two runtimes would
//     then admit different lineages.
//   * Object keys are sorted with `byteCompare` wherever Go sorts, because Go orders strings by
//     their UTF-8 bytes and JavaScript orders them by UTF-16 code units, which disagree above the
//     basic plane.

import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

import {
  admitPredicateLeaf,
  admitPredicatePath,
  factPath,
  facts,
  fromNode,
  meaningDecimal,
  parseOperand,
  TruthTrue,
  TruthUnknown,
} from './predicate.js';
import type { FactSource, Predicate } from './predicate.js';
import { admitReading, expectReadingOrder } from './reading.js';
import type { ReadingReference } from './reading.js';
import {
  admitResponse,
  decodeResponseObservation,
  expectResponsePayload,
  responsePrimitiveAdmits,
  snapshotResponseResult,
} from './response.js';
import type { ResponseObservation } from './response.js';

// ---- the value universe -------------------------------------------------------------------------

/**
 * Node is one specification value: null, boolean, number, string, Node[] or a record of Node.
 *
 * Deliberately not a closed union: these are what the model's types project to, and a target
 * returning anything else has returned something the specification cannot describe. A closed union
 * would make every read of a value a narrowing exercise and none of the narrowing would be a check
 * the specification asked for.
 */
export type Node = any;

/** Row is one row of a view: a value per projected field name. */
export type Row = { [field: string]: Node };

/**
 * JsonNumber is a number token kept as the digits it was written with.
 *
 * `json.Number` in the Go runtime, and for the same reason: binary64 collapses every integer above
 * 2^53, so 9007199254740992 and 9007199254740993 are one value to `JSON.parse` and two to the Rust
 * admitter. A suite whose lineage differs only there would be admitted here and refused there.
 */
export class JsonNumber {
  readonly raw: string;

  constructor(raw: string) {
    this.raw = raw;
  }

  toString(): string {
    return this.raw;
  }

  valueOf(): number {
    return Number(this.raw);
  }

  /** The binary64 image of the token, and whether it has one. */
  float64(): [number, boolean] {
    const parsed = Number(this.raw);
    return [parsed, Number.isFinite(parsed) || this.raw.length > 0];
  }
}

/** ExactNumber is an integer token binary64 cannot hold exactly, kept as its canonical digits. */
export class ExactNumber {
  readonly digits: string;

  constructor(digits: string) {
    this.digits = digits;
  }
}

export function isObject(value: Node): value is { [key: string]: Node } {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    !(value instanceof JsonNumber)
  );
}

export function isNil(value: Node): boolean {
  return value === null || value === undefined;
}

// ---- errors ---------------------------------------------------------------------------------------

const UNSUPPORTED = Symbol.for('ess.conformance.unsupported');

/**
 * ErrUnsupported is what a target returns for a semantic it cannot expose.
 *
 * Distinct from a failure: a suite that counted "the implementation cannot show me this" as "the
 * implementation is wrong" would report a defect nobody can fix.
 *
 * Throw it, or throw anything whose `cause` chain reaches it — `unsupported(reason)` builds one
 * that carries the sentence, which is what the report and the log print.
 */
export const ErrUnsupported: Error = Object.assign(new Error('the target does not expose this'), {
  [UNSUPPORTED]: true,
});

/** unsupported wraps the sentinel around a reason, the way `fmt.Errorf("...: %w", …)` does. */
export function unsupported(reason: string): Error {
  return Object.assign(new Error(reason, { cause: ErrUnsupported }), { [UNSUPPORTED]: true });
}

/**
 * isUnsupported reports whether an error is, or wraps, ErrUnsupported.
 *
 * The `cause` chain is what wrapping looks like here, and the brand is what survives a chain an
 * adopter built by hand. Bounded, because a cycle in a chain somebody constructed is not this
 * function's problem to hang on.
 */
export function isUnsupported(error: unknown): boolean {
  let current: unknown = error;
  for (let depth = 0; depth < 64 && current !== null && current !== undefined; depth += 1) {
    if (current === ErrUnsupported) {
      return true;
    }
    if (typeof current === 'object' && (current as Record<symbol, unknown>)[UNSUPPORTED] === true) {
      return true;
    }
    if (!(current instanceof Error)) {
      return false;
    }
    current = current.cause;
  }
  return false;
}

/** errorText is `%v` on an error: what the message says, whatever was thrown. */
export function errorText(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

/**
 * itemAt is an element of a sequence whose index this runtime has already bounded.
 *
 * The compiler cannot see the bound — it is a `position` the admitter checked, or a length the
 * loop is written against — and a check here would be a second answer to a question already
 * answered. Every caller is a site the admission pass has decided.
 */
function itemAt<T>(items: readonly T[], index: number): T {
  return items[index] as T;
}

function attempt<T>(body: () => T): T | undefined {
  try {
    return body();
  } catch {
    return undefined;
  }
}

function failed(body: () => unknown): boolean {
  try {
    body();
    return false;
  } catch {
    return true;
  }
}

// ---- ordering that agrees with Go -------------------------------------------------------------------

/**
 * byteCompare orders two strings the way Go does: by their UTF-8 bytes, which is code-point order.
 *
 * JavaScript's own comparison is by UTF-16 code unit, and the two disagree for every character
 * above the basic plane — `'' < '\u{10000}'` in Go and the other way round here. Every sort
 * in this file that Go performs goes through this.
 */
export function byteCompare(left: string, right: string): number {
  const first = left[Symbol.iterator]();
  const second = right[Symbol.iterator]();
  for (;;) {
    const one = first.next();
    const other = second.next();
    if (one.done === true && other.done === true) {
      return 0;
    }
    if (one.done === true) {
      return -1;
    }
    if (other.done === true) {
      return 1;
    }
    const left_ = one.value.codePointAt(0) as number;
    const right_ = other.value.codePointAt(0) as number;
    if (left_ !== right_) {
      return left_ < right_ ? -1 : 1;
    }
  }
}

export function sortStrings(values: string[]): string[] {
  return values.sort(byteCompare);
}

function goLess(left: string, right: string): boolean {
  return byteCompare(left, right) < 0;
}

function goAtMost(left: string, right: string): boolean {
  return byteCompare(left, right) <= 0;
}

/** meaningKeys is the keys of a record in the order Go's `sort.Strings` puts them. */
export function meaningKeys(value: { [key: string]: Node }): string[] {
  return sortStrings(Object.keys(value));
}

// ---- strict JSON --------------------------------------------------------------------------------------

/** validUTF8 reports whether a string is well-formed, which is what `utf8.ValidString` asks. */
export function validUTF8(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = index + 1 < value.length ? value.charCodeAt(index + 1) : 0;
      if (next < 0xdc00 || next > 0xdfff) {
        return false;
      }
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      return false;
    }
  }
  return true;
}

/**
 * scalarStrings refuses the lone surrogates a permissive decoder would replace.
 *
 * Admission must refuse rather than repair: a document that decodes to something other than what
 * it says is a document two runtimes will disagree about.
 */
export function scalarStrings(raw: string): void {
  let quoted = false;
  for (let index = 0; index < raw.length; index += 1) {
    if (raw[index] === '"') {
      quoted = !quoted;
      continue;
    }
    if (!quoted || raw[index] !== '\\') {
      continue;
    }
    index += 1;
    if (index >= raw.length) {
      throw new Error('unfinished escape');
    }
    if (raw[index] !== 'u') {
      continue;
    }
    if (index + 4 >= raw.length) {
      throw new Error('unfinished Unicode escape');
    }
    const digits = raw.slice(index + 1, index + 5);
    if (!/^[0-9a-fA-F]{4}$/.test(digits)) {
      throw new Error(`invalid Unicode escape \\u${digits}`);
    }
    const code = Number.parseInt(digits, 16);
    index += 4;
    if (code >= 0xdc00 && code <= 0xdfff) {
      throw new Error('lone low surrogate');
    }
    if (code >= 0xd800 && code <= 0xdbff) {
      if (index + 6 >= raw.length || raw.slice(index + 1, index + 3) !== '\\u') {
        throw new Error('lone high surrogate');
      }
      const lowDigits = raw.slice(index + 3, index + 7);
      const low = /^[0-9a-fA-F]{4}$/.test(lowDigits) ? Number.parseInt(lowDigits, 16) : -1;
      if (low < 0xdc00 || low > 0xdfff) {
        throw new Error('invalid surrogate pair');
      }
      index += 6;
    }
  }
}

const NUMBER_TOKEN = /^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/;

class Reader {
  private readonly raw: string;
  private index = 0;
  readonly spans: WeakMap<object, [number, number]>;

  constructor(raw: string, spans: WeakMap<object, [number, number]>) {
    this.raw = raw;
    this.spans = spans;
  }

  private space(): void {
    while (this.index < this.raw.length) {
      const character = this.raw[this.index];
      if (character === ' ' || character === '\t' || character === '\n' || character === '\r') {
        this.index += 1;
      } else {
        break;
      }
    }
  }

  private expect(character: string): void {
    if (this.raw[this.index] !== character) {
      throw new Error(`invalid character at ${this.index}, ${character} expected`);
    }
    this.index += 1;
  }

  private string(): string {
    this.expect('"');
    let out = '';
    for (;;) {
      if (this.index >= this.raw.length) {
        throw new Error('unterminated string');
      }
      const character = this.raw[this.index] as string;
      if (character === '"') {
        this.index += 1;
        return out;
      }
      if (character === '\\') {
        this.index += 1;
        const escape = this.raw[this.index];
        this.index += 1;
        switch (escape) {
          case '"':
            out += '"';
            break;
          case '\\':
            out += '\\';
            break;
          case '/':
            out += '/';
            break;
          case 'b':
            out += '\b';
            break;
          case 'f':
            out += '\f';
            break;
          case 'n':
            out += '\n';
            break;
          case 'r':
            out += '\r';
            break;
          case 't':
            out += '\t';
            break;
          case 'u': {
            const digits = this.raw.slice(this.index, this.index + 4);
            if (!/^[0-9a-fA-F]{4}$/.test(digits)) {
              throw new Error('invalid Unicode escape');
            }
            this.index += 4;
            out += String.fromCharCode(Number.parseInt(digits, 16));
            break;
          }
          default:
            throw new Error(`invalid escape \\${escape ?? ''}`);
        }
        continue;
      }
      if (character.charCodeAt(0) < 0x20) {
        throw new Error('control character in string');
      }
      out += character;
      this.index += 1;
    }
  }

  value(depth: number): Node {
    if (depth > 128) {
      throw new Error('JSON nesting exceeds 128');
    }
    this.space();
    const start = this.index;
    const character = this.raw[this.index];
    if (character === undefined) {
      throw new Error('unexpected end of JSON input');
    }
    if (character === '{') {
      this.index += 1;
      const result: { [key: string]: Node } = Object.create(null) as { [key: string]: Node };
      this.space();
      if (this.raw[this.index] === '}') {
        this.index += 1;
      } else {
        for (;;) {
          this.space();
          const key = this.string();
          if (Object.prototype.hasOwnProperty.call(result, key)) {
            throw new Error(`duplicate key ${JSON.stringify(key)}`);
          }
          this.space();
          this.expect(':');
          result[key] = this.value(depth + 1);
          this.space();
          if (this.raw[this.index] === ',') {
            this.index += 1;
            continue;
          }
          this.expect('}');
          break;
        }
      }
      this.spans.set(result, [start, this.index]);
      return result;
    }
    if (character === '[') {
      this.index += 1;
      const result: Node[] = [];
      this.space();
      if (this.raw[this.index] === ']') {
        this.index += 1;
      } else {
        for (;;) {
          result.push(this.value(depth + 1));
          this.space();
          if (this.raw[this.index] === ',') {
            this.index += 1;
            continue;
          }
          this.expect(']');
          break;
        }
      }
      this.spans.set(result, [start, this.index]);
      return result;
    }
    if (character === '"') {
      return this.string();
    }
    if (this.raw.startsWith('true', this.index)) {
      this.index += 4;
      return true;
    }
    if (this.raw.startsWith('false', this.index)) {
      this.index += 5;
      return false;
    }
    if (this.raw.startsWith('null', this.index)) {
      this.index += 4;
      return null;
    }
    const matched = NUMBER_TOKEN.exec(this.raw.slice(this.index));
    if (matched === null) {
      throw new Error(`invalid character ${JSON.stringify(character)} looking for a value`);
    }
    this.index += matched[0].length;
    return new JsonNumber(matched[0]);
  }

  done(): void {
    this.space();
    if (this.index !== this.raw.length) {
      throw new Error('trailing JSON input');
    }
  }
}

/**
 * strictJSON decodes keys before comparing them, retaining scalar spellings and refusing duplicates.
 *
 * Numbers come back as `JsonNumber`, nesting beyond 128 is refused, a second top-level value is
 * refused, and a string carrying a lone surrogate is refused rather than repaired.
 */
export function strictJSON(raw: string): Node {
  return strictJSONWithSpans(raw).value;
}

/** strictJSONWithSpans is strictJSON, and the source range every composite value occupied. */
export function strictJSONWithSpans(raw: string): {
  value: Node;
  spans: WeakMap<object, [number, number]>;
} {
  if (!validUTF8(raw)) {
    throw new Error('input is not UTF-8');
  }
  scalarStrings(raw);
  const spans = new WeakMap<object, [number, number]>();
  const reader = new Reader(raw, spans);
  const value = reader.value(0);
  reader.done();
  return { value, spans };
}

// ---- Go's JSON encoding ---------------------------------------------------------------------------------

function quoteJSON(value: string, escapeHTML: boolean): string {
  let out = '"';
  for (const character of value) {
    const code = character.codePointAt(0) as number;
    switch (character) {
      case '"':
        out += '\\"';
        continue;
      case '\\':
        out += '\\\\';
        continue;
      case '\n':
        out += '\\n';
        continue;
      case '\r':
        out += '\\r';
        continue;
      case '\t':
        out += '\\t';
        continue;
      default:
        break;
    }
    if (escapeHTML && (character === '<' || character === '>' || character === '&')) {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
      continue;
    }
    if (code === 0x2028 || code === 0x2029) {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
      continue;
    }
    if (code < 0x20) {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
      continue;
    }
    out += character;
  }
  return `${out}"`;
}

/**
 * goMarshal writes the bytes Go's `encoding/json` writes: sorted map keys, `<` for HTML, and
 * an escaped U+2028 whatever the escaping mode.
 *
 * Byte-for-byte, because three of the limits in this file are counted in the bytes this produces.
 * A field carrying `undefined` is omitted, which is `omitempty` on the Go side of the same value.
 */
export function goMarshal(value: Node, escapeHTML = true): string {
  if (value === null || value === undefined) {
    return 'null';
  }
  if (value instanceof JsonNumber) {
    return value.raw;
  }
  if (value instanceof ExactNumber) {
    return value.digits;
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new Error(`json: unsupported value: ${String(value)}`);
    }
    return JSON.stringify(value) as string;
  }
  if (typeof value === 'string') {
    return quoteJSON(value, escapeHTML);
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => goMarshal(item, escapeHTML)).join(',')}]`;
  }
  if (typeof value === 'object') {
    const keys = sortStrings(
      Object.keys(value as object).filter(
        (key) => (value as Record<string, Node>)[key] !== undefined,
      ),
    );
    const parts = keys.map(
      (key) =>
        `${quoteJSON(key, escapeHTML)}:${goMarshal((value as Record<string, Node>)[key], escapeHTML)}`,
    );
    return `{${parts.join(',')}}`;
  }
  throw new Error(`json: unsupported type ${typeof value}`);
}

/** deepEqual is `reflect.DeepEqual` over the values this runtime carries. */
export function deepEqual(left: Node, right: Node): boolean {
  if (left instanceof JsonNumber || right instanceof JsonNumber) {
    return left instanceof JsonNumber && right instanceof JsonNumber && left.raw === right.raw;
  }
  if (left instanceof ExactNumber || right instanceof ExactNumber) {
    return (
      left instanceof ExactNumber && right instanceof ExactNumber && left.digits === right.digits
    );
  }
  if (isNil(left) || isNil(right)) {
    return isNil(left) && isNil(right);
  }
  if (Array.isArray(left) || Array.isArray(right)) {
    if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) {
      return false;
    }
    return left.every((item, index) => deepEqual(item, right[index]));
  }
  if (typeof left === 'object' || typeof right === 'object') {
    if (typeof left !== 'object' || typeof right !== 'object') {
      return false;
    }
    const leftKeys = Object.keys(left as object);
    const rightKeys = Object.keys(right as object);
    if (leftKeys.length !== rightKeys.length) {
      return false;
    }
    return leftKeys.every(
      (key) =>
        Object.prototype.hasOwnProperty.call(right, key) &&
        deepEqual((left as Record<string, Node>)[key], (right as Record<string, Node>)[key]),
    );
  }
  return left === right;
}

/** plainNumbers is what `json.Unmarshal` without `UseNumber` leaves behind: binary64, everywhere. */
export function plainNumbers(value: Node): Node {
  if (value instanceof JsonNumber) {
    return Number(value.raw);
  }
  if (Array.isArray(value)) {
    return value.map(plainNumbers);
  }
  if (isObject(value)) {
    const result: { [key: string]: Node } = {};
    for (const key of Object.keys(value)) {
      result[key] = plainNumbers(value[key]);
    }
    return result;
  }
  return value;
}

// ---- exact coverage inventory and original parent admission ------------------------------------

export function coverageError(): Error {
  return new Error('inconsistent closed coverage inventory');
}

export function originalDigest(raw: string): string {
  return `sha256:${createHash('sha256').update(raw, 'utf8').digest('hex')}`;
}

export function sourceIdentity(value: Node): void {
  const identity = text(value);
  for (const segment of identity.split('/')) {
    if (segment === '' || segment === '.' || segment === '..') {
      throw coverageError();
    }
  }
  for (const character of identity) {
    const code = character.codePointAt(0) as number;
    const control = code < 0x20 || (code >= 0x7f && code <= 0x9f);
    if (character === '\\' || character === ':' || control) {
      throw coverageError();
    }
  }
}

export function suiteReference(value: Node): void {
  const reference = closed(value, 'version digest_profile digest', '');
  const digest = reference.digest;
  if (
    (reference.version !== 'ess-conformance/5' &&
      reference.version !== 'ess-conformance/7' &&
      reference.version !== 'ess-conformance/9' &&
      reference.version !== 'ess-conformance/11') ||
    reference.digest_profile !== 'sha256-json-bytes/1' ||
    typeof digest !== 'string' ||
    !digest.startsWith('sha256:') ||
    !modelDigest.test(digest.slice('sha256:'.length))
  ) {
    throw coverageError();
  }
}

export function referenceFor(suite: Suite): { [key: string]: Node } {
  return {
    version: suite.provenance.suite_version,
    digest_profile: 'sha256-json-bytes/1',
    digest: originalDigest(suite.original),
  };
}

export function orderedIDs(value: Node): string[] {
  const values = array(value);
  const result: string[] = [];
  for (const item of values) {
    const id = text(item);
    scenarioIdentity(id);
    if (result.length > 0 && !goLess(itemAt(result, result.length - 1), id)) {
      throw coverageError();
    }
    result.push(id);
  }
  return result;
}

const SEMANTIC_KINDS = [
  'domain',
  'type',
  'entity',
  'command',
  'outcome',
  'event',
  'error',
  'view',
  'actor',
  'transition',
  'binding',
  'component',
];

export function semanticKey(value: Node): string {
  if (isNil(value)) {
    return '';
  }
  const reference = value as { [key: string]: Node };
  let rank = 0;
  for (let index = 0; index < SEMANTIC_KINDS.length; index += 1) {
    if (reference.kind === SEMANTIC_KINDS[index]) {
      rank = index;
      break;
    }
  }
  let label: string;
  if (typeof reference.name === 'string') {
    label = reference.name;
  } else {
    const nested = reference.name as { [key: string]: Node };
    label =
      reference.kind === 'outcome'
        ? `${String(nested.command)}/${String(nested.outcome)}`
        : `${String(nested.entity)}/${String(nested.transition)}`;
  }
  return `${String(rank).padStart(2, '0')}:${label}`;
}

export function checkedNeeds(value: Node, required: boolean): void {
  const needs = array(value);
  if (required === (needs.length === 0)) {
    throw coverageError();
  }
  let previous = '';
  for (const need of needs) {
    admitReference(need);
    const key = semanticKey(need);
    if (goAtMost(key, previous)) {
      throw coverageError();
    }
    previous = key;
  }
}

export function nullableID(value: Node): void {
  if (isNil(value)) {
    return;
  }
  scenarioIdentity(text(value));
}

export function originIncludes(selection: { [key: string]: Node }, origin: Node): boolean {
  return selection.origins === 'generated_and_authored' || selection.origins === origin;
}

export function checkedSelection(
  value: Node,
  provenance: { [key: string]: Node },
): { [key: string]: Node } {
  const selection = closed(value, 'scope origins filter', '');
  switch (selection.origins) {
    case 'generated':
    case 'authored':
    case 'generated_and_authored':
      break;
    default:
      throw coverageError();
  }
  const scope = closed(selection.scope, 'kind', 'component');
  switch (scope.kind) {
    case 'system':
      if (Object.keys(scope).length !== 1 || !isNil(provenance.component)) {
        throw coverageError();
      }
      break;
    case 'component': {
      const component = scope.component;
      if (
        typeof component !== 'string' ||
        !kebabName.test(component) ||
        provenance.component !== component
      ) {
        throw coverageError();
      }
      break;
    }
    default:
      throw coverageError();
  }
  const filter = closed(selection.filter, 'kind', 'ids parent');
  switch (filter.kind) {
    case 'all':
      if (Object.keys(filter).length !== 1) {
        throw coverageError();
      }
      break;
    case 'explicit':
      orderedIDs(filter.ids);
      suiteReference(filter.parent);
      break;
    default:
      throw coverageError();
  }
  return selection;
}

export function checkedOutside(
  value: Node,
  selection: { [key: string]: Node },
): { [key: string]: Node } {
  const outside = closed(value, 'scenario origin reason needs', '');
  if (failed(() => nullableID(outside.scenario)) || isNil(outside.scenario)) {
    throw coverageError();
  }
  if (outside.origin !== 'generated' && outside.origin !== 'authored') {
    throw coverageError();
  }
  checkedNeeds(outside.needs, outside.reason === 'other_component');
  const scope = selection.scope as { [key: string]: Node };
  switch (outside.reason) {
    case 'other_component':
      if (scope.kind !== 'component' || !originIncludes(selection, outside.origin)) {
        throw coverageError();
      }
      break;
    case 'origin_selection':
      if (originIncludes(selection, outside.origin)) {
        throw coverageError();
      }
      break;
    case 'selection_filter':
      if (
        (selection.filter as { [key: string]: Node }).kind !== 'explicit' ||
        !originIncludes(selection, outside.origin)
      ) {
        throw coverageError();
      }
      break;
    default:
      throw coverageError();
  }
  return outside;
}

export function refusalKey(refusal: { [key: string]: Node }): string[] {
  const key = (value: Node): string => (isNil(value) ? '' : String(value));
  let retainedOrigin = '';
  let retainedSource = '';
  if (!isNil(refusal.retained)) {
    const retained = refusal.retained as { [key: string]: Node };
    retainedOrigin = key(retained.origin);
    retainedSource = key(retained.source);
  }
  const needs = (refusal.needs as Node[]).map(semanticKey);
  return [
    key(refusal.origin),
    key(refusal.source),
    semanticKey(refusal.subject),
    key(refusal.scenario),
    key(refusal.code),
    key(refusal.effect),
    retainedOrigin,
    retainedSource,
    key(refusal.scope),
    needs.join('\u0000'),
    key(refusal.message),
  ];
}

export function orderedRefusal(
  left: { [key: string]: Node },
  right: { [key: string]: Node },
): boolean {
  const first = refusalKey(left);
  const second = refusalKey(right);
  for (let index = 0; index < first.length; index += 1) {
    if (first[index] !== second[index]) {
      return goLess(itemAt(first, index), itemAt(second, index));
    }
  }
  return true;
}

export function checkedRefusal(
  value: Node,
  selection: { [key: string]: Node },
  sources: { [key: string]: Node },
  survivors: { [id: string]: string },
  owners: { [id: string]: string },
): { [key: string]: Node } {
  const refusal = closed(
    value,
    'origin scenario subject source code message effect retained scope needs',
    '',
  );
  nullableID(refusal.scenario);
  if (!isNil(refusal.subject)) {
    admitReference(refusal.subject);
  }
  const message = refusal.message;
  if (typeof message !== 'string' || message.trim() === '') {
    throw coverageError();
  }
  const code = refusal.code;
  if (typeof code !== 'string') {
    throw coverageError();
  }
  switch (refusal.origin) {
    case 'generated': {
      if (!isNil(refusal.source) || isNil(refusal.subject)) {
        throw coverageError();
      }
      let number = 0;
      for (let n = 1; n <= 15; n += 1) {
        if (code === `ESS-SYNTH-${String(n).padStart(3, '0')}`) {
          number = n;
        }
      }
      if (number === 0) {
        throw coverageError();
      }
      let effect = 'candidate_not_emitted';
      if (number === 5 || number === 11 || number === 12 || number === 14) {
        effect = 'check_not_emitted';
      }
      if (refusal.effect !== effect) {
        throw coverageError();
      }
      break;
    }
    case 'authored': {
      sourceIdentity(refusal.source);
      let valid = false;
      for (let n = 1; n <= 35; n += 1) {
        if (code === `ESS-AUTHOR-${String(n).padStart(3, '0')}`) {
          valid = true;
        }
      }
      if (!valid || refusal.effect !== 'candidate_not_emitted') {
        throw coverageError();
      }
      const source = sources[refusal.source as string];
      if (
        !isObject(source) ||
        source.disposition !== 'refused' ||
        !deepEqual(source.scenario, refusal.scenario)
      ) {
        throw coverageError();
      }
      break;
    }
    default:
      throw coverageError();
  }
  let retained: Node = undefined;
  const id = refusal.scenario;
  if (typeof id === 'string' && (survivors[id] ?? '') !== '') {
    const source: Node = (owners[id] ?? '') !== '' ? owners[id] : null;
    retained = { origin: survivors[id], source };
  }
  if (!isNil(refusal.retained)) {
    closed(refusal.retained, 'origin source', '');
  }
  if (!deepEqual(retained, refusal.retained)) {
    throw coverageError();
  }
  checkedNeeds(refusal.needs, refusal.scope === 'outside_component');
  switch (refusal.scope) {
    case 'in_scope':
      if (!originIncludes(selection, refusal.origin)) {
        throw coverageError();
      }
      break;
    case 'outside_origin':
      if (originIncludes(selection, refusal.origin)) {
        throw coverageError();
      }
      break;
    case 'outside_component':
      if (
        (selection.scope as { [key: string]: Node }).kind !== 'component' ||
        !originIncludes(selection, refusal.origin)
      ) {
        throw coverageError();
      }
      break;
    default:
      throw coverageError();
  }
  return refusal;
}

export function admitCoverage(root: { [key: string]: Node }): void {
  const coverage = closed(
    root.coverage,
    'selection knowledge generated authored outside refused authored_sources counts',
    '',
  );
  const selection = checkedSelection(
    coverage.selection,
    root.provenance as { [key: string]: Node },
  );
  if (coverage.knowledge !== 'unknown' && coverage.knowledge !== 'complete_inventory') {
    throw coverageError();
  }
  const counts = closed(coverage.counts, 'generated authored outside refused', '');
  for (const label of ['generated', 'authored', 'outside', 'refused']) {
    const count = unsigned(counts[label]);
    const values = array(coverage[label]);
    if (count !== BigInt(values.length)) {
      throw coverageError();
    }
  }
  const survivors: { [id: string]: string } = {};
  for (const origin of ['generated', 'authored']) {
    const ids = orderedIDs(coverage[origin]);
    if (ids.length > 0 && !originIncludes(selection, origin)) {
      throw coverageError();
    }
    for (const id of ids) {
      if ((survivors[id] ?? '') !== '') {
        throw coverageError();
      }
      survivors[id] = origin;
    }
  }
  const scenarios = root.scenarios as { [key: string]: Node };
  if (Object.keys(survivors).length !== Object.keys(scenarios).length) {
    throw coverageError();
  }
  for (const id of Object.keys(scenarios)) {
    if ((survivors[id] ?? '') === '') {
      throw coverageError();
    }
  }
  const filter = selection.filter as { [key: string]: Node };
  if (filter.kind === 'explicit') {
    const ids = orderedIDs(filter.ids);
    if (ids.length !== Object.keys(scenarios).length) {
      throw coverageError();
    }
    for (const id of ids) {
      if (!Object.prototype.hasOwnProperty.call(scenarios, id)) {
        throw coverageError();
      }
    }
  }
  let previous = '';
  for (const value of coverage.outside as Node[]) {
    const outside = checkedOutside(value, selection);
    const id = outside.scenario as string;
    if (goAtMost(id, previous) || (survivors[id] ?? '') !== '') {
      throw coverageError();
    }
    previous = id;
    survivors[id] = outside.origin as string;
  }
  const sources = coverage.authored_sources;
  if (!isObject(sources)) {
    throw coverageError();
  }
  const owners: { [id: string]: string } = {};
  for (const identity of Object.keys(sources)) {
    sourceIdentity(identity);
    const source = closed(sources[identity], 'digest scenario disposition', '');
    const digest = source.digest;
    if (
      typeof digest !== 'string' ||
      !digest.startsWith('sha256:') ||
      !modelDigest.test(digest.slice('sha256:'.length))
    ) {
      throw coverageError();
    }
    nullableID(source.scenario);
    switch (source.disposition) {
      case 'accepted': {
        const id = source.scenario;
        if (typeof id !== 'string' || survivors[id] !== 'authored' || (owners[id] ?? '') !== '') {
          throw coverageError();
        }
        owners[id] = identity;
        break;
      }
      case 'refused':
        break;
      default:
        throw coverageError();
    }
  }
  for (const id of Object.keys(survivors)) {
    if (survivors[id] === 'authored' && (owners[id] ?? '') === '') {
      throw coverageError();
    }
  }
  const refusedSources: { [source: string]: boolean } = {};
  let previousRefusal: { [key: string]: Node } | undefined;
  for (const value of coverage.refused as Node[]) {
    const refusal = checkedRefusal(value, selection, sources, survivors, owners);
    if (previousRefusal !== undefined && !orderedRefusal(previousRefusal, refusal)) {
      throw coverageError();
    }
    previousRefusal = refusal;
    if (!isNil(refusal.source)) {
      refusedSources[refusal.source as string] = true;
    }
  }
  for (const identity of Object.keys(sources)) {
    if (
      (sources[identity] as { [key: string]: Node }).disposition === 'refused' &&
      refusedSources[identity] !== true
    ) {
      throw coverageError();
    }
  }
}

export function completeCoverage(coverage: { [key: string]: Node } | undefined): boolean {
  if (coverage === undefined || coverage.knowledge !== 'complete_inventory') {
    return false;
  }
  for (const value of coverage.refused as Node[]) {
    if ((value as { [key: string]: Node }).scope === 'in_scope') {
      return false;
    }
  }
  return true;
}

export function admitRunInput(raw: string): Suite {
  const value = strictJSON(raw);
  if (!isObject(value)) {
    throw coverageError();
  }
  if (!Object.prototype.hasOwnProperty.call(value, 'format')) {
    return admitSuite(raw);
  }
  const input = closed(value, 'format suite_json parent_suites', '');
  if (input.format !== 'ess-conformance-input/1') {
    throw coverageError();
  }
  const original = text(input.suite_json);
  const selected = admitSuiteDocument(original, true);
  if (selected.coverage === undefined) {
    throw coverageError();
  }
  const parents = array(input.parent_suites);
  const seen: { [digest: string]: boolean } = { [originalDigest(original)]: true };
  let child = selected;
  for (const value_ of parents) {
    const document = text(value_);
    const parent = admitSuiteDocument(document, true);
    const digest = originalDigest(document);
    if (seen[digest] === true) {
      throw coverageError();
    }
    seen[digest] = true;
    admitParent(child, parent);
    child = parent;
  }
  const coverage = child.coverage as { [key: string]: Node };
  if (
    ((coverage.selection as { [key: string]: Node }).filter as { [key: string]: Node }).kind !==
    'all'
  ) {
    throw new Error('missing final parent');
  }
  return selected;
}

export function copyObject(value: { [key: string]: Node }): { [key: string]: Node } {
  const copy: { [key: string]: Node } = {};
  for (const key of Object.keys(value)) {
    copy[key] = value[key];
  }
  return copy;
}

export function admitParent(child: Suite, parent: Suite): void {
  if (parent.coverage === undefined) {
    throw coverageError();
  }
  const childCoverage = child.coverage as { [key: string]: Node };
  const selection = childCoverage.selection as { [key: string]: Node };
  const filter = selection.filter as { [key: string]: Node };
  if (filter.kind !== 'explicit' || !deepEqual(filter.parent, referenceFor(parent))) {
    throw coverageError();
  }
  const childProvenance = copyObject(child.document.provenance as { [key: string]: Node });
  const parentProvenance = copyObject(parent.document.provenance as { [key: string]: Node });
  // Present on both sides whether or not either wrote it: Go's `m[k] = m[k]` mints the key, and a
  // missing key and a null one are two different maps to a deep comparison.
  childProvenance.component = childProvenance.component ?? null;
  parentProvenance.component = parentProvenance.component ?? null;
  if (!deepEqual(childProvenance, parentProvenance)) {
    throw coverageError();
  }
  const expected = copyObject(parent.coverage);
  const selected = copyObject(parent.coverage.selection as { [key: string]: Node });
  selected.filter = filter;
  expected.selection = selected;
  const outside: Node[] = [...(parent.coverage.outside as Node[])];
  for (const origin of ['generated', 'authored']) {
    const ids: Node[] = [];
    for (const value of parent.coverage[origin] as Node[]) {
      const id = value as string;
      if (Object.prototype.hasOwnProperty.call(child.scenarios, id)) {
        ids.push(id);
      } else {
        outside.push({ scenario: id, origin, reason: 'selection_filter', needs: [] });
      }
    }
    expected[origin] = ids;
  }
  outside.sort((left, right) =>
    byteCompare(
      (left as { [key: string]: Node }).scenario as string,
      (right as { [key: string]: Node }).scenario as string,
    ),
  );
  expected.outside = outside;
  const counts = copyObject(parent.coverage.counts as { [key: string]: Node });
  for (const key of ['generated', 'authored', 'outside']) {
    counts[key] = new JsonNumber(String((expected[key] as Node[]).length));
  }
  expected.counts = counts;
  if (!deepEqual(expected, child.coverage)) {
    throw coverageError();
  }
  const parentScenarios = parent.document.scenarios as { [key: string]: Node };
  const childScenarios = child.document.scenarios as { [key: string]: Node };
  for (const id of Object.keys(childScenarios)) {
    const original = parentScenarios[id];
    if (
      !Object.prototype.hasOwnProperty.call(parentScenarios, id) ||
      !deepEqual(scenarioMeaning(childScenarios[id]), scenarioMeaning(original))
    ) {
      throw new Error('child changed full scenario semantics or dependencies');
    }
  }
}

// ---- the inherited semantics a child may not change ---------------------------------------------

export function meaningCombine(kind: string, children: Node[]): Node {
  if (children.length === 0) {
    return kind === 'all';
  }
  if (children.length === 1) {
    return children[0];
  }
  return [kind, children];
}

export function meaningNot(value: Node): Node {
  if (typeof value === 'boolean') {
    return !value;
  }
  if (Array.isArray(value) && value.length === 2 && value[0] === 'not') {
    return value[1];
  }
  return ['not', value];
}

export function meaningSequence(value: Node): Node[] {
  if (isNil(value)) {
    return [];
  }
  if (Array.isArray(value)) {
    return value;
  }
  return [value];
}

export function meaningScalar(value: Node): Node {
  if (typeof value !== 'string') {
    return nodeMeaning(value);
  }
  const raw = value.trim();
  if (raw.length >= 2 && (raw[0] === "'" || raw[0] === '"') && raw[raw.length - 1] === raw[0]) {
    return raw.slice(1, raw.length - 1);
  }
  if (raw === 'true') {
    return true;
  }
  if (raw === 'false') {
    return false;
  }
  if (meaningDecimal.test(raw)) {
    const digits = exactInteger(raw);
    if (digits !== null) {
      return new ExactNumber(digits);
    }
    const number = Number(raw);
    if (Number.isFinite(number)) {
      return number;
    }
  }
  return raw;
}

export function meaningOperand(value: Node): Node {
  if (typeof value === 'string') {
    const raw = value.trim();
    if (raw.includes('.') && factPath.test(raw)) {
      if (!Number.isFinite(Number(raw)) || raw.trim() === '') {
        return ['fact', raw];
      }
    }
  }
  return ['literal', meaningScalar(value)];
}

export const meaningOperators: { [written: string]: string } = {
  eq: '==',
  equals: '==',
  '==': '==',
  ne: '!=',
  not_equals: '!=',
  '!=': '!=',
  lt: '<',
  '<': '<',
  le: '<=',
  lte: '<=',
  '<=': '<=',
  gt: '>',
  '>': '>',
  ge: '>=',
  gte: '>=',
  '>=': '>=',
};

export function meaningLeaf(expression: string): Node {
  const raw = expression.trim();
  if (raw === 'true' || raw === 'always') {
    return true;
  }
  if (raw === 'false' || raw === 'never') {
    return false;
  }
  if (raw.startsWith('not ')) {
    return meaningNot(meaningLeaf(raw.slice('not '.length)));
  }
  for (const fn of ['defined', 'exists', 'missing']) {
    if (raw.startsWith(fn)) {
      const tail = raw.slice(fn.length).trim();
      if (tail.startsWith('(') && tail.endsWith(')')) {
        const value = ['defined', tail.slice(1, tail.length - 1).trim()];
        if (fn === 'missing') {
          return meaningNot(value);
        }
        return value;
      }
    }
  }
  let quote = '';
  for (let index = 0; index < raw.length; index += 1) {
    const character = raw[index];
    if (quote !== '') {
      if (character === quote) {
        quote = '';
      }
      continue;
    }
    if (character === "'" || character === '"') {
      quote = character;
      continue;
    }
    let operator = '';
    if (index + 1 < raw.length) {
      const pair = raw.slice(index, index + 2);
      if (pair === '==' || pair === '!=' || pair === '<=' || pair === '>=') {
        operator = pair;
      }
    }
    if (operator === '' && (character === '<' || character === '>')) {
      operator = character;
    }
    if (operator !== '') {
      return [
        'compare',
        raw.slice(0, index).trim(),
        operator,
        meaningOperand(raw.slice(index + operator.length)),
      ];
    }
  }
  return ['truthy', raw];
}

export function predicateMeaning(value: Node): Node {
  if (typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'string') {
    return meaningLeaf(value);
  }
  if (Array.isArray(value)) {
    return meaningCombine('all', value.map(predicateMeaning));
  }
  if (isObject(value)) {
    const children = meaningKeys(value).map((key) => meaningEntry(key, value[key]));
    return meaningCombine('all', children);
  }
  throw new Error('predicate meaning requires prior typed admission');
}

export function meaningEntry(key: string, value: Node): Node {
  switch (key) {
    case 'all':
    case 'and':
    case 'all_of':
    case 'any':
    case 'or':
    case 'none':
    case 'none_of_these': {
      const children = meaningSequence(value).map(predicateMeaning);
      const kind = key === 'all' || key === 'and' || key === 'all_of' ? 'all' : 'any';
      const result = meaningCombine(kind, children);
      if (key === 'none' || key === 'none_of_these') {
        return meaningNot(result);
      }
      return result;
    }
    case 'not':
      return meaningNot(predicateMeaning(value));
    case 'forall':
    case 'exists': {
      const body = value as { [key: string]: Node };
      return [key, body.in, body.as, predicateMeaning(body.that)];
    }
    default:
      break;
  }
  if (Array.isArray(value)) {
    return ['any_of', key, value.map(meaningScalar)];
  }
  if (isObject(value)) {
    const children = meaningKeys(value).map((operator) =>
      meaningOperator(key, operator, value[operator]),
    );
    return meaningCombine('all', children);
  }
  return ['compare', key, '==', ['literal', meaningScalar(value)]];
}

export function meaningOperator(path: string, operator: string, value: Node): Node {
  const mapped = meaningOperators[operator];
  if (mapped !== undefined) {
    return ['compare', path, mapped, meaningOperand(value)];
  }
  switch (operator) {
    case 'defined':
    case 'exists': {
      const result = ['defined', path];
      if (value !== true) {
        return meaningNot(result);
      }
      return result;
    }
    case 'truthy':
      return ['truthy', path];
    default: {
      const kind = operator === 'none_of' || operator === 'not_in' ? 'none_of' : 'any_of';
      return [kind, path, meaningSequence(value).map(meaningScalar)];
    }
  }
}

export function rankingMeaning(value: Node): Node {
  return (value as Node[]).map((item) => {
    const words = goFields(item as string);
    const direction =
      words.length === 2 && (words[1] === 'desc' || words[1] === 'descending') ? 'desc' : 'asc';
    return [words[0], direction];
  });
}

const STEP_DEFAULTS: { [step: string]: string } = {
  execute_command: 'input',
  expect_error: 'fields',
  expect_event: 'payload shape',
  query_view: 'params',
  eventually_view: 'params',
  eventually_event: 'payload shape',
  expect_invocation: 'input',
  expect_duration: '',
  expect_halt: 'params',
  eventually_halt: 'params',
};

/** Integer metadata and original source strings never pass through this semantic comparison. */
export function scenarioMeaning(value: Node): Node {
  const scenario = copyObject(value as { [key: string]: Node });
  const source: { [key: string]: boolean } = {};
  for (const reference of scenario.source as Node[]) {
    source[semanticKey(reference)] = true;
  }
  scenario.source = source;
  const steps: Node[] = [];
  for (const raw of scenario.steps as Node[]) {
    const step = copyObject(raw as { [key: string]: Node });
    for (const key of goFields(STEP_DEFAULTS[step.step as string] ?? '')) {
      if (!Object.prototype.hasOwnProperty.call(step, key)) {
        step[key] = {};
      }
    }
    if (step.step === 'execute_command' && !Object.prototype.hasOwnProperty.call(step, 'actor')) {
      step.actor = null;
    }
    for (const key of ['input', 'params']) {
      if (isObject(step[key])) {
        step[key] = valuesMeaning(step[key] as { [key: string]: Node });
      }
    }
    for (const key of ['payload', 'fields']) {
      if (Object.prototype.hasOwnProperty.call(step, key)) {
        step[key] = nodeMeaning(step[key]);
      }
    }
    if (isObject(step.shape)) {
      const shapes: { [key: string]: Node } = {};
      for (const key of Object.keys(step.shape)) {
        const leaf = copyObject(
          (step.shape as { [key: string]: Node })[key] as { [key: string]: Node },
        );
        if (!Object.prototype.hasOwnProperty.call(leaf, 'optional')) {
          leaf.optional = false;
        }
        shapes[key] = leaf;
      }
      step.shape = shapes;
    }
    if (isObject(step.expectation)) {
      const expected = copyObject(step.expectation as { [key: string]: Node });
      switch (expected.expect) {
        case 'contains':
        case 'absent':
        case 'at':
          if (!Object.prototype.hasOwnProperty.call(expected, 'fields')) {
            expected.fields = {};
          }
          break;
        case 'counts':
          if (!Object.prototype.hasOwnProperty.call(expected, 'at_least')) {
            expected.at_least = null;
          }
          if (!Object.prototype.hasOwnProperty.call(expected, 'at_most')) {
            expected.at_most = null;
          }
          break;
        default:
          break;
      }
      if (isObject(expected.fields)) {
        expected.fields = valuesMeaning(expected.fields as { [key: string]: Node });
      }
      if (Object.prototype.hasOwnProperty.call(expected, 'predicate')) {
        expected.predicate = predicateMeaning(expected.predicate);
      }
      if (Object.prototype.hasOwnProperty.call(expected, 'order_by')) {
        expected.order_by = rankingMeaning(expected.order_by);
      }
      step.expectation = expected;
    }
    steps.push(step);
  }
  scenario.steps = steps;
  return scenario;
}

export function valuesMeaning(values: { [key: string]: Node }): Node {
  const result: { [key: string]: Node } = {};
  for (const label of Object.keys(values)) {
    const field = copyObject(values[label] as { [key: string]: Node });
    if (field.kind === 'literal') {
      field.value = nodeMeaning(field.value);
    }
    result[label] = field;
  }
  return result;
}

/**
 * exactInteger returns the canonical digits of an integer token binary64 cannot hold exactly.
 *
 * Binary64 collapses every integer above 2^53, so 9007199254740992 and 9007199254740993 were one
 * value here and two in the Rust admitter: a child scenario that swapped one for the other would
 * compare equal in this runtime and unequal in that one, and the generated suite would admit a
 * lineage the other refuses.
 */
export function exactInteger(raw: string): string | null {
  let body = raw;
  let negative = false;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    body = body.slice(1);
    negative = true;
  }
  // An integer written with a fractional part of zeroes is the same integer.
  const dot = body.indexOf('.');
  if (dot >= 0) {
    if (body.slice(dot + 1).replace(/0/g, '') !== '') {
      return null;
    }
    body = body.slice(0, dot);
  }
  if (body === '') {
    return null;
  }
  for (const character of body) {
    if (character < '0' || character > '9') {
      return null;
    }
  }
  const number = Number(raw);
  // A token no binary64 holds keeps whatever answer this runtime already gave it, and a token
  // binary64 holds exactly needs no digits kept.
  if (
    Number.isNaN(number) ||
    !Number.isFinite(number) ||
    (number === Math.trunc(number) && Math.abs(number) <= 9007199254740991)
  ) {
    return null;
  }
  body = body.replace(/^0+/, '');
  if (body === '') {
    body = '0';
  }
  if (negative && body !== '0') {
    return `-${body}`;
  }
  return body;
}

export function nodeMeaning(value: Node): Node {
  if (value instanceof JsonNumber) {
    const digits = exactInteger(value.raw);
    if (digits !== null) {
      return new ExactNumber(digits);
    }
    return Number(value.raw);
  }
  if (Array.isArray(value)) {
    return value.map(nodeMeaning);
  }
  if (isObject(value)) {
    const result: { [key: string]: Node } = {};
    for (const key of Object.keys(value)) {
      result[key] = nodeMeaning(value[key]);
    }
    return result;
  }
  return value;
}

/** goFields splits on runs of whitespace, the way `strings.Fields` does. */
export function goFields(value: string): string[] {
  const trimmed = value.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(/\s+/u);
}

// ---- what an implementation offers --------------------------------------------------------------

/** Answer is a value a target may hand back directly or in a promise. */
export type Answer<T> = T | Promise<T>;

/**
 * Target is an implementation a conformance suite can be run against.
 *
 * Every method answers a question some ESS construct asks. There is no assertion among them and no
 * reset beyond the isolation ScenarioContext requires: a target reports what it observed, and the
 * runner decides whether the specification is satisfied. A method that answered a question the
 * suite is supposed to ask would make the suite ask the implementation for its own verdict.
 *
 * Every method may return a promise, and every method may throw `ErrUnsupported` — or anything
 * `unsupported()` built — for a semantic the implementation does not expose. That scenario is
 * reported as skipped, which is a different fact from a failed one.
 */
export interface Target {
  /** Identity names the implementation under test, for the report. */
  identity(): Answer<Identity>;

  /**
   * beginScenario and endScenario bracket each scenario. Observations from one scenario may not
   * satisfy another, and this is where a target makes that true.
   */
  beginScenario(scenario: ScenarioContext): Answer<void>;
  endScenario(scenario: ScenarioContext): Answer<void>;

  /**
   * executeCommand invokes one command and reports the branch it took, the error it declared and
   * the events it emitted directly.
   *
   * Throw ErrUnsupported where the implementation offers no way to invoke it — a command whose
   * actor is the implementation itself has no caller a target can be.
   */
  executeCommand(request: CommandRequest): Answer<CommandResult>;

  /**
   * queryView reads one view at the consistency the request demands. A read_your_writes view must
   * show the command that just returned, and the target blocks until it can.
   */
  queryView(request: ViewRequest): Answer<ViewResult>;

  /**
   * observeEvents reports the events seen for this activity, away from the command that caused
   * them, until the deadline.
   */
  observeEvents(request: EventObservationRequest): Answer<ObservedEvent[]>;

  /** configureExternalOutcome forces an outcome declared `external:` to take a named branch. */
  configureExternalOutcome(control: ExternalOutcomeControl): Answer<void>;

  /**
   * redeliverEvent delivers an event a second time. The only way to perform the claim
   * `delivery: at_least_once` makes.
   */
  redeliverEvent(request: RedeliveryRequest): Answer<void>;

  /**
   * observeInvocations reports the commands one binding invoked and what it passed.
   *
   * Throw ErrUnsupported where the implementation cannot expose this; the scenario is reported as
   * unsupported rather than failed, which is a different fact.
   */
  observeInvocations(request: InvocationObservationRequest): Answer<Invocation[]>;
}

/**
 * EntitySetupTarget validates fixture values against the actual entity contract and establishes
 * them in the backend read by queryView. Success guarantees durable, read-visible state in this
 * isolated scenario. Throw ErrUnsupported if either validation or establishment is unavailable.
 * Setup does not manufacture a command, lifecycle transition, event, or history.
 */
export interface EntitySetupTarget {
  establishEntity(request: EntitySetupRequest): Answer<void>;
}

/** EntitySetupRequest is literal fixture state, not a trusted model-validation certificate. */
export interface EntitySetupRequest {
  entity: string;
  identity: Node;
  fields: { [field: string]: Node };
  state: string;
  correlation: string;
}

/** Identity names the implementation under test. */
export interface Identity {
  name: string;
  version: string;
}

/** ScenarioContext is what a target is told about the scenario it is bracketing. */
export interface ScenarioContext {
  /** The scenario id, as the suite writes it. */
  scenario: string;
  /** This run's activity id, minted by the runner. */
  correlation: string;
}

/** CommandRequest is one command invocation. */
export interface CommandRequest {
  command: string;
  actor: string;
  input: { [field: string]: Node };
  correlation: string;
}

/** CommandResult is what one command did. */
export interface CommandResult {
  /** The actual returned, declared command response. */
  response?: { [field: string]: Node } | undefined;
  /** The branch it took, empty when it refused. */
  outcome?: string | undefined;
  /** The declared error it refused with, empty when it did not. */
  error?: string | undefined;
  /** A token a later read_your_writes query may demand, empty when the target has no such token. */
  consistency?: string | undefined;
  /** The events emitted as part of the command returning. */
  directEvents?: ObservedEvent[] | undefined;
}

/** ObservedEvent is one event and what it carried. */
export interface ObservedEvent {
  event: string;
  payload: { [field: string]: Node };
}

/** EventObservationRequest asks for the events of one activity. */
export interface EventObservationRequest {
  event: string;
  correlation: string;
  deadline: Deadline;
}

/** RedeliveryRequest asks for one event to be delivered again. */
export interface RedeliveryRequest {
  event: string;
  correlation: string;
}

/** ViewRequest reads one view. */
export interface ViewRequest {
  view: string;
  /**
   * The value bound to each parameter the view declares, resolved.
   *
   * Empty for a view with no `params:`, which is most of them. A view that declares them is one
   * the implementation cannot answer without them, and the runner refuses to send a request with a
   * parameter it could not resolve rather than reading a different set of rows.
   */
  params: { [parameter: string]: Node };
  /** The consistency token the read must reflect, empty for a current read. */
  atLeast: string;
  correlation: string;
  deadline: Deadline;
}

/** ViewResult is what a view holds. */
export interface ViewResult {
  rows?: Row[] | undefined;
}

/** InvocationObservationRequest asks what one binding invoked. */
export interface InvocationObservationRequest {
  binding: string;
  command: string;
  correlation: string;
  deadline: Deadline;
}

/** Invocation is one command a binding invoked, and what it passed. */
export interface Invocation {
  command: string;
  input: { [field: string]: Node };
}

/** ExternalOutcomeControl forces an external outcome to a branch. */
export interface ExternalOutcomeControl {
  command: string;
  outcome: string;
  correlation: string;
}

/**
 * Clock is what a target offers so that a scenario can claim a length of time.
 *
 * Optional, and separate from Target on purpose. A duration claim is a claim about a system's own
 * timers, and plenty of implementations have none worth testing. A target that has a clock
 * implements these two methods and one that does not is *skipped* on the scenarios that need them.
 * Never passed: a window nobody held is not a window that held.
 *
 * Discovered by method presence — see `isClock`. There is no interface at run time to assert
 * against, so a target that names both methods has a clock and a target that names neither has
 * none. A target that names one of them is a target with a defect, and it is reported as failing
 * the scenario rather than skipping it.
 */
export interface Clock {
  /** Records the instant this scenario has reached, under a name a later claim measures from. */
  markInstant(mark: InstantMark): Answer<void>;

  /**
   * Lets a window close and reports what the clock read, and what was published while it was open.
   *
   * It reports an observation and never a verdict: whether the reading satisfies the claim is the
   * runner's decision, made against the suite.
   */
  observeElapsed(request: ElapsedRequest): Answer<ElapsedObservation>;
}

/**
 * OrderedReader is what a target offers so that a scenario can claim a consumer stopped a scan.
 *
 * `produced` is the *source's* count and not the reader's. A target that reports how many rows it
 * handed on answers `stopAfter` whatever it did, which makes every implementation halt and the
 * claim mean nothing. A target whose only ordered read returns an array answers its length and
 * `false`, which is a red scenario and is the finding.
 */
export interface OrderedReader {
  /**
   * Reads a view in its declared order, hands rows to a reader that takes `stopAfter` of them and
   * then says stop, and reports what the iteration did.
   */
  scanView(request: ScanRequest): Answer<ScanObservation>;
}

/** ScanRequest asks for a bounded ordered read of one view. */
export interface ScanRequest {
  view: string;
  params: { [parameter: string]: Node };
  /** How many rows the reader takes before it says stop. Never zero. */
  stopAfter: number;
  /** The consistency token a read_your_writes read demands, empty when there is none. */
  atLeast: string;
  correlation: string;
  deadline: Deadline;
}

/** ScanObservation is what one ordered read did, as the target that performed it saw it. */
export interface ScanObservation {
  /** How many rows the ordered source yielded before the read ended. */
  produced?: number | undefined;
  /**
   * Whether the read ended because the reader said stop, rather than because the source ran out.
   * Both facts are needed: a source holding exactly `stopAfter` rows produces `stopAfter` either
   * way.
   */
  halted?: boolean | undefined;
}

/** InstantMark names the instant a scenario has reached. */
export interface InstantMark {
  instant: string;
  correlation: string;
}

/** ElapsedRequest asks how much of a window has closed, and what happened in it. */
export interface ElapsedRequest {
  /** The name of the instant the window opens at, marked earlier in this scenario. */
  instant: string;
  /** How many seconds of the window to let close before answering. Zero asks for the reading as it stands. */
  hold: number;
  /** The event whose publication inside the window the runner is asking about, empty when there is none. */
  watching?: string | undefined;
  correlation: string;
}

/** ElapsedObservation is what a clock read, and what it saw. */
export interface ElapsedObservation {
  /** How much has passed since the marked instant, on the target's own clock. */
  elapsedMillis?: number | undefined;
  /** How many times the watched event was published inside the window. */
  published?: number | undefined;
}

/**
 * Deadline is when the target may stop waiting, on the runner's clock.
 *
 * A budget rather than an instant, and there is no poll interval: a poll interval is a fixed delay
 * spelled as configuration, which is the same test of the machine it runs on repeated in a loop.
 */
export interface Deadline {
  /** How many more times the runner will ask. */
  attempts: number;
}

// ---- discovering what a target offers ----------------------------------------------------------

function method(target: unknown, ...names: string[]): boolean {
  if (target === null || typeof target !== 'object') {
    return false;
  }
  return names.every((label) => typeof (target as Record<string, unknown>)[label] === 'function');
}

/** isClock reports whether a target offers both halves of the clock. */
export function isClock(target: Target): target is Target & Clock {
  return method(target, 'markInstant', 'observeElapsed');
}

/** isOrderedReader reports whether a target can read a listing a row at a time. */
export function isOrderedReader(target: Target): target is Target & OrderedReader {
  return method(target, 'scanView');
}

/** isEntitySetupTarget reports whether a target can validate and establish fixture state. */
export function isEntitySetupTarget(target: Target): target is Target & EntitySetupTarget {
  return method(target, 'establishEntity');
}

/** isPeriodicTarget reports whether a target can open, observe and close a periodic host. */
export function isPeriodicTarget(target: Target): target is Target & PeriodicTarget {
  return method(target, 'openPeriodic', 'observePeriodic', 'closePeriodic');
}

/**
 * isClockReadingTarget reports whether a target can observe the evidence behind a clock reading.
 *
 * The interface itself is declared beside the reading accessor that uses it, so this answers with
 * a boolean rather than narrowing: there is one declaration of that capability and it is not here.
 */
export function isClockReadingTarget(target: Target): boolean {
  return method(target, 'observeClockReading');
}

// ---- the harness ----------------------------------------------------------------------------------

/**
 * Harness owns every source of variation: the ids handed to a target, and how many times an
 * `eventually` step asks before giving up.
 *
 * Constructed per run, so "the same runner produces the same report" is not a discipline anybody
 * has to keep — two identically-constructed harnesses cannot diverge.
 */
export class Harness {
  private readonly system: string;
  private sequence = 0;
  private readonly attempts = 8;

  constructor(system: string) {
    this.system = reduce(system);
  }

  /** correlation mints the next activity id. */
  correlation(): string {
    this.sequence += 1;
    return `${this.system}-${String(this.sequence).padStart(6, '0')}`;
  }

  /** deadline is the budget an `eventually` step is given. */
  deadline(): Deadline {
    return { attempts: this.attempts };
  }
}

/** newHarness returns the harness a run uses, seeded from the specification's own system name. */
export function newHarness(system: string): Harness {
  return new Harness(system);
}

/** reduce turns a system name into something usable as an identifier segment. */
export function reduce(system: string): string {
  const parts: string[] = [];
  let current = '';
  for (const character of system) {
    const alphanumeric =
      (character >= 'a' && character <= 'z') ||
      (character >= 'A' && character <= 'Z') ||
      (character >= '0' && character <= '9');
    if (alphanumeric) {
      current += character;
    } else if (current !== '') {
      parts.push(current);
      current = '';
    }
  }
  if (current !== '') {
    parts.push(current);
  }
  if (parts.length === 0) {
    return 'ess';
  }
  return parts.join('-');
}

// ---- the suite ---------------------------------------------------------------------------------------

/** Suite is a synthesized conformance suite. */
export interface Suite {
  provenance: Provenance;
  scenarios: { [id: string]: Scenario };
  /** The exact bytes the suite was admitted from, which is what its digest is taken over. */
  original: string;
  /** The admitted document, with every number still the digits it was written with. */
  document: { [key: string]: Node };
  /** The coverage inventory, for the suite versions that carry one. */
  coverage?: { [key: string]: Node };
}

/**
 * Provenance says which specification this suite came from.
 *
 * `spec_digest` is the field that makes a passing run worth anything: without it a report says
 * that some implementation passed some suite.
 */
export interface Provenance {
  suite_version: string;
  system: string;
  specification_version: string;
  spec_digest: string;
  contract_digest: string;
}

/** Scenario is one thing the specification obliges an implementation to do. */
export interface Scenario {
  purpose: string;
  steps: Step[];
}

/**
 * Step is one step of a scenario. Which fields are set depends on `step`.
 *
 * Named as the suite document names them, because the document is what a step is decoded from and
 * a second spelling would be a second place for the two to disagree.
 */
export interface Step {
  response?: ResponseObservation;
  check?: PeriodicCheck;
  left?: ReadingReference;
  right?: ReadingReference;
  order: string;
  identity: Node;
  fields?: { [field: string]: Node };
  state: string;
  step: string;
  command: string;
  actor: string;
  input?: { [field: string]: Value };
  outcome?: OutcomeRef;
  force?: OutcomeRef;
  event: string;
  /**
   * Plain values, not Value: an event's fields are compared against what the specification
   * declared them to be, and there is nothing earlier in the scenario for them to refer to.
   */
  payload?: { [field: string]: Node };
  shape?: { [path: string]: Held };
  error: string;
  view: string;
  /** What the caller supplies for a view that declares `params:`. Value, not Node, because a
   * parameter may be the identity an earlier step captured. */
  subject?: { [field: string]: Value };
  params?: { [parameter: string]: Value };
  expectation?: Expectation;
  binding: string;
  instance: string;
  entity: string;
  field: string;
  /**
   * The window's anchor: the name a `mark_instant` step gave one instant of this scenario. Never
   * inferred from the step before it — a window whose start moves when something is inserted above
   * it is the defect these four steps were added to fix.
   */
  instant: string;
  /** A length of time in whole seconds. */
  elapsed: number;
  /** How many rows a reader takes from an ordered view before it says stop. Never zero. */
  after: number;
}

/**
 * Held is what one declared payload field must hold.
 *
 * Separate from a value match because the two are different kinds of claim, and only one of them
 * is free: a value is assertable only where some construct says where it comes from, and a type is
 * declared outright.
 */
export interface Held {
  holds: string;
  kind?: string;
  /** The closed set of names an `enum` leaf admits, in declaration order. */
  variants?: string[];
  /** Whether the declaration permits the path to carry nothing. It excuses absence, not the value. */
  optional?: boolean;
}

/** OutcomeRef names one branch of one command. */
export interface OutcomeRef {
  command: string;
  outcome: string;
}

/** Value is one value a step carries: written down, captured earlier, or read from an event. */
export interface Value {
  selection?: SelectionObservation;
  accessor?: AccessorObservation;
  kind: string;
  value?: Node;
  instance?: string;
  event?: string;
  field?: string;
}

/**
 * Expectation is what must hold of a view.
 *
 * `at_least` and `at_most` are optional because absent and zero are different answers: a floor of
 * zero requires nothing, and a suite that wrote neither bound is asking nothing at all — which is
 * a generator defect this runner reports rather than passes.
 */
export interface Expectation {
  expect: string;
  fields?: { [field: string]: Value };
  predicate?: Node;
  order_by?: string[];
  at_least?: number;
  at_most?: number;
  position?: Position;
}

/**
 * Position is which row of a view an assertion is about.
 *
 * `last` is not `nth` at any number a suite could write, because the count is the target's — which
 * is why the three cases are three and not one with an index.
 */
export interface Position {
  row: string;
  index: number;
}

// ---- running -----------------------------------------------------------------------------------

/**
 * TestScope is the part of a test context this runner uses.
 *
 * `node:test`'s own `TestContext` satisfies it. Narrowed to three members so the runner can be
 * driven by something else — which is how this file's own cases watch a deliberately failing
 * scenario fail without failing the case that is watching.
 */
export interface TestScope {
  test(name: string, fn: (t: TestScope) => void | Promise<void>): Promise<unknown>;
  diagnostic(message: string): void;
  skip(message?: string): void;
}

/** A scenario has ended skipped: the target could not answer the question. */
class SkipSignal extends Error {}

/** A scenario has ended without reaching its last step. */
class FatalSignal extends Error {}

/**
 * suiteDocument reads the suite beside this module.
 *
 * A file rather than a string constant, for the reason the Go package embeds one: a generated
 * purpose reads `` `acd.backend.ConnectAgent` answers `requested` `` and stays diffable as a file,
 * where a constant would be one unreadable escaped line.
 *
 * `../` reaches the package root from `src/` before compilation and from `dist/` after it, so the
 * one specifier works whether the package is read where it was written or where it was built.
 */
export function suiteDocument(): string {
  return readFileSync(new URL('../suite.json', import.meta.url), 'utf8');
}

/**
 * run executes every scenario of the suite beside this module against a freshly built target.
 *
 * One target per scenario, because scenario isolation is the suite's own requirement and a shared
 * target makes it the adopter's discipline instead.
 */
export function run(t: TestScope, newTarget: () => Target): Promise<void> {
  return runWith(t, newTarget, suiteDocument());
}

/** runWith is `run` against a suite document handed over rather than read from disk. */
export async function runWith(
  t: TestScope,
  newTarget: () => Target,
  suiteJSON: string,
): Promise<void> {
  const config = reportConfiguration();
  let suite: Suite;
  try {
    suite = admitRunInput(suiteJSON);
  } catch (error) {
    throw new Error(`suite admission: ${errorText(error)}`);
  }
  const version = suite.provenance.suite_version;
  if (
    (version === 'ess-conformance/8' ||
      version === 'ess-conformance/9' ||
      version === 'ess-conformance/10' ||
      version === 'ess-conformance/11') &&
    config.version !== '2'
  ) {
    throw new Error('suite/8 and /9 require explicit ESS_REPORT_FORMAT=2 before execution');
  }
  if (
    (version === 'ess-conformance/5' ||
      version === 'ess-conformance/6' ||
      version === 'ess-conformance/7') &&
    config.version !== '2'
  ) {
    throw new Error('suite/5, /6 and /7 require explicit ESS_REPORT_FORMAT=2 before execution');
  }
  try {
    suite = executionSuite(suite);
  } catch (error) {
    throw new Error(`suite execution adaptation: ${errorText(error)}`);
  }

  // Sorted, so the order scenarios run in is the order they are written in the report, on every
  // machine.
  const ids = sortStrings(Object.keys(suite.scenarios));

  t.diagnostic(
    `${suite.provenance.system} ${suite.provenance.specification_version}, ${ids.length} scenario(s), ` +
      `spec digest ${suite.provenance.spec_digest}`,
  );

  // One extra target, for the name the report carries. Asked before any scenario runs so a target
  // that cannot name itself fails the run here, with that message, rather than leaving a report
  // that says nothing about what was tested.
  let identity: Identity;
  try {
    identity = normalizeIdentity(await newTarget().identity());
  } catch (error) {
    throw new Error(`the target does not name itself: ${errorText(error)}`);
  }

  const harness = newHarness(suite.provenance.system);
  const results: ScenarioResult[] = [];
  // How many scenarios actually ran to a conclusion. A name filter skips a subtest's body
  // entirely, so its status keeps the optimistic default; counting terminations is the only way
  // to tell a run that answered from one that was never asked.
  let terminated = 0;
  for (const id of ids) {
    const scenario = suite.scenarios[id] as Scenario;
    let status = statusPassed;
    let terminal = false;
    await t.test(id, async (subtest: TestScope) => {
      const scenarioRun = new ScenarioRun(subtest, newTarget(), harness, harness.correlation());
      let returned = false;
      let thrown: unknown;
      try {
        await scenarioRun.execute(id, scenario);
        returned = true;
      } catch (error) {
        thrown = error;
      }
      status = scenarioRun.status;
      terminal = scenarioRun.callbacksComplete && (returned || status !== statusPassed);
      if (config.version === '2' && scenarioRun.failures.length > 0) {
        status = statusFailed;
      }
      if (
        thrown !== undefined &&
        !(thrown instanceof SkipSignal) &&
        !(thrown instanceof FatalSignal)
      ) {
        throw thrown;
      }
      if (scenarioRun.failures.length > 0) {
        throw new Error(scenarioRun.failures.join('\n'));
      }
      if (thrown instanceof FatalSignal) {
        throw new Error(thrown.message);
      }
      if (thrown instanceof SkipSignal) {
        subtest.skip(thrown.message);
      }
    });
    if (terminal) {
      terminated += 1;
    }
    if (config.version === '1' || terminal) {
      results.push({ id, status });
    }
  }
  if (config.version === '2') {
    writeCountReport(t, suite, identity, results, terminated, config.strict);
  } else {
    writeReport(t, suite, identity, results, terminated);
  }
}

// ---- the report ---------------------------------------------------------------------------------

/** What one scenario came to, in the words the report uses. */
export const statusPassed = 'passed';
export const statusFailed = 'failed';
export const statusSkipped = 'skipped';

/** ScenarioResult is one scenario's verdict, for the report. */
export interface ScenarioResult {
  id: string;
  status: string;
}

/**
 * Report is `ess-conformance-report/1`: the closed document a conformance run publishes, and the
 * one `aep plan artifact evidence --from` reads. The same shape the Rust runner writes.
 *
 * The status vocabulary is the runner's: `passed` when every scenario passed, `failed` when any
 * failed, and `inconclusive` when none failed and some were skipped — a skipped scenario is one
 * the target could not answer, and a run that could not ask everything cannot say the
 * specification held.
 */
export interface Report {
  format: string;
  specification: string;
  spec_digest: string;
  implementation: string;
  status: string;
  scenarios_total: number;
  scenarios_failed: number;
  suite_version: string;
  failed_scenarios: string[];
  completed_at: number;
}

/**
 * accountForEveryScenario refuses a report for a run that did not reach every scenario the suite
 * holds.
 *
 * Name filtering is the ordinary way this happens, and it used to produce a document claiming the
 * scenarios that never ran had PASSED. Filtering without asking for a document is unaffected: no
 * `ESS_REPORT_OUT`, no document, nothing to be wrong. This refuses only the combination of a
 * partial run and a request to publish it.
 */
export function accountForEveryScenario(suite: Suite, terminated: number): Error | null {
  const held = Object.keys(suite.scenarios).length;
  if (terminated === held) {
    return null;
  }
  return new Error(
    `incomplete execution: ${terminated} of ${held} scenarios reached a conclusion, so this run ` +
      `cannot say what the other ${held - terminated} came to. A name filter is the usual cause — ` +
      'drop it to publish a document, or unset ESS_REPORT_OUT to filter without publishing one',
  );
}

/** reportNow is the one place in this file that knows what time it is. */
export let reportNow: () => number = () => Date.now();

/** writeReport writes the run's report where ESS_REPORT_OUT names, and nowhere when it is unset. */
export function writeReport(
  t: TestScope,
  suite: Suite,
  identity: Identity,
  results: ScenarioResult[],
  terminated: number,
): void {
  const path = process.env.ESS_REPORT_OUT ?? '';
  if (path === '') {
    return;
  }
  const refusal = accountForEveryScenario(suite, terminated);
  if (refusal !== null) {
    throw new Error(`report/1 refused: ${refusal.message}`);
  }

  const failedScenarios: string[] = [];
  let anyFailed = false;
  let anySkipped = false;
  for (const result of results) {
    if (result.status === statusPassed) {
      continue;
    }
    if (result.status === statusFailed) {
      anyFailed = true;
    } else if (result.status === statusSkipped) {
      anySkipped = true;
    }
    failedScenarios.push(`${result.status} ${result.id}`);
  }
  let status = statusPassed;
  if (anyFailed) {
    status = statusFailed;
  } else if (anySkipped) {
    status = 'inconclusive';
  }

  const document: Report = {
    format: 'ess-conformance-report/1',
    specification: `${suite.provenance.system}/${suite.provenance.specification_version}`,
    spec_digest: suite.provenance.spec_digest,
    implementation: `${identity.name} ${identity.version}`,
    status,
    scenarios_total: results.length,
    scenarios_failed: failedScenarios.length,
    suite_version: suite.provenance.suite_version,
    failed_scenarios: failedScenarios,
    completed_at: reportNow(),
  };
  writeFileSync(path, `${JSON.stringify(document, null, 2)}\n`, 'utf8');
  t.diagnostic(
    `report: ${status}, ${results.length} scenario(s), ${failedScenarios.length} not passed, written to ${path}`,
  );
}

// ---- one scenario in flight -----------------------------------------------------------------------

function normalizeIdentity(identity: Identity | undefined): Identity {
  return { name: identity?.name ?? '', version: identity?.version ?? '' };
}

/**
 * ObservedCommandResult is a command result with every absent field filled with the zero the Go
 * runtime reads: the empty string, and no events.
 */
export interface ObservedCommandResult {
  response: { [field: string]: Node } | undefined;
  outcome: string;
  error: string;
  consistency: string;
  directEvents: ObservedEvent[];
}

function normalizeResult(result: CommandResult | undefined): ObservedCommandResult {
  return {
    response: result?.response,
    outcome: result?.outcome ?? '',
    error: result?.error ?? '',
    consistency: result?.consistency ?? '',
    directEvents: result?.directEvents ?? [],
  };
}

/** ScenarioRun is one scenario in flight, and everything it has bound. */
export class ScenarioRun {
  readonly t: TestScope;
  readonly target: Target;
  readonly harness: Harness;
  readonly correlation: string;

  /** What `capture_instance` bound, by name. */
  readonly instances: { [instance: string]: Node } = {};
  readonly established: EntitySetupRequest[] = [];
  /**
   * The instants `mark_instant` named, so a window measured from one nothing marked is a suite
   * defect rather than a measurement from whatever was in hand.
   */
  readonly marked: { [instant: string]: boolean } = {};
  /**
   * The events the last command published, by event name. Cleared per command, because every
   * `expect_no_event` is a claim about *that* invocation.
   */
  observed: { [event: string]: ObservedEvent[] } = {};
  /**
   * The events observed anywhere in this scenario so far, in the order they arrived.
   *
   * A second record rather than the same one, because the two answer different questions. A
   * negative event assertion asks what this command published; a value written `observed` asks
   * what some earlier step in this scenario published.
   */
  readonly seen: ObservedEvent[] = [];
  /** What the most recent command did, for the assertions that read it. */
  last: ObservedCommandResult = normalizeResult(undefined);
  lastCommand = '';
  snapshots = new Map<string, { identity: { [field: string]: Node }; row: string }>();
  /** The token the last command returned, for a read_your_writes query. */
  consistency = '';
  /** What the last query_view returned, for the expect_view after it. */
  lastView: Row[] = [];
  /** Which view lastView came from. */
  queried = '';
  /** What this scenario has come to so far: passed until a step fails or skips. */
  status: string = statusPassed;
  /** Every failed assertion, in the order they were recorded. */
  readonly failures: string[] = [];
  /**
   * Returned callbacks, independently of a provisional skip or failure. A throw inside teardown
   * cannot complete the earlier step's verdict.
   */
  callbacksComplete = false;

  constructor(t: TestScope, target: Target, harness: Harness, correlation: string) {
    this.t = t;
    this.target = target;
    this.harness = harness;
    this.correlation = correlation;
  }

  async execute(id: string, scenario: Scenario): Promise<void> {
    const context: ScenarioContext = { scenario: id, correlation: this.correlation };
    try {
      await this.target.beginScenario(context);
    } catch (error) {
      this.callbacksComplete = true; // begin returned; no teardown is required
      if (isUnsupported(error)) {
        this.skip(`the target does not support this scenario: ${errorText(error)}`);
      }
      this.status = statusFailed;
      throw new FatalSignal(`begin: ${errorText(error)}`);
    }
    try {
      if (scenario.purpose !== '') {
        this.t.diagnostic(scenario.purpose);
      }
      for (let index = 0; index < scenario.steps.length; index += 1) {
        if (!(await this.step(index, itemAt(scenario.steps, index)))) {
          return;
        }
      }
    } finally {
      let teardown: unknown;
      try {
        await this.target.endScenario(context);
      } catch (error) {
        teardown = error;
      }
      this.callbacksComplete = true;
      if (teardown !== undefined) {
        this.status = statusFailed;
        this.failures.push(`end: ${errorText(teardown)}`);
      }
    }
  }

  /**
   * step performs one step, reporting whether the scenario should continue.
   *
   * A failed assertion stops the scenario: the steps after it were written assuming this one held,
   * and running them produces a second failure about the first one's cause.
   */
  async step(index: number, step: Step): Promise<boolean> {
    switch (step.step) {
      case 'expect_response_payload':
        return expectResponsePayload(this, index, step);
      case 'check_periodic':
        return this.checkPeriodic(index, step);
      case 'expect_reading_order':
        return expectReadingOrder(this, index, step);
      case 'establish_entity':
        return this.establishEntity(index, step);
      case 'execute_command':
        return this.executeCommand(index, step);
      case 'expect_outcome':
        return this.expectOutcome(index, step);
      case 'snapshot_subject':
      case 'expect_subject_unchanged':
        return this.snapshotSubject(index, step);
      case 'expect_no_error':
        if (!this.lastCommand)
          return this.fail(index, 'no command preceded the no-error assertion');
        if (this.last.error) return this.fail(index, `unexpected error ${this.last.error}`);
        return true;
      case 'expect_error':
        return this.expectError(index, step);
      case 'expect_event':
        return this.expectEvent(index, step);
      case 'expect_no_event':
        return this.expectNoEvent(index, step);
      case 'eventually_event':
        return this.eventuallyEvent(index, step);
      case 'capture_instance':
        return this.captureInstance(index, step);
      case 'query_view':
        return this.queryView(index, step);
      case 'expect_view':
        return this.expectView(index, step, false);
      case 'eventually_view':
        return this.expectView(index, step, true);
      case 'expect_invocation':
        return this.expectInvocation(index, step);
      case 'redeliver_event':
        return this.redeliver(index, step);
      case 'configure_external_outcome':
        return this.configure(index, step);
      case 'mark_instant':
        return this.markInstant(index, step);
      case 'expect_not_before':
        return this.expectElapsed(index, step, false);
      case 'expect_within':
        return this.expectElapsed(index, step, true);
      case 'expect_quiet':
        return this.expectQuiet(index, step);
      case 'expect_halt':
        return this.expectHalt(index, step, false);
      case 'eventually_halt':
        return this.expectHalt(index, step, true);
      default:
        // A step this build does not know is a suite written by a newer generator. Reporting it as
        // a failure would blame the implementation for the tool's age.
        this.skip(
          `step ${index} is \`${step.step}\`, which this generated runner does not implement`,
        );
        return false;
    }
  }

  async executeCommand(index: number, step: Step): Promise<boolean> {
    const input = this.resolveAll(index, step.input);
    if (input === null) {
      return false;
    }
    let result: CommandResult;
    try {
      result = await this.target.executeCommand({
        command: step.command,
        actor: step.actor,
        input,
        correlation: this.correlation,
      });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(
          `step ${index}: the target does not expose \`${step.command}\`: ${errorText(error)}`,
        );
      }
      return this.fail(index, `executing \`${step.command}\`: ${errorText(error)}`);
    }
    let normalized = normalizeResult(result);
    if (normalized.response !== undefined && normalized.response !== null) {
      try {
        normalized = normalizeResult(snapshotResponseResult(normalized));
      } catch (error) {
        return this.fail(index, `response observation: ${errorText(error)}`);
      }
    }
    this.consistency = normalized.consistency;
    this.last = normalized;
    this.lastCommand = step.command;
    // Cleared, not accumulated. Every `expect_no_event` in a scenario is a claim about *this*
    // command.
    this.observed = {};
    for (const event of normalized.directEvents) {
      (this.observed[event.event] ??= []).push(event);
      this.remember(event);
    }
    return true;
  }

  /** remember records an occurrence for the whole scenario, without recording one twice. */
  remember(event: ObservedEvent): void {
    for (const held of this.seen) {
      if (held.event === event.event && equal(held.payload, event.payload)) {
        return;
      }
    }
    this.seen.push(event);
  }

  expectOutcome(index: number, step: Step): boolean {
    if (step.outcome === undefined) {
      return this.fail(index, 'the suite names no outcome, which is a generator defect');
    }
    if (this.last.outcome !== step.outcome.outcome) {
      return this.fail(
        index,
        `\`${step.outcome.command}\` took \`${orNone(this.last.outcome)}\`, and the specification ` +
          `says \`${step.outcome.outcome}\``,
      );
    }
    return true;
  }

  expectError(index: number, step: Step): boolean {
    if (this.last.error !== step.error) {
      return this.fail(
        index,
        `refused with \`${orNone(this.last.error)}\`, and the specification says \`${step.error}\``,
      );
    }
    return true;
  }

  expectEvent(index: number, step: Step): boolean {
    const seen = this.observed[step.event] ?? [];
    if (seen.length === 0) {
      return this.fail(index, `\`${step.event}\` was not emitted`);
    }
    let mismatch = '';
    for (const event of seen) {
      if (!matches(event.payload, step.payload ?? {})) {
        continue;
      }
      // The declared fields, and what each holds. Asserting only that the event arrived would pass
      // an implementation that published it empty.
      const reason = holds(event.payload, step.shape ?? {});
      if (reason !== '') {
        mismatch = reason;
        continue;
      }
      return true;
    }
    if (mismatch !== '') {
      return this.fail(index, `\`${step.event}\` was emitted, and ${mismatch}`);
    }
    return this.fail(
      index,
      `\`${step.event}\` was emitted, and no instance of it carried ${describe(step.payload ?? {})}`,
    );
  }

  expectNoEvent(index: number, step: Step): boolean {
    if ((this.observed[step.event] ?? []).length > 0) {
      return this.fail(index, `\`${step.event}\` was emitted, and this branch does not emit it`);
    }
    return true;
  }

  async eventuallyEvent(index: number, step: Step): Promise<boolean> {
    const deadline = this.harness.deadline();
    for (let attempt = 0; attempt < deadline.attempts; attempt += 1) {
      let events: ObservedEvent[];
      try {
        events =
          (await this.target.observeEvents({
            event: step.event,
            correlation: this.correlation,
            deadline: { attempts: deadline.attempts - attempt },
          })) ?? [];
      } catch (error) {
        if (isUnsupported(error)) {
          this.skip(`step ${index}: the target cannot observe \`${step.event}\``);
        }
        return this.fail(index, `observing \`${step.event}\`: ${errorText(error)}`);
      }
      for (const event of events) {
        (this.observed[event.event] ??= []).push(event);
        this.remember(event);
      }
      if ((this.observed[step.event] ?? []).length > 0) {
        return true;
      }
    }
    return this.fail(index, `\`${step.event}\` was not observed within the run's budget`);
  }

  async establishEntity(index: number, step: Step): Promise<boolean> {
    if (Object.prototype.hasOwnProperty.call(this.instances, step.instance)) {
      return this.fail(index, `duplicate setup instance \`${step.instance}\``);
    }
    for (const previous of this.established) {
      if (previous.entity === step.entity && equal(previous.identity, step.identity)) {
        return this.fail(index, `duplicate qualified entity identity for \`${step.entity}\``);
      }
    }
    if (!isEntitySetupTarget(this.target)) {
      this.skip('target cannot validate and establish entity state');
      return false;
    }
    const request: EntitySetupRequest = {
      entity: step.entity,
      identity: step.identity,
      fields: step.fields ?? {},
      state: step.state,
      correlation: this.correlation,
    };
    try {
      await this.target.establishEntity(request);
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(`entity setup unsupported: ${errorText(error)}`);
      }
      return this.fail(index, `entity setup failed: ${errorText(error)}`);
    }
    this.established.push(request);
    this.instances[step.instance] = step.identity;
    // A pre-setup query cannot establish facts about the newly acknowledged state.
    this.queried = '';
    this.lastView = [];
    return true;
  }

  captureInstance(index: number, step: Step): boolean {
    for (const event of this.observed[step.event] ?? []) {
      if (Object.prototype.hasOwnProperty.call(event.payload, step.field)) {
        this.instances[step.instance] = event.payload[step.field];
        return true;
      }
    }
    return this.fail(
      index,
      `nothing bound \`${step.instance}\`: \`${step.event}\` did not carry \`${step.field}\``,
    );
  }

  async queryView(index: number, step: Step): Promise<boolean> {
    const params = this.resolveAll(index, step.params);
    if (params === null) {
      return false;
    }
    let result: ViewResult;
    try {
      result = await this.target.queryView({
        view: step.view,
        params,
        atLeast: this.consistency,
        correlation: this.correlation,
        deadline: this.harness.deadline(),
      });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(
          `step ${index}: the target does not expose \`${step.view}\`: ${errorText(error)}`,
        );
      }
      return this.fail(index, `querying \`${step.view}\`: ${errorText(error)}`);
    }
    this.lastView = result?.rows ?? [];
    this.queried = step.view;
    return true;
  }

  snapshotSubject(index: number, step: Step): boolean {
    if (this.queried !== step.view)
      return this.fail(index, `subject snapshot requires a preceding query of ${step.view}`);
    const capture = step.step === 'snapshot_subject';
    const previous = this.snapshots.get(step.view);
    const identity = capture ? this.resolveAll(index, step.subject) : previous?.identity;
    if (!identity || Object.keys(identity).length === 0)
      return this.fail(index, 'missing subject identity or previous snapshot');
    const rows = this.lastView.filter((row) => matches(row, identity));
    if (rows.length !== 1)
      return this.fail(
        index,
        `subject snapshot ${step.view} matched ${rows.length} rows, want exactly one`,
      );
    if (capture) {
      this.snapshots.set(step.view, { identity, row: goMarshal(rows[0]!) });
      return true;
    }
    if (goMarshal(rows[0]!) !== previous!.row)
      return this.fail(
        index,
        `subject changed in ${step.view}: before=${previous!.row} after=${goMarshal(rows[0]!)}`,
      );
    return true;
  }

  async expectView(index: number, step: Step, retry: boolean): Promise<boolean> {
    const attempts = retry ? this.harness.deadline().attempts : 1;
    let last = '';
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      if (retry || this.queried !== step.view) {
        const params = this.resolveAll(index, step.params);
        if (params === null) {
          return false;
        }
        let result: ViewResult;
        try {
          result = await this.target.queryView({
            view: step.view,
            params,
            atLeast: '',
            correlation: this.correlation,
            deadline: { attempts: attempts - attempt },
          });
        } catch (error) {
          if (isUnsupported(error)) {
            this.skip(
              `step ${index}: the target does not expose \`${step.view}\`: ${errorText(error)}`,
            );
          }
          return this.fail(index, `querying \`${step.view}\`: ${errorText(error)}`);
        }
        this.lastView = result?.rows ?? [];
        this.queried = step.view;
      }
      const [held, reason, undecidable] = this.decide(index, step);
      if (undecidable) {
        // Not retried, ever. A row that cannot answer the question is a defect in the
        // specification or in what the view publishes, and polling to the deadline reports it as
        // a timeout — the same defect in a slower, less legible costume.
        return this.fail(index, reason);
      }
      if (held) {
        return true;
      }
      last = reason;
    }
    return this.fail(index, last);
  }

  /** decide answers whether the view expectation holds, why not, and whether it could be decided. */
  decide(index: number, step: Step): [boolean, string, boolean] {
    const expectation = step.expectation;
    if (expectation === undefined) {
      return [false, 'the suite names no expectation, which is a generator defect', true];
    }
    switch (expectation.expect) {
      case 'contains':
      case 'excludes': {
        const want = this.resolveAll(index, expectation.fields);
        if (want === null) {
          return [false, 'a value the expectation names is not bound', true];
        }
        let found = false;
        for (const row of this.lastView) {
          if (matches(row, want)) {
            found = true;
            break;
          }
        }
        if (expectation.expect === 'excludes') {
          if (found) {
            return [
              false,
              `\`${step.view}\` holds a row where ${describe(want)}, and it must not`,
              false,
            ];
          }
          return [true, '', false];
        }
        if (!found) {
          return [false, `\`${step.view}\` holds no row where ${describe(want)}`, false];
        }
        return [true, '', false];
      }
      case 'satisfies': {
        let predicate: Predicate;
        try {
          predicate = fromNode(expectation.predicate);
        } catch (error) {
          return [false, `the suite's predicate does not parse: ${errorText(error)}`, true];
        }
        // "At least one row" is part of the assertion: every row of an empty view satisfies
        // everything, so a target that published nothing would otherwise pass.
        if (this.lastView.length === 0) {
          return [false, `\`${step.view}\` holds no rows`, false];
        }
        for (const row of this.lastView) {
          const answer = predicate.evaluate(facts(row));
          if (answer === TruthTrue) {
            continue;
          }
          if (answer === TruthUnknown) {
            return [
              false,
              `\`${String(predicate)}\` cannot be decided against ${describeRow(row)}, which is a ` +
                'defect in the view or the specification',
              true,
            ];
          }
          return [false, `\`${String(predicate)}\` in ${describeRow(row)}`, false];
        }
        return [true, '', false];
      }
      case 'counts': {
        // A count and not a match: which rows they are is what `contains` asks, and asking both in
        // one assertion would report two different defects under one name.
        if (expectation.at_least === undefined && expectation.at_most === undefined) {
          return [
            false,
            'a count with neither `at_least` nor `at_most` requires nothing, which is a generator defect',
            true,
          ];
        }
        const held = this.lastView.length;
        if (expectation.at_least !== undefined && held < expectation.at_least) {
          return [
            false,
            `\`${step.view}\` holds ${held} row(s) and the specification requires at least ${expectation.at_least}`,
            false,
          ];
        }
        if (expectation.at_most !== undefined && held > expectation.at_most) {
          return [
            false,
            `\`${step.view}\` holds ${held} row(s) and the specification permits at most ${expectation.at_most}`,
            false,
          ];
        }
        return [true, '', false];
      }
      case 'ranked':
        return ranked(step.view, expectation.order_by ?? [], this.lastView);
      case 'at': {
        // A position in an unordered view names a different row on every read, and calling
        // whichever one came back "the first" is a coin toss reported as a check.
        if ((expectation.order_by ?? []).length === 0) {
          return [
            false,
            `\`${step.view}\` declares no order, so a position in it names no particular row`,
            true,
          ];
        }
        if (expectation.position === undefined) {
          return [false, 'the suite names no position, which is a generator defect', true];
        }
        const want = this.resolveAll(index, expectation.fields);
        if (want === null) {
          return [false, 'a value the expectation names is not bound', true];
        }
        const held = this.lastView.length;
        let at = expectation.position.index;
        switch (expectation.position.row) {
          case 'first':
            at = 0;
            break;
          case 'last':
            at = held - 1;
            break;
          case 'nth':
            break;
          default:
            return [
              false,
              `\`${expectation.position.row}\` is a position this generated runner does not implement`,
              true,
            ];
        }
        if (at < 0 || at >= held) {
          return [false, `\`${step.view}\` holds ${held} row(s)`, false];
        }
        const row = itemAt(this.lastView, at);
        if (!matches(row, want)) {
          return [false, `row ${at} of \`${step.view}\` is ${describeRow(row)}`, false];
        }
        return [true, '', false];
      }
      default:
        return [
          false,
          `\`${expectation.expect}\` is an expectation this generated runner does not implement`,
          true,
        ];
    }
  }

  async expectInvocation(index: number, step: Step): Promise<boolean> {
    let invocations: Invocation[];
    try {
      invocations =
        (await this.target.observeInvocations({
          binding: step.binding,
          command: step.command,
          correlation: this.correlation,
          deadline: this.harness.deadline(),
        })) ?? [];
    } catch (error) {
      if (isUnsupported(error)) {
        // The one method the model explicitly refuses to require. Unsupported is a fact about the
        // target, not a failure of the specification.
        this.skip(
          `step ${index}: the target does not expose what \`${step.binding}\` invoked: ${errorText(error)}`,
        );
      }
      return this.fail(index, `observing \`${step.binding}\`: ${errorText(error)}`);
    }
    const want: { [field: string]: Node } = {};
    const absent: string[] = [];
    for (const [field, written] of Object.entries(step.input ?? {})) {
      let node: Node;
      let present: boolean;
      try {
        [node, present] = this.resolveAccessorExpected(written);
      } catch (error) {
        return this.fail(index, `\`${field}\`: ${errorText(error)}`);
      }
      if (present) {
        want[field] = node;
      } else {
        absent.push(field);
      }
    }
    for (const invocation of invocations) {
      let absenceOK = true;
      for (const field of absent) {
        if (Object.prototype.hasOwnProperty.call(invocation.input, field)) {
          absenceOK = false;
        }
      }
      if (invocation.command === step.command && matches(invocation.input, want) && absenceOK) {
        return true;
      }
    }
    return this.fail(
      index,
      `\`${step.binding}\` did not invoke \`${step.command}\` with ${describe(want)}`,
    );
  }

  async redeliver(index: number, step: Step): Promise<boolean> {
    try {
      await this.target.redeliverEvent({ event: step.event, correlation: this.correlation });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(
          `step ${index}: the target cannot redeliver \`${step.event}\`, so \`at_least_once\` is unchecked`,
        );
      }
      return this.fail(index, `redelivering \`${step.event}\`: ${errorText(error)}`);
    }
    return true;
  }

  async configure(index: number, step: Step): Promise<boolean> {
    if (step.force === undefined) {
      return this.fail(index, 'the suite names no outcome to force, which is a generator defect');
    }
    try {
      await this.target.configureExternalOutcome({
        command: step.force.command,
        outcome: step.force.outcome,
        correlation: this.correlation,
      });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(`step ${index}: the target cannot force \`${step.force.outcome}\``);
      }
      return this.fail(index, `forcing \`${step.force.outcome}\`: ${errorText(error)}`);
    }
    return true;
  }

  /**
   * clock is the target's clock, or a report that it has none.
   *
   * One place, so every one of the four steps reaches the same answer and the skip reads the same.
   */
  clock(index: number): Target & Clock {
    if (!isClock(this.target)) {
      this.skip(
        `step ${index} claims a length of time, and this target implements no Clock, so the claim ` +
          'cannot be checked. It is reported unanswered rather than satisfied.',
      );
    }
    return this.target as Target & Clock;
  }

  /** markInstant names the instant a later claim measures from. */
  async markInstant(index: number, step: Step): Promise<boolean> {
    const clock = this.clock(index);
    try {
      await clock.markInstant({ instant: step.instant, correlation: this.correlation });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(`step ${index}: the target cannot mark the instant \`${step.instant}\``);
      }
      return this.fail(index, `marking the instant \`${step.instant}\`: ${errorText(error)}`);
    }
    this.marked[step.instant] = true;
    return true;
  }

  /** elapsed asks the clock to let a window close, and returns what it read. */
  async elapsed(
    index: number,
    step: Step,
    hold: number,
    watching: string,
  ): Promise<{ elapsedMillis: number; published: number } | null> {
    const clock = this.clock(index);
    if (this.marked[step.instant] !== true) {
      this.fail(
        index,
        `the window opens at \`${step.instant}\`, and no earlier step marked it; this is a defect ` +
          'in the suite rather than in the implementation',
      );
      return null;
    }
    let observed: ElapsedObservation;
    try {
      observed = await clock.observeElapsed({
        instant: step.instant,
        hold,
        watching,
        correlation: this.correlation,
      });
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(`step ${index}: the target cannot let time pass since \`${step.instant}\``);
      }
      this.fail(index, `letting ${hold}s pass since \`${step.instant}\`: ${errorText(error)}`);
      return null;
    }
    return { elapsedMillis: observed?.elapsedMillis ?? 0, published: observed?.published ?? 0 };
  }

  /**
   * expectElapsed requires that a window of a stated length really passed, on one side or the other.
   *
   * `within` measures what already happened and holds nothing: holding first would guarantee the
   * answer it is asking about. `not_before` is the hold, and the hold is the point.
   */
  async expectElapsed(index: number, step: Step, within: boolean): Promise<boolean> {
    const hold = within ? 0 : step.elapsed;
    const observed = await this.elapsed(index, step, hold, '');
    if (observed === null) {
      return false;
    }
    const claimed = step.elapsed * 1000;
    if (within && observed.elapsedMillis > claimed) {
      return this.fail(
        index,
        `no more than ${step.elapsed}s may have passed since \`${step.instant}\`, and the target ` +
          `measured ${observed.elapsedMillis}ms`,
      );
    }
    if (!within && observed.elapsedMillis < claimed) {
      return this.fail(
        index,
        `at least ${step.elapsed}s must have passed since \`${step.instant}\`, and the target ` +
          `measured ${observed.elapsedMillis}ms`,
      );
    }
    return true;
  }

  /**
   * expectQuiet requires that an event was not published anywhere inside a window.
   *
   * A different claim from `expect_no_event`, which is about the command before it. This is about
   * a stretch of the scenario in which no command of its own runs.
   */
  async expectQuiet(index: number, step: Step): Promise<boolean> {
    const observed = await this.elapsed(index, step, step.elapsed, step.event);
    if (observed === null) {
      return false;
    }
    // The window has to have closed for the claim to be about the window the scenario wrote.
    if (observed.elapsedMillis < step.elapsed * 1000) {
      return this.fail(
        index,
        `the window of ${step.elapsed}s after \`${step.instant}\` did not close: the target ` +
          `measured ${observed.elapsedMillis}ms, so what it answered about is shorter than what ` +
          'the scenario claims',
      );
    }
    if (observed.published > 0) {
      return this.fail(
        index,
        `\`${step.event}\` was published ${observed.published} time(s) within ${step.elapsed}s of ` +
          `\`${step.instant}\``,
      );
    }
    return true;
  }

  /**
   * expectHalt requires that a reader's stop stopped the producer of an ordered read.
   *
   * Two conditions and the claim needs both. The source must have produced exactly what the reader
   * took, and the read must have ended because the reader said stop.
   */
  async expectHalt(index: number, step: Step, retry: boolean): Promise<boolean> {
    if (!isOrderedReader(this.target)) {
      this.skip(
        `step ${index} claims a reader stopped an ordered scan, and this target implements no ` +
          'OrderedReader, so the claim cannot be checked. It is reported unanswered rather than ' +
          'satisfied.',
      );
      return false;
    }
    const reader = this.target as Target & OrderedReader;
    const params = this.resolveAll(index, step.params);
    if (params === null) {
      return false;
    }
    // Current for the eventual half, exactly as expectView reads it: demanding the token would
    // make the target block until the projection caught up, which is the lag the retry observes.
    let atLeast = this.consistency;
    let attempts = 1;
    if (retry) {
      atLeast = '';
      attempts = this.harness.deadline().attempts;
    }
    let last = '';
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      let observed: ScanObservation;
      try {
        observed = await reader.scanView({
          view: step.view,
          params,
          stopAfter: step.after,
          atLeast,
          correlation: this.correlation,
          deadline: { attempts: attempts - attempt },
        });
      } catch (error) {
        if (isUnsupported(error)) {
          this.skip(`step ${index}: the target cannot read \`${step.view}\` a row at a time`);
        }
        return this.fail(index, `reading \`${step.view}\` a row at a time: ${errorText(error)}`);
      }
      const produced = observed?.produced ?? 0;
      const halted = observed?.halted ?? false;
      if (halted && produced === step.after) {
        return true;
      }
      if (halted) {
        last = `the reader stopped, and the target produced ${produced} row(s) to hand it ${step.after}`;
      } else {
        last =
          `the read ended because the source ran out after ${produced} row(s), not because the ` +
          'reader stopped it';
      }
    }
    return this.fail(
      index,
      `reading \`${step.view}\` must stop after ${step.after} row(s) because the reader did: ${last}`,
    );
  }

  /** fail records one failed assertion and stops the scenario. */
  fail(index: number, message: string): boolean {
    this.status = statusFailed;
    this.failures.push(`step ${index}: ${message}`);
    return false;
  }

  /**
   * skip ends the scenario as one the target could not answer, and records that it did.
   *
   * Every skip in this runtime goes through here so the report and the test log cannot disagree
   * about what the scenario came to.
   *
   * EVERY CALLER PASSES THE TARGET'S OWN ERROR. A target throws `unsupported()` around the
   * sentence explaining what it could not answer, and printing only the construct's name throws
   * that away, leaving different causes rendered identically.
   */
  skip(message: string): never {
    this.status = statusSkipped;
    throw new SkipSignal(message);
  }

  /** resolveAll resolves every value a step carries against what this run has bound. */
  resolveAll(
    index: number,
    values: { [field: string]: Value } | undefined,
  ): { [field: string]: Node } | null {
    const resolved: { [field: string]: Node } = {};
    for (const [field, written] of Object.entries(values ?? {})) {
      try {
        resolved[field] = this.resolve(written);
      } catch (error) {
        this.fail(index, `\`${field}\`: ${errorText(error)}`);
        return null;
      }
    }
    return resolved;
  }

  resolve(value: Value): Node {
    switch (value.kind) {
      case 'literal':
        return value.value;
      case 'instance': {
        if (!Object.prototype.hasOwnProperty.call(this.instances, value.instance as string)) {
          throw new Error(`nothing bound the instance \`${String(value.instance)}\``);
        }
        return this.instances[value.instance as string];
      }
      case 'observed': {
        // The whole scenario, and the first occurrence in it. `observed` means "what an earlier
        // step in this scenario published", so a later command that published nothing of this name
        // does not unbind it.
        for (const event of this.seen) {
          if (event.event !== value.event) {
            continue;
          }
          if (Object.prototype.hasOwnProperty.call(event.payload, value.field as string)) {
            return event.payload[value.field as string];
          }
        }
        throw new Error(
          `\`${String(value.event)}\` was not observed carrying \`${String(value.field)}\``,
        );
      }
      default:
        throw new Error(
          `\`${value.kind}\` is a value kind this generated runner does not implement`,
        );
    }
  }

  /** resolveAccessorExpected answers a value and whether the accessor found one at all. */
  resolveAccessorExpected(value: Value): [Node, boolean] {
    if (value.kind === 'observed_selection') {
      if (value.selection === undefined) {
        throw new Error('missing selection observation');
      }
      for (const event of this.seen) {
        if (event.event === value.event) {
          return value.selection.evaluate(event.payload);
        }
      }
      throw new Error('selection event was not observed');
    }
    if (value.kind !== 'observed_accessor') {
      return [this.resolve(value), true];
    }
    if (value.accessor === undefined) {
      throw new Error('missing accessor plan');
    }
    for (const event of this.seen) {
      if (event.event === value.event) {
        return value.accessor.evaluate(event.payload);
      }
    }
    throw new Error('accessor event was not observed');
  }

  async checkPeriodic(index: number, step: Step): Promise<boolean> {
    if (!isPeriodicTarget(this.target)) {
      this.skip(`step ${index}: target has no periodic authority`);
    }
    const clock = this.clock(index);
    if (step.check === undefined) {
      return this.fail(index, 'missing periodic check');
    }
    try {
      await checkPeriodic(
        step.check,
        this.correlation,
        this.target as Target & PeriodicTarget,
        clock,
      );
    } catch (error) {
      if (isUnsupported(error)) {
        this.skip(`step ${index}: periodic authority/observation unsupported: ${errorText(error)}`);
      }
      return this.fail(index, `periodic contract: ${errorText(error)}`);
    }
    return true;
  }
}

// ---- comparisons --------------------------------------------------------------------------------

/**
 * matches reports whether every wanted field is present and equal.
 *
 * A subset, not an equality: a row carries what the view projects, and a scenario names the fields
 * that identify the instance it is about.
 */
export function matches(row: { [field: string]: Node }, want: { [field: string]: Node }): boolean {
  for (const field of Object.keys(want)) {
    if (!Object.prototype.hasOwnProperty.call(row, field) || !equal(row[field], want[field])) {
      return false;
    }
  }
  return true;
}

/**
 * equal compares two specification values structurally.
 *
 * Dispatched on the left value, exactly as the Go runtime's type switch is — including that a
 * `JsonNumber` on the *left* matches nothing, because `json.Number` falls through that switch to
 * its default. Two runtimes that disagreed here would disagree about a duplicate entity identity.
 */
export function equal(left: Node, right: Node): boolean {
  if (isNil(left)) {
    return isNil(right);
  }
  if (typeof left === 'boolean') {
    return typeof right === 'boolean' && left === right;
  }
  if (typeof left === 'number') {
    const [other, ok] = asNumber(right);
    return ok && left === other;
  }
  if (typeof left === 'string') {
    return typeof right === 'string' && left === right;
  }
  if (Array.isArray(left)) {
    if (!Array.isArray(right) || left.length !== right.length) {
      return false;
    }
    return left.every((item, index) => equal(item, right[index]));
  }
  if (isObject(left)) {
    if (!isObject(right) || Object.keys(left).length !== Object.keys(right).length) {
      return false;
    }
    for (const key of Object.keys(left)) {
      if (!equal(left[key], right[key])) {
        return false;
      }
    }
    return true;
  }
  return false;
}

export function asNumber(value: Node): [number, boolean] {
  if (typeof value === 'number') {
    return [value, true];
  }
  if (typeof value === 'bigint') {
    return [Number(value), true];
  }
  if (value instanceof JsonNumber) {
    const parsed = Number(value.raw);
    return [parsed, Number.isFinite(parsed)];
  }
  return [0, false];
}

/** describe renders a field match for a diagnostic, in a stable order. */
export function describe(fields: { [field: string]: Node }): string {
  return describeRow(fields);
}

export function describeRow(row: { [field: string]: Node }): string {
  return sortStrings(Object.keys(row))
    .map((key) => `${key} = ${render(row[key])}`)
    .join(', ');
}

/** formatFloat is `strconv.FormatFloat(value, 'f', -1, 64)`: shortest, and never an exponent. */
function formatFloat(value: number): string {
  if (Number.isNaN(value)) {
    return 'NaN';
  }
  if (value === Number.POSITIVE_INFINITY) {
    return '+Inf';
  }
  if (value === Number.NEGATIVE_INFINITY) {
    return '-Inf';
  }
  if (Object.is(value, -0)) {
    return '-0';
  }
  const written = String(value);
  const exponent = /^(-?)(\d+)(?:\.(\d+))?[eE]([+-]?\d+)$/.exec(written);
  if (exponent === null) {
    return written;
  }
  const [, sign = '', whole = '', fraction = '', power = '0'] = exponent;
  const digits = whole + fraction;
  const point = whole.length + Number.parseInt(power, 10);
  if (point <= 0) {
    return `${sign}0.${'0'.repeat(-point)}${digits}`;
  }
  if (point >= digits.length) {
    return `${sign}${digits}${'0'.repeat(point - digits.length)}`;
  }
  return `${sign}${digits.slice(0, point)}.${digits.slice(point)}`;
}

/** quoteGo is `strconv.Quote`: a Go-syntax string literal, for a diagnostic. */
function quoteGo(value: string): string {
  let out = '"';
  for (const character of value) {
    switch (character) {
      case '"':
        out += '\\"';
        continue;
      case '\\':
        out += '\\\\';
        continue;
      case '\u0007':
        out += '\\a';
        continue;
      case '\b':
        out += '\\b';
        continue;
      case '\f':
        out += '\\f';
        continue;
      case '\n':
        out += '\\n';
        continue;
      case '\r':
        out += '\\r';
        continue;
      case '\t':
        out += '\\t';
        continue;
      case '\v':
        out += '\\v';
        continue;
      default:
        break;
    }
    const code = character.codePointAt(0) as number;
    if (code < 0x20 || code === 0x7f) {
      out += `\\x${code.toString(16).padStart(2, '0')}`;
      continue;
    }
    out += character;
  }
  return `${out}"`;
}

export function render(value: Node): string {
  if (isNil(value)) {
    return 'null';
  }
  if (typeof value === 'string') {
    return quoteGo(value);
  }
  if (typeof value === 'number') {
    return formatFloat(value);
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  return goMarshal(value);
}

/**
 * holds reports why a payload does not carry what the specification declared, or "" when it does.
 *
 * # What `optional` excuses, and what it does not
 *
 * Absence, and an explicit null, which is absence spelled differently. Nothing else. A reading
 * that skipped a declared-optional path altogether would pass an implementation publishing the
 * field with the wrong kind in it, and that is a weaker suite than the one that wrongly refused
 * absence. `optional` means "may be absent", never "unchecked".
 *
 * # What is checked when a value is there
 *
 * A primitive against its grammar, and an `enum` against its declared variants. Both sets travel
 * in the leaf, so neither re-derives a decision the compiler already took. A list, a map and a
 * union say only what container they are, so this runner does not reach into them.
 */
export function holds(payload: { [field: string]: Node }, shape: { [path: string]: Held }): string {
  for (const path of sortStrings(Object.keys(shape))) {
    const expected = shape[path] as Held;
    const [value, state, at] = lookup(payload, path);
    if (state === 'blocked') {
      // Not excusable by `optional`. A prefix holding a value no field can be read out of
      // contradicts the declaration whatever the leaf permits.
      return `\`${at}\` holds ${render(value)}, so \`${path}\` is not there to read`;
    }
    if (state === 'absent') {
      if (expected.optional === true) {
        continue;
      }
      return `did not carry \`${path}\``;
    }
    if (isNil(value) && expected.optional === true) {
      continue;
    }
    switch (expected.holds) {
      case 'primitive': {
        const reason = primitive(expected.kind ?? '', value);
        if (reason !== '') {
          return `\`${path}\` ${reason}`;
        }
        break;
      }
      case 'enum':
        if (!variant(expected.variants ?? [], value)) {
          return (
            `\`${path}\` holds ${render(value)} and the specification declares one of ` +
            `${(expected.variants ?? []).join(', ')}`
          );
        }
        break;
      default:
        // A list, a map and a union are containers whose members a path cannot name, so there is
        // nothing here to compare them against.
        break;
    }
  }
  return '';
}

/**
 * variant reports whether value is one of a closed set of names, as text.
 *
 * A value that is not text is not one of the names, rather than something to be rendered and
 * compared. A closed set of names is closed, which is the whole reason to declare one.
 */
export function variant(variants: string[], value: Node): boolean {
  if (typeof value !== 'string') {
    return false;
  }
  return variants.includes(value);
}

/**
 * Reach is what a dotted path found in a payload.
 *
 * Three answers rather than two: absence and a prefix that contradicts the declaration are
 * different facts, and only the first of them is one `optional` may excuse.
 *
 *   * `value`   — a value sits at the path. It may be null.
 *   * `absent`  — nothing is carried there. No segment held it, or a segment on the way held null.
 *   * `blocked` — a prefix holds something that is neither a mapping nor null.
 */
export type Reach = 'value' | 'absent' | 'blocked';

/**
 * lookup follows a dotted path into a payload, reporting the prefix that blocked it and what that
 * prefix held when one did.
 */
export function lookup(payload: { [field: string]: Node }, path: string): [Node, Reach, string] {
  let current: Node = payload;
  let walked = '';
  for (const segment of path.split('.')) {
    if (isNil(current)) {
      return [null, 'absent', walked];
    }
    if (!isObject(current)) {
      return [current, 'blocked', walked];
    }
    if (walked !== '') {
      walked += '.';
    }
    walked += segment;
    if (!Object.prototype.hasOwnProperty.call(current, segment)) {
      return [null, 'absent', walked];
    }
    current = current[segment];
  }
  return [current, 'value', walked];
}

/**
 * canonicalUUID reports whether text is a UUID in the one hyphenated form the specification
 * publishes. The urn:uuid: and brace-wrapped spellings are refused, because one value has one
 * spelling.
 */
export function canonicalUUID(value: string): boolean {
  const widths = [8, 4, 4, 4, 12];
  const groups = value.split('-');
  if (groups.length !== widths.length) {
    return false;
  }
  for (let index = 0; index < groups.length; index += 1) {
    const group = itemAt(groups, index);
    if (group.length !== itemAt(widths, index)) {
      return false;
    }
    if (!/^[0-9a-fA-F]*$/.test(group)) {
      return false;
    }
  }
  return true;
}

/**
 * paddedBase64 reports whether text is base64 with padding, the standard alphabet only.
 *
 * Padding is a *suffix*: strip up to two trailing '=', then every remaining byte must be in the
 * alphabet. A scan that admitted '=' at either of the last two positions accepted "AA=A" —
 * padding followed by data — which every other lane refuses.
 */
export function paddedBase64(value: string): boolean {
  if (value.length % 4 !== 0) {
    return false;
  }
  const alphabet = (character: string): boolean =>
    (character >= 'A' && character <= 'Z') ||
    (character >= 'a' && character <= 'z') ||
    (character >= '0' && character <= '9') ||
    character === '+' ||
    character === '/';
  let padding = 0;
  while (padding < 2 && padding < value.length && value[value.length - 1 - padding] === '=') {
    padding += 1;
  }
  for (let index = 0; index < value.length - padding; index += 1) {
    if (!alphabet(itemAt([...value], index))) {
      return false;
    }
  }
  return true;
}

/**
 * integerBound is the binary64 image of the Integer range and not the interval itself: this
 * runtime sees a binary64, and the largest signed 64-bit integer written as one and read back is
 * 2^63. Comparing against 2^63 exclusively refused every integer above 9223372036854775296.
 */
export const integerBound = 9223372036854775808;

export function integral(value: number): boolean {
  return value === Math.trunc(value) && value >= -integerBound && value <= integerBound;
}

/**
 * primitive reports why a value is not of the declared kind, or "" when it is.
 *
 * A grammar, not merely a shape. "uuid" admitting any string at all and "bytes" admitting anything
 * whatever would accept candidates that every schema the same specification publishes refuses.
 */
export function primitive(kind: string, value: Node): string {
  const mismatch = (): string => `holds ${render(value)} and the specification declares a ${kind}`;
  switch (kind) {
    case 'string':
    case 'timestamp':
    case 'duration':
      if (typeof value !== 'string') {
        return mismatch();
      }
      break;
    case 'uuid':
      if (typeof value !== 'string' || !canonicalUUID(value)) {
        return mismatch();
      }
      break;
    case 'bytes':
      if (typeof value !== 'string' || !paddedBase64(value)) {
        return mismatch();
      }
      break;
    case 'integer': {
      const [number, ok] = asNumber(value);
      if (!ok || !integral(number)) {
        return mismatch();
      }
      break;
    }
    case 'decimal':
      if (!asNumber(value)[1]) {
        return mismatch();
      }
      break;
    case 'boolean':
      if (typeof value !== 'boolean') {
        return `holds ${render(value)} and the specification declares a boolean`;
      }
      break;
    default:
      break;
  }
  return '';
}

// ---- ordering ------------------------------------------------------------------------------------

/**
 * ranked reports whether rows are in the declared order.
 *
 * Adjacent pairs, not a sort: re-sorting and comparing would ask whether these are the right rows,
 * which they trivially are, and would pass a view that returned everything backwards.
 *
 * Fewer than two rows holds. There is no adjacent pair to be out of order, and demanding one would
 * quietly make every ordering claim a non-emptiness claim as well.
 */
export function ranked(view: string, orderBy: string[], rows: Row[]): [boolean, string, boolean] {
  const keys: [string, string][] = [];
  for (const written of orderBy) {
    const parts = goFields(written);
    if (parts.length === 0) {
      return [false, 'the suite writes an empty ranking key, which is a generator defect', true];
    }
    keys.push([itemAt(parts, 0), parts.length > 1 ? itemAt(parts, 1) : 'asc']);
  }

  for (let index = 0; index + 1 < rows.length; index += 1) {
    const earlier = itemAt(rows, index);
    const later = itemAt(rows, index + 1);
    for (const key of keys) {
      const hasLeft = Object.prototype.hasOwnProperty.call(earlier, key[0]);
      const hasRight = Object.prototype.hasOwnProperty.call(later, key[0]);
      if (!hasLeft || !hasRight) {
        return [
          false,
          `\`${view}\` is ranked by \`${key[0]}\` and does not publish it, which is a defect in the view`,
          true,
        ];
      }
      const [order, ok] = compare(earlier[key[0]], later[key[0]]);
      if (!ok) {
        return [
          false,
          `\`${view}\` holds values of two kinds in \`${key[0]}\`, which have no order between them`,
          true,
        ];
      }
      if (order === 0) {
        continue;
      }
      const wanted = key[1] === 'desc' || key[1] === 'descending' ? 1 : -1;
      if (order === wanted) {
        break;
      }
      return [
        false,
        `\`${view}\` holds ${describeRow(earlier)} then ${describeRow(later)}, which is not ` +
          `\`${key[0]} ${key[1]}\``,
        false,
      ];
    }
  }
  return [true, '', false];
}

/** compare orders two row values, reporting false where nothing orders them. */
export function compare(left: Node, right: Node): [number, boolean] {
  const [leftNumber, leftIsNumber] = asNumber(left);
  if (leftIsNumber) {
    const [rightNumber, rightIsNumber] = asNumber(right);
    if (rightIsNumber) {
      if (leftNumber < rightNumber) {
        return [-1, true];
      }
      if (leftNumber > rightNumber) {
        return [1, true];
      }
      return [0, true];
    }
    return [0, false];
  }
  if (typeof left === 'string') {
    if (typeof right === 'string') {
      return [byteCompare(left, right), true];
    }
    return [0, false];
  }
  if (typeof left === 'boolean') {
    if (typeof right === 'boolean') {
      if (left === right) {
        return [0, true];
      }
      return right ? [-1, true] : [1, true];
    }
  }
  return [0, false];
}

export function orNone(value: string): string {
  return value === '' ? 'nothing' : value;
}

// ---- opt-in report/2 admission and production ------------------------------------------------------

export interface ReportConfig {
  version: string;
  strict: boolean;
}

export function reportConfiguration(): ReportConfig {
  const selected = Object.prototype.hasOwnProperty.call(process.env, 'ESS_REPORT_FORMAT');
  const version = selected ? (process.env.ESS_REPORT_FORMAT as string) : '1';
  if (version !== '1' && version !== '2') {
    throw new Error('ESS_REPORT_FORMAT must be 1 or 2');
  }
  const strictSet = Object.prototype.hasOwnProperty.call(process.env, 'ESS_CONFORMANCE_STRICT');
  const diagnosticSet = Object.prototype.hasOwnProperty.call(
    process.env,
    'ESS_CONFORMANCE_ALLOW_INCOMPLETE',
  );
  const strict = process.env.ESS_CONFORMANCE_STRICT;
  const diagnostic = process.env.ESS_CONFORMANCE_ALLOW_INCOMPLETE;
  if ((strictSet && strict !== '1') || (diagnosticSet && diagnostic !== '1')) {
    throw new Error('strictness controls accept only unset or 1');
  }
  if (strictSet && diagnosticSet) {
    throw new Error('strict and allow-incomplete conflict');
  }
  if (strictSet && version !== '2') {
    throw new Error('strict conformance requires explicit ESS_REPORT_FORMAT=2');
  }
  return { version, strict: strictSet };
}

export function closed(value: Node, required: string, optional: string): { [key: string]: Node } {
  if (!isObject(value)) {
    throw new Error('expected object');
  }
  const allowed = new Set<string>();
  for (const key of goFields(required)) {
    allowed.add(key);
    if (!Object.prototype.hasOwnProperty.call(value, key)) {
      throw new Error(`missing field ${key}`);
    }
  }
  for (const key of goFields(optional)) {
    allowed.add(key);
  }
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      throw new Error(`unknown field ${key}`);
    }
  }
  return value;
}

export function text(value: Node): string {
  if (typeof value === 'string') {
    return value;
  }
  throw new Error('expected string');
}

export function array(value: Node): Node[] {
  if (Array.isArray(value)) {
    return value;
  }
  throw new Error('expected array');
}

const UINT64_MAX = 18446744073709551615n;

/**
 * unsigned is an unsigned integer token, as a bigint.
 *
 * A bigint and not a number, because the token may be larger than binary64 holds exactly and the
 * admission answer must not depend on that. The one place a value is then used as a count checks
 * it against the execution bound first.
 */
export function unsigned(value: Node): bigint {
  if (!(value instanceof JsonNumber)) {
    throw new Error('unsigned integer token required');
  }
  const raw = value.raw;
  const leading = raw[0] ?? '';
  if (raw === '' || (raw !== '0' && (leading < '1' || leading > '9'))) {
    throw new Error('unsigned integer token required');
  }
  for (const character of raw) {
    if (character < '0' || character > '9') {
      throw new Error('unsigned integer token required');
    }
  }
  const parsed = BigInt(raw);
  if (parsed > UINT64_MAX) {
    throw new Error('unsigned integer token required');
  }
  return parsed;
}

export const qualifiedName = /^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z][A-Za-z0-9_-]*)*$/;
export const kebabName = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;
export const stateName = /^[A-Z][A-Za-z0-9]*$/;
export const modelDigest = /^[a-f0-9]{64}$/;

export function name(value: Node, kebab: boolean): void {
  const label = text(value);
  const pattern = kebab ? kebabName : qualifiedName;
  if (!pattern.test(label)) {
    throw new Error(`invalid name ${quoteGo(label)}`);
  }
}

export function scenarioIdentity(id: string): void {
  const parts = id.split('/');
  const segment = (index: number): string => parts[index] ?? '';
  let valid = false;
  const q = (value: string): boolean => qualifiedName.test(value);
  const k = (value: string): boolean => kebabName.test(value);
  if (parts.length === 3 && segment(1) === 'outcome') {
    valid = q(segment(0)) && k(segment(2));
  } else if (parts.length === 3 && segment(1) === 'authored') {
    valid = q(segment(0)) && k(segment(2));
  } else if (parts.length === 3 && segment(1) === 'binding') {
    valid =
      k(segment(0)) &&
      (segment(2) === 'delivery' ||
        segment(2) === 'flow' ||
        segment(2) === 'mapping' ||
        segment(2) === 'on-failure');
  } else if (
    parts.length === 5 &&
    segment(1) === 'state' &&
    (segment(3) === 'refuses' || segment(3) === 'accepts')
  ) {
    valid = q(segment(0)) && stateName.test(segment(2)) && q(segment(4));
  } else if (parts.length === 6 && segment(1) === 'transition' && segment(3) === 'by') {
    valid =
      q(segment(0)) && q(segment(2)) && !segment(2).includes('.') && q(segment(4)) && k(segment(5));
  } else if (parts.length === 5 && segment(1) === 'invariant' && segment(2) === 'after') {
    valid = q(segment(0)) && q(segment(3)) && k(segment(4));
  } else if (parts.length === 5 && segment(1) === 'invariant' && segment(2) === 'at') {
    valid = q(segment(0)) && q(segment(3)) && segment(4) !== '';
  }
  if (!valid) {
    throw new Error(`malformed scenario ID ${quoteGo(id)}`);
  }
}

// ---- admitting the suite -----------------------------------------------------------------------

const SUITE_MAJORS: { [version: string]: number } = {
  'ess-conformance/1': 1,
  'ess-conformance/2': 2,
  'ess-conformance/3': 3,
  'ess-conformance/4': 4,
  'ess-conformance/5': 5,
  'ess-conformance/6': 6,
  'ess-conformance/7': 7,
  'ess-conformance/8': 8,
  'ess-conformance/9': 9,
  'ess-conformance/10': 10,
  'ess-conformance/11': 11,
};

export function admitSuite(raw: string): Suite {
  return admitSuiteDocument(raw, false);
}

export function admitSuiteDocument(raw: string, explicit: boolean): Suite {
  accessorPreflight(raw);
  const value = strictJSON(raw);
  const root = closed(value, 'provenance scenarios', 'coverage');
  const provenance = closed(
    root.provenance,
    'suite_version system specification_version spec_digest contract_digest',
    'component',
  );
  const version = text(provenance.suite_version);
  const major = SUITE_MAJORS[version];
  if (major === undefined) {
    throw new Error(`unsupported suite version ${quoteGo(version)}`);
  }
  const carriesCoverage = Object.prototype.hasOwnProperty.call(root, 'coverage');
  if (carriesCoverage !== (major === 5 || major === 7 || major === 9 || major === 11)) {
    throw new Error('coverage is required exactly for suite/5, suite/7, suite/9 and suite/11');
  }
  for (const key of ['system', 'specification_version', 'spec_digest', 'contract_digest']) {
    const held = text(provenance[key]);
    if (key.endsWith('digest') && !modelDigest.test(held)) {
      throw new Error('invalid digest');
    }
  }
  if (
    Object.prototype.hasOwnProperty.call(provenance, 'component') &&
    !isNil(provenance.component)
  ) {
    text(provenance.component);
  }
  const scenarios = root.scenarios;
  if (!isObject(scenarios)) {
    throw new Error('scenarios must be an object');
  }
  for (const id of Object.keys(scenarios)) {
    scenarioIdentity(id);
    const scenario = closed(scenarios[id], 'purpose steps source', '');
    const purpose = text(scenario.purpose);
    if (purpose.trim() === '' || [...purpose].length > 200) {
      throw new Error('invalid purpose');
    }
    for (const character of purpose) {
      const code = character.codePointAt(0) as number;
      if (code < 32 || (code >= 127 && code <= 159)) {
        throw new Error('purpose contains control');
      }
    }
    const steps = array(scenario.steps);
    for (const step of steps) {
      try {
        admitStep(step, major);
      } catch (error) {
        throw new Error(`${id}: ${errorText(error)}`);
      }
    }
    try {
      admitEntitySetups(steps);
    } catch (error) {
      throw new Error(`${id}: ${errorText(error)}`);
    }
    for (const source of array(scenario.source)) {
      admitReference(source);
    }
  }
  if (major === 5 || major === 7 || major === 9 || major === 11) {
    const coverage = root.coverage as { [key: string]: Node };
    if (Array.isArray(coverage.refused)) {
      for (const item of coverage.refused as Node[]) {
        if (isObject(item) && item.code === 'ESS-SYNTH-015' && major < 7) {
          throw new Error('accessor refusal requires suite/7');
        }
      }
    }
    if (isObject(coverage.selection)) {
      const filter = (coverage.selection as { [key: string]: Node }).filter;
      if (isObject(filter) && filter.kind === 'explicit') {
        const parent = filter.parent;
        if (isObject(parent) && parent.version !== version) {
          throw new Error('filtered coverage must preserve parent vocabulary version');
        }
      }
    }
    admitCoverage(root);
    const filter = ((root.coverage as { [key: string]: Node }).selection as { [key: string]: Node })
      .filter as { [key: string]: Node };
    if (!explicit && filter.kind !== 'all') {
      throw new Error('explicit suite requires complete input parents');
    }
  }

  const suite: Suite = {
    provenance: {
      suite_version: version,
      system: provenance.system as string,
      specification_version: provenance.specification_version as string,
      spec_digest: provenance.spec_digest as string,
      contract_digest: provenance.contract_digest as string,
    },
    scenarios: {},
    original: raw,
    document: root,
  };
  if (major === 5 || major === 7 || major === 9 || major === 11) {
    suite.coverage = root.coverage as { [key: string]: Node };
    // Original admission includes parents which will never execute. Retain their exact unsigned
    // metadata independently of the narrower execution view.
    for (const id of Object.keys(scenarios)) {
      suite.scenarios[id] = {
        purpose: (scenarios[id] as { [key: string]: Node }).purpose as string,
        steps: [],
      };
    }
    return suite;
  }
  suite.scenarios = decodeScenarios(scenarios);
  return suite;
}

export function executionSuite(suite: Suite): Suite {
  if (suite.coverage !== undefined) {
    executionIntegers(suite.document.scenarios as { [key: string]: Node });
    try {
      return {
        ...suite,
        scenarios: decodeScenarios(suite.document.scenarios as { [key: string]: Node }),
      };
    } catch (error) {
      throw new Error(`exact selected metadata exceeds the execution view: ${errorText(error)}`);
    }
  }
  return suite;
}

/**
 * executionIntegers refuses a count no execution integer can carry.
 *
 * The bound is the Go runtime's, not this one's: the two must admit the same documents, and a
 * document the Go suite runs is one this suite has to run too. A value above 2^53 is carried here
 * without its last digits, which is a count no specification writes and a divergence smaller than
 * refusing a suite the sibling accepts.
 */
export function executionIntegers(scenarios: { [key: string]: Node }): void {
  const maximum = 9223372036854775807n;
  for (const id of meaningKeys(scenarios)) {
    const steps = (scenarios[id] as { [key: string]: Node }).steps as Node[];
    for (let index = 0; index < steps.length; index += 1) {
      const step = steps[index] as { [key: string]: Node };
      const fields: { [label: string]: Node } = {};
      for (const field of ['after', 'elapsed']) {
        if (Object.prototype.hasOwnProperty.call(step, field)) {
          fields[field] = step[field];
        }
      }
      if (isObject(step.expectation)) {
        const expectation = step.expectation as { [key: string]: Node };
        for (const field of ['at_least', 'at_most']) {
          if (!isNil(expectation[field])) {
            fields[`expectation.${field}`] = expectation[field];
          }
        }
        if (
          isObject(expectation.position) &&
          (expectation.position as { [key: string]: Node }).row === 'nth'
        ) {
          fields['expectation.position.index'] = (
            expectation.position as { [key: string]: Node }
          ).index;
        }
      }
      for (const field of meaningKeys(fields)) {
        const value = unsigned(fields[field]);
        if (value > maximum) {
          throw new Error(
            `scenario ${id} step ${index} field ${field}: exact value ${value} cannot be ` +
              `represented as an execution integer (maximum ${maximum})`,
          );
        }
      }
    }
  }
}

// ---- the typed view a scenario is walked through --------------------------------------------------

function decodeScenarios(scenarios: { [key: string]: Node }): { [id: string]: Scenario } {
  const result: { [id: string]: Scenario } = {};
  for (const id of Object.keys(scenarios)) {
    const scenario = scenarios[id] as { [key: string]: Node };
    result[id] = {
      purpose: (scenario.purpose as string) ?? '',
      steps: (scenario.steps as Node[]).map(decodeStep),
    };
  }
  return result;
}

function decodeNumber(value: Node): number {
  if (value instanceof JsonNumber) {
    return Number(value.raw);
  }
  if (typeof value === 'number') {
    return value;
  }
  return 0;
}

function decodeValues(value: Node): { [field: string]: Value } | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const result: { [field: string]: Value } = {};
  for (const field of Object.keys(value)) {
    const written = value[field] as { [key: string]: Node };
    const decoded: Value = { kind: written.kind as string };
    if (Object.prototype.hasOwnProperty.call(written, 'value')) {
      decoded.value = plainNumbers(written.value);
    }
    if (Object.prototype.hasOwnProperty.call(written, 'instance')) {
      decoded.instance = written.instance as string;
    }
    if (Object.prototype.hasOwnProperty.call(written, 'event')) {
      decoded.event = written.event as string;
    }
    if (Object.prototype.hasOwnProperty.call(written, 'field')) {
      decoded.field = written.field as string;
    }
    if (Object.prototype.hasOwnProperty.call(written, 'accessor')) {
      decoded.accessor = new AccessorObservation(
        plainNumbers(written.accessor) as { [key: string]: Node },
      );
    }
    if (Object.prototype.hasOwnProperty.call(written, 'selection')) {
      decoded.selection = new SelectionObservation(written.selection);
    }
    result[field] = decoded;
  }
  return result;
}

function decodeExpectation(value: Node): Expectation | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const expectation: Expectation = { expect: value.expect as string };
  const fields = decodeValues(value.fields);
  if (fields !== undefined) {
    expectation.fields = fields;
  }
  if (Object.prototype.hasOwnProperty.call(value, 'predicate')) {
    expectation.predicate = plainNumbers(value.predicate);
  }
  if (Object.prototype.hasOwnProperty.call(value, 'order_by')) {
    expectation.order_by = (value.order_by as Node[]).map((item) => item as string);
  }
  for (const bound of ['at_least', 'at_most'] as const) {
    if (!isNil(value[bound])) {
      expectation[bound] = decodeNumber(value[bound]);
    }
  }
  if (isObject(value.position)) {
    const position = value.position as { [key: string]: Node };
    expectation.position = { row: position.row as string, index: decodeNumber(position.index) };
  }
  return expectation;
}

function decodeOutcome(value: Node): OutcomeRef | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  return { command: value.command as string, outcome: value.outcome as string };
}

function decodeShape(value: Node): { [path: string]: Held } | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const result: { [path: string]: Held } = {};
  for (const path of Object.keys(value)) {
    const leaf = value[path] as { [key: string]: Node };
    const held: Held = { holds: leaf.holds as string };
    if (Object.prototype.hasOwnProperty.call(leaf, 'kind')) {
      held.kind = leaf.kind as string;
    }
    if (Object.prototype.hasOwnProperty.call(leaf, 'variants')) {
      held.variants = (leaf.variants as Node[]).map((item) => item as string);
    }
    if (Object.prototype.hasOwnProperty.call(leaf, 'optional')) {
      held.optional = leaf.optional === true;
    }
    result[path] = held;
  }
  return result;
}

function decodeStep(value: Node): Step {
  const written = value as { [key: string]: Node };
  const label = (key: string): string =>
    typeof written[key] === 'string' ? (written[key] as string) : '';
  const step: Step = {
    order: label('order'),
    identity: Object.prototype.hasOwnProperty.call(written, 'identity')
      ? plainNumbers(written.identity)
      : undefined,
    state: label('state'),
    step: label('step'),
    command: label('command'),
    actor: label('actor'),
    event: label('event'),
    error: label('error'),
    view: label('view'),
    binding: label('binding'),
    instance: label('instance'),
    entity: label('entity'),
    field: label('field'),
    instant: label('instant'),
    elapsed: decodeNumber(written.elapsed),
    after: decodeNumber(written.after),
  };
  if (Object.prototype.hasOwnProperty.call(written, 'fields')) {
    step.fields = plainNumbers(written.fields) as { [field: string]: Node };
  }
  if (Object.prototype.hasOwnProperty.call(written, 'payload')) {
    step.payload = plainNumbers(written.payload) as { [field: string]: Node };
  }
  const input = decodeValues(written.input);
  if (input !== undefined) {
    step.input = input;
  }
  const subject = decodeValues(written.subject);
  if (subject !== undefined) step.subject = subject;
  const params = decodeValues(written.params);
  if (params !== undefined) {
    step.params = params;
  }
  const shape = decodeShape(written.shape);
  if (shape !== undefined) {
    step.shape = shape;
  }
  const expectation = decodeExpectation(written.expectation);
  if (expectation !== undefined) {
    step.expectation = expectation;
  }
  const outcome = decodeOutcome(written.outcome);
  if (outcome !== undefined) {
    step.outcome = outcome;
  }
  const force = decodeOutcome(written.force);
  if (force !== undefined) {
    step.force = force;
  }
  if (Object.prototype.hasOwnProperty.call(written, 'check')) {
    step.check = plainNumbers(written.check) as PeriodicCheck;
  }
  if (Object.prototype.hasOwnProperty.call(written, 'response')) {
    step.response = decodeResponseObservation(plainNumbers(written.response));
  }
  if (Object.prototype.hasOwnProperty.call(written, 'left')) {
    step.left = plainNumbers(written.left) as ReadingReference;
  }
  if (Object.prototype.hasOwnProperty.call(written, 'right')) {
    step.right = plainNumbers(written.right) as ReadingReference;
  }
  return step;
}

// ---- admitting one step -----------------------------------------------------------------------------

export function admitReference(value: Node): void {
  const reference = closed(value, 'kind name', '');
  const kind = text(reference.kind);
  switch (kind) {
    case 'domain':
    case 'type':
    case 'entity':
    case 'command':
    case 'event':
    case 'error':
    case 'view':
    case 'actor':
      name(reference.name, false);
      return;
    case 'binding':
    case 'component':
      name(reference.name, true);
      return;
    case 'outcome':
      admitOutcome(reference.name);
      return;
    case 'transition': {
      const transition = closed(reference.name, 'entity transition', '');
      name(transition.entity, false);
      name(transition.transition, false);
      if ((transition.transition as string).includes('.')) {
        throw new Error('transition must be one name segment');
      }
      return;
    }
    default:
      throw new Error(`unsupported semantic reference ${kind}`);
  }
}

export function admitOutcome(value: Node): void {
  const outcome = closed(value, 'command outcome', '');
  name(outcome.command, false);
  name(outcome.outcome, true);
}

export function admitValues(value: Node, major: number, accessors: boolean): void {
  if (!isObject(value)) {
    throw new Error('values must be an object');
  }
  for (const label of Object.keys(value)) {
    const written = value[label];
    if (!isObject(written)) {
      throw new Error('value must be an object');
    }
    const kind = text(written.kind);
    switch (kind) {
      case 'literal':
        closed(written, 'kind value', '');
        admitPayload(written.value);
        break;
      case 'instance':
        closed(written, 'kind instance', '');
        name(written.instance, true);
        break;
      case 'observed_selection': {
        if (major < 6 || !accessors) {
          throw new Error('observed_selection requires suite/6 or /7 invocation input');
        }
        closed(written, 'kind event selection', '');
        name(written.event, false);
        const selection = admitSelection(written.selection);
        for (const selector of selection.plan.selectors) {
          if (selector.operation.kind === 'first') {
            admitPredicateVersion(selector.operation.predicate, major);
          }
        }
        break;
      }
      case 'observed_accessor':
        if (major < 6 || !accessors) {
          throw new Error('observed_accessor requires suite/6 or /7 invocation input');
        }
        closed(written, 'kind event accessor', '');
        name(written.event, false);
        admitAccessor(written.accessor);
        break;
      case 'observed':
        closed(written, 'kind event field', '');
        name(written.event, false);
        text(written.field);
        break;
      default:
        throw new Error(`unsupported scenario value ${kind}`);
    }
  }
}

export function admitPayload(value: Node): void {
  if (value instanceof JsonNumber) {
    if (!Number.isFinite(Number(value.raw))) {
      throw new Error(`non-finite payload number: ${value.raw}`);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      admitPayload(item);
    }
    return;
  }
  if (isObject(value)) {
    for (const key of Object.keys(value)) {
      admitPayload(value[key]);
    }
  }
}

export function admitShape(value: Node): void {
  if (!isObject(value)) {
    throw new Error('shape must be an object');
  }
  for (const path of Object.keys(value)) {
    const leaf = value[path];
    if (!isObject(leaf)) {
      throw new Error('shape leaf must be object');
    }
    const kind = text(leaf.holds);
    let required = 'holds';
    switch (kind) {
      case 'primitive':
        required += ' kind';
        break;
      case 'enum':
        required += ' variants';
        break;
      case 'list':
      case 'map':
      case 'union':
        break;
      default:
        throw new Error('unsupported holds');
    }
    closed(leaf, required, 'optional');
    if (
      Object.prototype.hasOwnProperty.call(leaf, 'optional') &&
      typeof leaf.optional !== 'boolean'
    ) {
      throw new Error('optional must be boolean');
    }
    if (kind === 'primitive') {
      switch (leaf.kind) {
        case 'string':
        case 'boolean':
        case 'integer':
        case 'decimal':
        case 'timestamp':
        case 'duration':
        case 'uuid':
        case 'bytes':
          break;
        default:
          throw new Error('unknown primitive');
      }
    }
    if (kind === 'enum') {
      for (const item of array(leaf.variants)) {
        text(item);
      }
    }
  }
}

export function admitExpectation(value: Node, major: number): void {
  if (!isObject(value)) {
    throw new Error('expectation must be object');
  }
  const tag = text(value.expect);
  if (major < 2 && (tag === 'counts' || tag === 'at')) {
    throw new Error('expectation requires suite/2');
  }
  let required = 'expect';
  let optional = '';
  switch (tag) {
    case 'contains':
    case 'excludes':
      required += ' fields';
      break;
    case 'satisfies':
      required += ' predicate';
      break;
    case 'ranked':
      required += ' order_by';
      break;
    case 'counts':
      optional = 'at_least at_most';
      break;
    case 'at':
      required += ' order_by position';
      optional = 'fields';
      break;
    default:
      throw new Error(`unknown expectation ${tag}`);
  }
  closed(value, required, optional);
  if (Object.prototype.hasOwnProperty.call(value, 'fields')) {
    admitValues(value.fields, major, false);
  }
  for (const key of ['at_least', 'at_most']) {
    if (Object.prototype.hasOwnProperty.call(value, key) && !isNil(value[key])) {
      unsigned(value[key]);
    }
  }
  if (Object.prototype.hasOwnProperty.call(value, 'order_by')) {
    for (const rank of array(value.order_by)) {
      const words = goFields(text(rank));
      if (words.length < 1 || words.length > 2) {
        throw new Error('invalid ranking');
      }
      if (words.length === 2) {
        switch (words[1]) {
          case 'asc':
          case 'ascending':
          case 'desc':
          case 'descending':
            break;
          default:
            throw new Error('invalid ranking direction');
        }
      }
    }
  }
  if (Object.prototype.hasOwnProperty.call(value, 'position')) {
    const position = value.position;
    if (!isObject(position)) {
      throw new Error('invalid position');
    }
    switch (position.row) {
      case 'first':
      case 'last':
        closed(position, 'row', '');
        break;
      case 'nth':
        closed(position, 'row index', '');
        unsigned(position.index);
        break;
      default:
        throw new Error('unknown position');
    }
  }
  if (Object.prototype.hasOwnProperty.call(value, 'predicate')) {
    admitPayload(value.predicate);
    admitPredicateVersion(value.predicate, major);
  }
}

/**
 * admitPredicateEnvelope mirrors the Rust `Predicate::from_node` admission. Structured children
 * and string `not` prefixes spend the same depth budget.
 */
export function admitPredicateEnvelope(value: Node, depth: number): void {
  if (depth > 32) {
    throw new Error('predicate exceeds maximum depth 32');
  }
  if (typeof value === 'boolean') {
    return;
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed.startsWith('not ')) {
      admitPredicateEnvelope(trimmed.slice('not '.length), depth + 1);
      return;
    }
    admitPredicateLeaf(value);
    return;
  }
  if (Array.isArray(value)) {
    for (const child of value) {
      admitPredicateEnvelope(child, depth + 1);
    }
    return;
  }
  if (isObject(value)) {
    for (const key of Object.keys(value)) {
      const child = value[key];
      switch (key) {
        case 'all':
        case 'and':
        case 'all_of':
        case 'any':
        case 'or':
        case 'none':
        case 'none_of_these': {
          if (isNil(child)) {
            // A null is an empty list, not a null literal.
            continue;
          }
          const children = Array.isArray(child) ? child : [child];
          for (const item of children) {
            admitPredicateEnvelope(item, depth + 1);
          }
          break;
        }
        case 'not':
          admitPredicateEnvelope(child, depth + 1);
          break;
        case 'forall':
        case 'exists': {
          const fields = closed(child, 'in as that', '');
          const over = attempt(() => text(fields.in));
          if (over === undefined || !factPath.test(over)) {
            throw new Error('quantifier in must be a fact path');
          }
          const bind = attempt(() => text(fields.as));
          if (bind === undefined || !factPath.test(bind) || bind.includes('.')) {
            throw new Error('quantifier as must be one fact path segment');
          }
          admitPredicateEnvelope(fields.that, depth + 1);
          break;
        }
        default:
          admitPredicatePath(key);
          admitPredicateConstraint(child);
          break;
      }
    }
    return;
  }
  throw new Error('predicate must be a boolean, expression, list or mapping');
}

export function admitPredicateScalar(value: Node): void {
  if (typeof value === 'boolean' || typeof value === 'string' || value instanceof JsonNumber) {
    // Payload admission already checked finite numbers. Any string is legal: an operand falls back
    // to a literal when text is not a valid fact path.
    return;
  }
  throw new Error('predicate operand must be a boolean, number or string');
}

export function admitPredicateConstraint(value: Node): void {
  if (Array.isArray(value)) {
    for (const item of value) {
      admitPredicateScalar(item);
    }
    return;
  }
  if (isObject(value)) {
    // Every operator is checked; a known operator cannot hide a malformed neighbour.
    for (const operator of Object.keys(value)) {
      const operand = value[operator];
      switch (operator) {
        case 'eq':
        case 'equals':
        case '==':
        case 'ne':
        case 'not_equals':
        case '!=':
        case 'lt':
        case '<':
        case 'le':
        case 'lte':
        case '<=':
        case 'gt':
        case '>':
        case 'ge':
        case 'gte':
        case '>=':
          admitPredicateScalar(operand);
          break;
        case 'any_of':
        case 'in':
        case 'one_of':
        case 'none_of':
        case 'not_in': {
          if (isNil(operand)) {
            // A null is the empty sequence shorthand, not a null literal.
            continue;
          }
          const items = Array.isArray(operand) ? operand : [operand];
          for (const item of items) {
            admitPredicateScalar(item);
          }
          break;
        }
        case 'exists':
        case 'defined':
          if (typeof operand !== 'boolean') {
            throw new Error(`predicate ${operator} takes a boolean`);
          }
          break;
        case 'truthy':
          // The truthy form ignores its operand; payload validity still applies.
          break;
        default:
          throw new Error(`unknown predicate constraint operator ${quoteGo(operator)}`);
      }
    }
    return;
  }
  admitPredicateScalar(value);
}

export function admitStep(value: Node, major: number): void {
  if (!isObject(value)) {
    throw new Error('step must be object');
  }
  const tag = text(value.step);
  let required = 'step';
  let optional = '';
  switch (tag) {
    case 'expect_response_payload':
      if (major < 8) {
        throw new Error('response payload requires suite/8 or /9');
      }
      required += ' response';
      break;
    case 'check_periodic':
      if (major < 6) {
        throw new Error('periodic checks require suite/6');
      }
      required += ' check';
      break;
    case 'establish_entity':
      if (major < 6) {
        throw new Error('entity setup requires suite/6');
      }
      required += ' instance entity identity fields state';
      break;
    case 'expect_reading_order':
      if (major < 6) {
        throw new Error('clock reading requires suite/6 or /7');
      }
      required += ' left right order';
      break;
    case 'configure_external_outcome':
      required += ' force';
      break;
    case 'execute_command':
      required += ' command';
      optional = 'actor input';
      break;
    case 'expect_outcome':
      required += ' outcome';
      break;
    case 'snapshot_subject':
      if (major < 10) throw new Error('subject snapshots require suite/10 or /11');
      required += ' view subject';
      break;
    case 'expect_subject_unchanged':
      if (major < 10) throw new Error('subject preservation requires suite/10 or /11');
      required += ' view';
      break;
    case 'expect_no_error':
      if (major < 10) throw new Error('no-error assertions require suite/10 or /11');
      break;
    case 'expect_error':
      required += ' error';
      optional = 'fields';
      break;
    case 'expect_event':
    case 'eventually_event':
      required += ' event';
      optional = 'payload shape';
      break;
    case 'expect_no_event':
    case 'redeliver_event':
      required += ' event';
      break;
    case 'capture_instance':
      required += ' instance entity event field';
      break;
    case 'expect_invocation':
      required += ' binding command';
      optional = 'input';
      break;
    case 'query_view':
      required += ' view';
      optional = 'params';
      break;
    case 'expect_view':
      required += ' view expectation';
      break;
    case 'eventually_view':
      required += ' view expectation';
      optional = 'params';
      break;
    case 'mark_instant':
      if (major < 3) {
        throw new Error('step requires suite/3');
      }
      required += ' instant';
      break;
    case 'expect_not_before':
    case 'expect_within':
      if (major < 3) {
        throw new Error('step requires suite/3');
      }
      required += ' instant elapsed';
      break;
    case 'expect_quiet':
      if (major < 3) {
        throw new Error('step requires suite/3');
      }
      required += ' event instant elapsed';
      break;
    case 'expect_halt':
    case 'eventually_halt':
      if (major < 4) {
        throw new Error('step requires suite/4');
      }
      required += ' view after';
      optional = 'params';
      break;
    default:
      throw new Error(`unsupported step ${tag}`);
  }
  closed(value, required, optional);
  for (const key of Object.keys(value)) {
    const held = value[key];
    switch (key) {
      case 'response':
        admitResponse(held);
        break;
      case 'check':
        admitPeriodic(held);
        break;
      case 'left':
      case 'right':
        admitReading(held);
        break;
      case 'order': {
        const order = text(held);
        if (order !== 'before' && order !== 'equal' && order !== 'after') {
          throw new Error('invalid reading order');
        }
        break;
      }
      case 'force':
      case 'outcome':
        admitOutcome(held);
        break;
      case 'command':
      case 'entity':
      case 'event':
      case 'view':
      case 'error':
        name(held, false);
        break;
      case 'actor':
        if (!isNil(held)) {
          name(held, false);
        }
        break;
      case 'binding':
      case 'instance':
      case 'instant':
        name(held, true);
        break;
      case 'state': {
        const state = text(held);
        if (!stateName.test(state)) {
          throw new Error('invalid state name');
        }
        break;
      }
      case 'identity':
        admitPayload(held);
        break;
      case 'field':
        text(held);
        break;
      case 'input':
      case 'params':
      case 'subject':
        admitValues(held, major, tag === 'expect_invocation');
        break;
      case 'payload':
      case 'fields':
        if (!isObject(held)) {
          throw new Error('payload must be object');
        }
        admitPayload(held);
        break;
      case 'shape':
        admitShape(held);
        break;
      case 'expectation':
        admitExpectation(held, major);
        break;
      case 'elapsed':
      case 'after': {
        const n = unsigned(held);
        if (key === 'elapsed' && n > 4294967295n) {
          throw new Error('elapsed exceeds u32');
        }
        break;
      }
      default:
        break;
    }
  }
}

/** Validate setup structure before any target callback. The adapter separately validates its model. */
export function admitEntitySetups(steps: Node[]): void {
  let hasSetup = false;
  for (const raw of steps) {
    if ((raw as { [key: string]: Node }).step === 'establish_entity') {
      hasSetup = true;
    }
  }
  if (!hasSetup) {
    return;
  }
  const instances: { [instance: string]: boolean } = {};
  const identities: { [key: string]: Node }[] = [];
  let asserted = false;
  for (const raw of steps) {
    const step = raw as { [key: string]: Node };
    switch (step.step as string) {
      case 'establish_entity': {
        asserted = false;
        admitSetupLiteral(step.identity, 0);
        const fields = step.fields as { [key: string]: Node };
        for (const key of Object.keys(fields)) {
          admitSetupLiteral(fields[key], 0);
        }
        const instance = step.instance as string;
        if (instances[instance] === true) {
          throw new Error('duplicate setup instance');
        }
        instances[instance] = true;
        if (isNil(step.identity)) {
          throw new Error('setup identity cannot be null');
        }
        for (const previous of identities) {
          if (previous.entity === step.entity && equal(previous.identity, step.identity)) {
            throw new Error('duplicate qualified entity identity');
          }
        }
        for (const key of Object.keys(fields)) {
          if (!qualifiedName.test(key) || key.includes('.') || key.includes('-')) {
            throw new Error('invalid entity field name');
          }
        }
        identities.push(step);
        break;
      }
      case 'capture_instance': {
        const instance = step.instance as string;
        if (instances[instance] === true) {
          throw new Error('duplicate setup instance binding');
        }
        instances[instance] = true;
        break;
      }
      case 'check_periodic':
      case 'expect_view':
      case 'eventually_view':
      case 'expect_outcome':
      case 'expect_no_error':
      case 'expect_subject_unchanged':
      case 'expect_error':
      case 'expect_event':
      case 'expect_no_event':
      case 'eventually_event':
      case 'expect_invocation':
      case 'expect_not_before':
      case 'expect_within':
      case 'expect_quiet':
      case 'expect_halt':
      case 'eventually_halt':
        asserted = true;
        break;
      default:
        break;
    }
  }
  if (!asserted) {
    throw new Error('setup requires an assertion');
  }
}

export function admitSetupLiteral(value: Node, depth: number): void {
  if (depth > 120) {
    throw new Error('setup literal nesting exceeds 120');
  }
  if (Array.isArray(value)) {
    for (const child of value) {
      admitSetupLiteral(child, depth + 1);
    }
    return;
  }
  if (isObject(value)) {
    for (const key of Object.keys(value)) {
      admitSetupLiteral(value[key], depth + 1);
    }
  }
}

// ---- report/2 ---------------------------------------------------------------------------------------

export function countDocument(
  suite: Suite,
  identity: Identity,
  results: ScenarioResult[],
  now: number,
): { [key: string]: Node } {
  if (!validUTF8(identity.name) || !validUTF8(identity.version)) {
    throw new Error('implementation identity is not UTF-8');
  }
  if (now < 0) {
    throw new Error('negative report/2 clock');
  }
  const counts: Record<
    'total' | 'passed' | 'failed' | 'error' | 'unsupported' | 'skipped',
    number
  > = {
    total: results.length,
    passed: 0,
    failed: 0,
    error: 0,
    unsupported: 0,
    skipped: 0,
  };
  const outcomes: Record<'passed' | 'failed' | 'error' | 'unsupported' | 'skipped', string[]> = {
    passed: [],
    failed: [],
    error: [],
    unsupported: [],
    skipped: [],
  };
  const seen: { [id: string]: boolean } = {};
  for (const result of results) {
    if (seen[result.id] === true) {
      throw new Error('duplicate terminal result');
    }
    seen[result.id] = true;
    if (!Object.prototype.hasOwnProperty.call(suite.scenarios, result.id)) {
      throw new Error('unexpected terminal result');
    }
    if (
      result.status !== statusPassed &&
      result.status !== statusFailed &&
      result.status !== statusSkipped
    ) {
      throw new Error('unsupported terminal status');
    }
    const verdict = result.status as 'passed' | 'failed' | 'skipped';
    counts[verdict] += 1;
    outcomes[verdict].push(result.id);
  }
  // Retained as a second line of defence: `writeCountReport` refuses an incomplete run before
  // reaching here, so this fires only if a caller builds a document by another route.
  if (Object.keys(seen).length !== Object.keys(suite.scenarios).length) {
    throw new Error(
      `incomplete execution: ${Object.keys(seen).length} of ${Object.keys(suite.scenarios).length} ` +
        'scenarios accounted for',
    );
  }
  for (const ids of Object.values(outcomes)) {
    sortStrings(ids);
  }
  let execution = 'passed';
  if (counts.failed > 0) {
    execution = 'failed';
  } else if (counts.skipped > 0) {
    execution = 'inconclusive';
  }
  let conformance = 'inconclusive';
  if (execution === 'failed') {
    conformance = 'failed';
  } else if (execution === 'passed' && counts.total > 0 && completeCoverage(suite.coverage)) {
    conformance = 'passed';
  }
  const digest = createHash('sha256').update(suite.original, 'utf8').digest('hex');
  let coverage: { [key: string]: Node } = { knowledge: 'unknown' };
  if (suite.coverage !== undefined) {
    coverage = {};
    for (const key of ['knowledge', 'selection', 'counts', 'refused']) {
      coverage[key] = suite.coverage[key];
    }
  }
  return {
    format: 'ess-conformance-report/2',
    specification: `${suite.provenance.system}/${suite.provenance.specification_version}`,
    spec_digest: suite.provenance.spec_digest,
    implementation: `${identity.name} ${identity.version}`,
    producer_profile: 'go-scenario-status/1',
    suite: {
      version: suite.provenance.suite_version,
      digest_profile: 'sha256-json-bytes/1',
      digest: `sha256:${digest}`,
    },
    execution_status: execution,
    conformance_status: conformance,
    counts,
    outcomes,
    coverage,
    policy: 'complete-selection/1',
    completed_at: now,
  };
}

export function writeCountReport(
  t: TestScope,
  suite: Suite,
  identity: Identity,
  results: ScenarioResult[],
  terminated: number,
  strict: boolean,
): void {
  const refusal = accountForEveryScenario(suite, terminated);
  if (refusal !== null) {
    throw new Error(`report/2 refused: ${refusal.message}`);
  }
  let document: { [key: string]: Node };
  try {
    document = countDocument(suite, identity, results, reportNow());
  } catch (error) {
    throw new Error(`report/2 refused: ${errorText(error)}`);
  }
  let encoded: string;
  try {
    encoded = countCanonical(document);
  } catch (error) {
    throw new Error(`report/2 encoding: ${errorText(error)}`);
  }
  const path = process.env.ESS_REPORT_OUT ?? '';
  if (path !== '') {
    writeFileSync(path, encoded, 'utf8');
  }
  if (strict && document.conformance_status !== 'passed') {
    if (suite.coverage === undefined) {
      throw new Error(
        `strict conformance: ${String(document.conformance_status)} (legacy suite coverage is unknown)`,
      );
    }
    throw new Error(`strict conformance: ${String(document.conformance_status)}`);
  }
  t.diagnostic(
    `report/2: ${String(document.execution_status)}, written to ${path === '' ? '(nowhere)' : path}`,
  );
}

/** Canonical report/2 contains only unsigned integer scalars; the digits avoid binary64 loss. */
export function countCanonical(document: Node): string {
  const value = strictJSON(goMarshal(document));
  const quote = (text_: string): string => {
    let out = '"';
    for (const character of text_) {
      const code = character.codePointAt(0) as number;
      switch (character) {
        case '"':
        case '\\':
          out += `\\${character}`;
          continue;
        case '\n':
          out += '\\n';
          continue;
        case '\r':
          out += '\\r';
          continue;
        case '\t':
          out += '\\t';
          continue;
        case '\b':
          out += '\\b';
          continue;
        case '\f':
          out += '\\f';
          continue;
        default:
          break;
      }
      if (code < 32) {
        out += `\\u${code.toString(16).padStart(4, '0')}`;
      } else {
        out += character;
      }
    }
    return `${out}"`;
  };
  const write = (held: Node, depth: number): string => {
    const indent = (level: number): string => '  '.repeat(level);
    if (isNil(held)) {
      return 'null';
    }
    if (held instanceof JsonNumber) {
      unsigned(held);
      return held.raw;
    }
    if (typeof held === 'string') {
      return quote(held);
    }
    if (Array.isArray(held)) {
      if (held.length === 0) {
        return '[]';
      }
      const parts = held.map((item, position) => {
        const written = `${indent(depth + 1)}${write(item, depth + 1)}`;
        return position < held.length - 1 ? `${written},\n` : `${written}\n`;
      });
      return `[\n${parts.join('')}${indent(depth)}]`;
    }
    if (isObject(held)) {
      const keys = sortStrings(Object.keys(held));
      if (keys.length === 0) {
        return '{}';
      }
      const parts = keys.map((key, position) => {
        const written = `${indent(depth + 1)}${quote(key)}: ${write(held[key], depth + 1)}`;
        return position < keys.length - 1 ? `${written},\n` : `${written}\n`;
      });
      return `{\n${parts.join('')}${indent(depth)}}`;
    }
    throw new Error('unexpected report scalar');
  };
  return `${write(value, 0)}\n`;
}

// ---- the accessor: an exact invocation-member assertion, not a generic JSON path ----------------

export interface AccessorField {
  name: string;
  type: string;
}

export interface AccessorShape {
  variants?: string[];
  kind: string;
  name: string;
  of?: AccessorShape;
}

export interface AccessorOperation {
  kind: string;
  field: AccessorField;
  next: number;
  tag: string;
  variants: { [label: string]: number };
}

export interface AccessorNode {
  source: string;
  shape: AccessorShape;
  position: number;
  operation: AccessorOperation;
  leaf: string | null;
  may_miss: boolean;
  depth: number;
}

export interface AccessorPlan {
  segments: string[];
  root: AccessorField;
  start: number;
  nodes: AccessorNode[];
}

/** accessorTypeFacts is a closed certificate of the nominal structure an observer must inspect. */
export interface AccessorTypeFacts {
  nodes: { [name: string]: AccessorTypeBody };
}

export interface AccessorTypeBody {
  kind: string;
  of: string;
  members: string[];
}

const ACCESSOR_SEGMENT = /^[A-Za-z][A-Za-z0-9_]*$/;

function decodeAccessorField(value: Node): AccessorField {
  const held = isObject(value) ? value : {};
  return {
    name: typeof held.name === 'string' ? held.name : '',
    type: typeof held.type === 'string' ? held.type : '',
  };
}

function decodeAccessorShape(value: Node): AccessorShape {
  const held = isObject(value) ? value : {};
  const shape: AccessorShape = {
    kind: typeof held.kind === 'string' ? held.kind : '',
    name: typeof held.name === 'string' ? held.name : '',
  };
  if (Array.isArray(held.variants)) {
    shape.variants = held.variants.map((item: Node) => String(item));
  }
  if (isObject(held.of)) {
    shape.of = decodeAccessorShape(held.of);
  }
  return shape;
}

function decodeAccessorOperation(value: Node): AccessorOperation {
  const held = isObject(value) ? value : {};
  const variants: { [label: string]: number } = {};
  if (isObject(held.variants)) {
    for (const label of Object.keys(held.variants)) {
      variants[label] = decodeNumber((held.variants as { [key: string]: Node })[label]);
    }
  }
  return {
    kind: typeof held.kind === 'string' ? held.kind : '',
    field: decodeAccessorField(held.field),
    next: decodeNumber(held.next),
    tag: typeof held.tag === 'string' ? held.tag : '',
    variants,
  };
}

function decodeAccessorNode(value: Node): AccessorNode {
  const held = isObject(value) ? value : {};
  return {
    source: typeof held.source === 'string' ? held.source : '',
    shape: decodeAccessorShape(held.shape),
    position: decodeNumber(held.position),
    operation: decodeAccessorOperation(held.operation),
    leaf: typeof held.leaf === 'string' ? held.leaf : null,
    may_miss: held.may_miss === true,
    depth: decodeNumber(held.depth),
  };
}

export function decodeAccessorPlan(value: Node): AccessorPlan {
  const held = isObject(value) ? value : {};
  return {
    segments: Array.isArray(held.segments) ? held.segments.map((item: Node) => String(item)) : [],
    root: decodeAccessorField(held.root),
    start: decodeNumber(held.start),
    nodes: Array.isArray(held.nodes) ? held.nodes.map(decodeAccessorNode) : [],
  };
}

export function decodeAccessorTypeFacts(value: Node): AccessorTypeFacts {
  const held = isObject(value) ? value : {};
  const nodes: { [name: string]: AccessorTypeBody } = {};
  if (isObject(held.nodes)) {
    for (const label of Object.keys(held.nodes)) {
      const body = (held.nodes as { [key: string]: Node })[label];
      const written = isObject(body) ? body : {};
      nodes[label] = {
        kind: typeof written.kind === 'string' ? written.kind : '',
        of: typeof written.of === 'string' ? written.of : '',
        members: Array.isArray(written.members)
          ? written.members.map((item: Node) => String(item))
          : [],
      };
    }
  }
  return { nodes };
}

/**
 * accessorPreflight counts borrowed observation documents before the admitter builds their maps.
 *
 * The size of a member is the source range it occupied, which is what the Go decoder hands its
 * own counter. A document that does not parse is left to the closed admitter to diagnose.
 */
export function accessorPreflight(raw: string): void {
  let decoded: { value: Node; spans: WeakMap<object, [number, number]> };
  try {
    decoded = strictJSONWithSpans(raw);
  } catch {
    return; // The ordinary closed admitter diagnoses malformed legacy documents.
  }
  const root = decoded.value;
  if (!isObject(root) || !isObject(root.scenarios)) {
    return;
  }
  const size = (node: Node): number => {
    if (node !== null && typeof node === 'object') {
      const span = decoded.spans.get(node as object);
      if (span !== undefined) {
        return span[1] - span[0];
      }
    }
    return goMarshal(node).length;
  };
  let total = 0;
  for (const id of Object.keys(root.scenarios)) {
    const scenario = (root.scenarios as { [key: string]: Node })[id];
    if (!isObject(scenario) || !Array.isArray(scenario.steps)) {
      continue;
    }
    for (const step of scenario.steps as Node[]) {
      if (!isObject(step) || !isObject(step.input)) {
        continue;
      }
      const input = step.input as { [key: string]: Node };
      for (const field of Object.keys(input)) {
        const value = input[field];
        if (!isObject(value)) {
          continue;
        }
        let measured = 0;
        for (const member of ['accessor', 'selection']) {
          if (!Object.prototype.hasOwnProperty.call(value, member)) {
            continue;
          }
          const bytes = size(value[member]);
          if (bytes > 2 * 1048576) {
            throw new Error('AccessorResource: raw observation bytes');
          }
          measured += bytes;
        }
        if (value.kind === 'observed_accessor' || value.kind === 'observed_selection') {
          total += measured;
          if (total > 16 * 1048576) {
            throw new Error('AccessorResource: suite observation bytes');
          }
        }
      }
    }
  }
}

export function admitAccessorField(value: Node): void {
  const field = closed(value, 'name type', 'wire display summary');
  const label = attempt(() => text(field.name));
  if (label === undefined || !ACCESSOR_SEGMENT.test(label)) {
    throw new Error('invalid accessor field name');
  }
  for (const key of ['wire', 'display', 'summary']) {
    if (Object.prototype.hasOwnProperty.call(field, key) && !isNil(field[key])) {
      text(field[key]);
    }
  }
}

const ACCESSOR_PRIMITIVES = [
  'String',
  'Boolean',
  'Integer',
  'Decimal',
  'Binary64',
  'Timestamp',
  'Duration',
  'Uuid',
  'Bytes',
];

/** The key follows the closed type ordering, including segmented qualified-name ordering. */
export function accessorType(source: string, depth: number): [string, string] {
  if (depth > 32) {
    throw new Error('accessor type nesting bound');
  }
  const trimmed = source.trim();
  for (let index = 0; index < ACCESSOR_PRIMITIVES.length; index += 1) {
    if (trimmed === ACCESSOR_PRIMITIVES[index]) {
      return [trimmed, `0${index}`];
    }
  }
  const wrappers = ['Optional', 'List', 'Map'];
  for (let index = 0; index < wrappers.length; index += 1) {
    const wrapper = itemAt(wrappers, index);
    if (trimmed.startsWith(`${wrapper}<`) && trimmed.endsWith('>')) {
      let inner = trimmed.slice(wrapper.length + 1, trimmed.length - 1);
      let prefix = `${wrapper}<`;
      let keyPrefix = String(index + 2);
      if (wrapper === 'Map') {
        const comma = inner.indexOf(',');
        if (comma < 0) {
          throw new Error('invalid accessor map key');
        }
        const key = inner.slice(0, comma).trim();
        const rest = inner.slice(comma + 1);
        if (!accessorPrimitive(key) || key === 'Binary64') {
          throw new Error('invalid accessor map key');
        }
        const [, order] = accessorType(key, depth + 1);
        prefix += `${key}, `;
        keyPrefix += order;
        inner = rest;
      }
      const [canonical, order] = accessorType(inner, depth + 1);
      return [`${prefix}${canonical}>`, keyPrefix + order];
    }
  }
  name(trimmed, false);
  return [trimmed, `1${trimmed.split('.').join('\u0000')}\u0000`];
}

export function normalizeAccessorTypes(observation: AccessorObservation): void {
  const canonical = (source: string): string => accessorType(source, 0)[0];
  observation.target = canonical(observation.target);
  observation.plan.root.type = canonical(observation.plan.root.type);
  for (const node of observation.plan.nodes) {
    node.source = canonical(node.source);
    if (node.leaf !== null) {
      node.leaf = canonical(node.leaf);
    }
    if (node.operation.kind === 'field') {
      node.operation.field.type = canonical(node.operation.field.type);
    }
  }
  for (const label of Object.keys(observation.types.nodes)) {
    const body = observation.types.nodes[label] as AccessorTypeBody;
    if (body.kind === 'newtype') {
      body.of = canonical(body.of);
    }
    for (let index = 0; index < body.members.length; index += 1) {
      body.members[index] = canonical(itemAt(body.members, index));
    }
  }
}

/** shapeCanonical is the bytes `json.Marshal` writes for one shape, field order and all. */
function shapeCanonical(shape: AccessorShape): string {
  const variants =
    shape.variants === undefined
      ? 'null'
      : `[${shape.variants.map((item) => goMarshal(item)).join(',')}]`;
  const of = shape.of === undefined ? 'null' : shapeCanonical(shape.of);
  return `{"variants":${variants},"kind":${goMarshal(shape.kind)},"name":${goMarshal(shape.name)},"of":${of}}`;
}

export function checkAccessorShape(node: AccessorNode, nodes: AccessorNode[]): void {
  const invalid = new Error('accessor wire shape disagrees with typed operation');
  let source = node.source;
  let shape = node.shape;
  const optional = accessorOptional(source)[1];
  if (optional && shape.kind !== 'optional') {
    throw invalid;
  }
  if (shape.kind === 'optional') {
    if (shape.of === undefined) {
      throw invalid;
    }
    shape = shape.of;
    if (
      !optional &&
      (accessorPrimitive(source) || source.startsWith('List<') || source.startsWith('Map<'))
    ) {
      throw invalid;
    }
  }
  for (;;) {
    const [inner, ok] = accessorOptional(source);
    if (!ok) {
      break;
    }
    source = inner;
  }
  if (
    accessorPrimitive(source) &&
    (shape.kind !== 'primitive' || shape.name !== source.toLowerCase())
  ) {
    throw invalid;
  }
  if (source.startsWith('List<') && shape.kind !== 'sequence') {
    throw invalid;
  }
  if (source.startsWith('Map<') && shape.kind !== 'object') {
    throw invalid;
  }
  switch (node.operation.kind) {
    case 'field':
    case 'union':
      if (node.shape.kind !== 'object') {
        throw invalid;
      }
      break;
    case 'newtype':
    case 'optional': {
      let next = itemAt(nodes, node.operation.next).shape;
      if (node.operation.kind === 'optional' && next.kind === 'optional') {
        next = next.of as AccessorShape;
      }
      const left = shapeCanonical(node.operation.kind === 'newtype' ? node.shape : shape);
      if (left !== shapeCanonical(next)) {
        throw invalid;
      }
      break;
    }
    default:
      break;
  }
}

export function accessorOptional(source: string): [string, boolean] {
  if (source.startsWith('Optional<') && source.endsWith('>')) {
    return [source.slice('Optional<'.length, source.length - 1), true];
  }
  return [source, false];
}

export function accessorPrimitive(source: string): boolean {
  return ACCESSOR_PRIMITIVES.includes(source);
}

export function accessorCollection(source: string): [string, boolean] {
  if (source.startsWith('List<') && source.endsWith('>')) {
    return [source.slice('List<'.length, source.length - 1), true];
  }
  if (source.startsWith('Map<') && source.endsWith('>')) {
    const inner = source.slice('Map<'.length, source.length - 1);
    const at = inner.indexOf(', ');
    if (at < 0 || !accessorPrimitive(inner.slice(0, at))) {
      throw new Error('invalid accessor map type');
    }
    return [inner.slice(at + 2), true];
  }
  return ['', false];
}

export function accessorChildren(operation: AccessorOperation): number[] {
  switch (operation.kind) {
    case 'leaf':
    case 'missing':
      return [];
    case 'field':
    case 'optional':
    case 'newtype':
      return [operation.next];
    case 'union':
      return sortStrings(Object.keys(operation.variants)).map(
        (label) => operation.variants[label] as number,
      );
    default:
      return [];
  }
}

/**
 * accessorCompactBytes counts the representation the shared limit is stated in.
 *
 * Go escapes U+2028 and U+2029 even with HTML escaping disabled and the Rust compact writer emits
 * their UTF-8 bytes. Counted the same way here, without mistaking an escaped backslash followed by
 * "u2028" for a rune.
 */
export function accessorCompactBytes(raw: string): number {
  let size = Buffer.byteLength(raw, 'utf8');
  for (let index = 0; index < raw.length; index += 1) {
    if (raw[index] !== '\\') {
      continue;
    }
    if (
      index + 5 < raw.length &&
      raw[index + 1] === 'u' &&
      raw.slice(index + 2, index + 5) === '202' &&
      (raw[index + 5] === '8' || raw[index + 5] === '9')
    ) {
      size -= 3;
      index += 5;
    } else {
      index += 1; // Skip the escaped character, especially a second backslash.
    }
  }
  return size;
}

/** AccessorObservation is one declared traversal into an observed payload. */
export class AccessorObservation {
  types: AccessorTypeFacts;
  plan: AccessorPlan;
  target: string;

  constructor(value: Node) {
    const held = isObject(value) ? value : {};
    this.target = typeof held.target === 'string' ? held.target : '';
    this.plan = decodeAccessorPlan(held.plan);
    this.types = decodeAccessorTypeFacts(held.types);
  }

  /** assignment answers how many Optional layers the leaf carries, and how many the target adds. */
  assignment(): [number, number] {
    const plan = this.plan;
    if (
      plan.start < 0 ||
      plan.start >= plan.nodes.length ||
      itemAt(plan.nodes, plan.start).leaf === null
    ) {
      throw new Error('invalid accessor root');
    }
    const start = itemAt(plan.nodes, plan.start);
    let leaf = start.leaf as string;
    if (start.may_miss) {
      if (!accessorOptional(this.target)[1]) {
        throw new Error('partial accessor requires Optional target');
      }
    }
    let target = this.target;
    let added = 0;
    while (target !== leaf) {
      const [inner, ok] = accessorOptional(target);
      if (!ok || added >= 128) {
        throw new Error('accessor has no identity-first assignment');
      }
      target = inner;
      added += 1;
    }
    let depth = 0;
    for (;;) {
      const [inner, ok] = accessorOptional(leaf);
      if (!ok) {
        break;
      }
      leaf = inner;
      depth += 1;
      if (depth > 128) {
        throw new Error('accessor Optional bound');
      }
    }
    if (depth >= 2 && added === 0) {
      throw new Error('AmbiguousOptionalObservation');
    }
    return [depth, added];
  }

  evaluate(payload: { [field: string]: Node }): [Node, boolean] {
    const [depth, added] = this.assignment();
    let value: Node = payload[this.plan.root.name];
    let present = Object.prototype.hasOwnProperty.call(payload, this.plan.root.name);
    let id = this.plan.start;
    for (let count = 0; count < 128; count += 1) {
      const node = itemAt(this.plan.nodes, id);
      const operation = node.operation;
      if (present) {
        if (!accessorShapeAdmits(node.shape, value)) {
          throw new Error('accessor has wrong declared payload kind');
        }
      } else if (node.shape.kind !== 'optional') {
        throw new Error('required accessor member missing');
      }
      switch (operation.kind) {
        case 'missing':
          return [null, false];
        case 'leaf':
          if (!present || isNil(value)) {
            if (depth === 0) {
              throw new Error('required accessor terminal missing/null');
            }
            return [null, added > 0];
          }
          return [value, true];
        case 'optional':
          if (!present || isNil(value)) {
            return [null, false];
          }
          id = operation.next;
          break;
        case 'newtype':
          id = operation.next;
          break;
        case 'field': {
          if (!isObject(value)) {
            throw new Error('accessor requires struct object');
          }
          const fields = value as { [key: string]: Node };
          present = Object.prototype.hasOwnProperty.call(fields, operation.field.name);
          value = fields[operation.field.name];
          id = operation.next;
          break;
        }
        case 'union': {
          if (!isObject(value)) {
            throw new Error('accessor requires tagged union');
          }
          const fields = value as { [key: string]: Node };
          const tag = fields[operation.tag];
          if (typeof tag !== 'string') {
            throw new Error('accessor discriminator missing or not text');
          }
          if (!Object.prototype.hasOwnProperty.call(operation.variants, tag)) {
            throw new Error('unknown accessor discriminator');
          }
          const next = operation.variants[tag] as number;
          const content = operation.tag === 'value' ? 'content' : 'value';
          present = Object.prototype.hasOwnProperty.call(fields, content);
          value = fields[content];
          if (!present) {
            throw new Error('accessor union payload missing');
          }
          id = next;
          break;
        }
        default:
          break;
      }
    }
    throw new Error('accessor operation budget exceeded');
  }
}

export function admitAccessor(value: Node): AccessorObservation {
  return admitAccessorMode(value, false);
}

export function admitAccessorMode(value: Node, item: boolean): AccessorObservation {
  const root = closed(value, 'plan target types', '');
  const planned = closed(root.plan, 'segments root start nodes', '');
  admitAccessorField(planned.root);
  const raw = goMarshal(value, false);
  if (accessorCompactBytes(raw) > 1048576) {
    throw new Error('AccessorResource: observation bytes');
  }
  const rawNodes = attempt(() => array(planned.nodes));
  if (rawNodes === undefined || rawNodes.length > 4096) {
    throw new Error('AccessorResource: nodes');
  }
  for (const rawNode of rawNodes) {
    const node = closed(rawNode, 'source shape position operation leaf may_miss depth', '');
    const operation = node.operation;
    if (!isObject(operation)) {
      throw new Error('invalid accessor operation');
    }
    let required = 'kind';
    switch (operation.kind) {
      case 'leaf':
      case 'missing':
        break;
      case 'field':
        required += ' field next';
        admitAccessorField(operation.field);
        break;
      case 'optional':
      case 'newtype':
        required += ' next';
        break;
      case 'union':
        required += ' tag variants';
        break;
      default:
        throw new Error('unsupported accessor operation');
    }
    closed(operation, required, '');
    admitAccessorShape(node.shape, 0);
  }
  const observation = new AccessorObservation(plainNumbers(strictJSON(raw)));
  normalizeAccessorTypes(observation);
  const plan = observation.plan;
  let minimum = 2;
  let maximum = 3;
  if (item) {
    minimum = 1;
    maximum = 4;
    if (plan.root.name !== 'item') {
      throw new Error('invalid selection item root');
    }
  }
  if (
    plan.segments.length < minimum ||
    plan.segments.length > maximum ||
    plan.start < 0 ||
    plan.start >= plan.nodes.length ||
    plan.root.name !== plan.segments[0]
  ) {
    throw new Error('invalid accessor root');
  }
  for (const segment of plan.segments) {
    if (!ACCESSOR_SEGMENT.test(segment)) {
      throw new Error('invalid accessor segment');
    }
  }
  const rootNode = itemAt(plan.nodes, plan.start);
  if (rootNode.source !== plan.root.type || rootNode.position !== 1) {
    throw new Error('accessor root type differs');
  }
  let edges = 0;
  let previousKey = '';
  let previousPosition = -1;
  for (const node of plan.nodes) {
    const key = attempt(() => accessorType(node.source, 0)[1]);
    if (
      key === undefined ||
      node.position < 0 ||
      goLess(key, previousKey) ||
      (key === previousKey && node.position <= previousPosition)
    ) {
      throw new Error('invalid or unsorted accessor node type');
    }
    previousKey = key;
    previousPosition = node.position;
    const children = accessorChildren(node.operation);
    edges += children.length;
    if (edges > 16384) {
      throw new Error('AccessorResource: edges');
    }
    for (const id of children) {
      if (id < 0 || id >= plan.nodes.length) {
        throw new Error('dangling accessor edge');
      }
    }
    checkAccessorShape(node, plan.nodes);
    if (
      node.operation.kind === 'field' ||
      node.operation.kind === 'newtype' ||
      node.operation.kind === 'union'
    ) {
      if (failed(() => name(node.source, false)) || accessorPrimitive(node.source)) {
        throw new Error('accessor traversal requires a nominal source');
      }
    }
    const operation = node.operation;
    switch (operation.kind) {
      case 'leaf':
        if (node.position !== plan.segments.length) {
          throw new Error('early accessor leaf');
        }
        break;
      case 'missing':
        if (node.position >= plan.segments.length) {
          throw new Error('missing accessor terminal');
        }
        break;
      case 'field':
        if (
          node.position >= plan.segments.length ||
          operation.field.name !== plan.segments[node.position] ||
          itemAt(plan.nodes, operation.next).source !== operation.field.type ||
          itemAt(plan.nodes, operation.next).position !== node.position + 1
        ) {
          throw new Error('accessor field type differs');
        }
        break;
      case 'optional': {
        const [inner, ok] = accessorOptional(node.source);
        if (
          !ok ||
          node.position >= plan.segments.length ||
          itemAt(plan.nodes, operation.next).source !== inner ||
          itemAt(plan.nodes, operation.next).position !== node.position
        ) {
          throw new Error('accessor Optional type differs');
        }
        break;
      }
      case 'newtype':
        if (
          itemAt(plan.nodes, operation.next).position !== node.position ||
          node.position >= plan.segments.length
        ) {
          throw new Error('invalid accessor wrapper');
        }
        break;
      case 'union': {
        if (
          operation.tag === '' ||
          Object.keys(operation.variants).length === 0 ||
          node.position >= plan.segments.length
        ) {
          throw new Error('invalid accessor union');
        }
        for (const id of children) {
          if (itemAt(plan.nodes, id).position !== node.position) {
            throw new Error('accessor union position differs');
          }
        }
        break;
      }
      default:
        break;
    }
  }
  const pending: { id: number; done: boolean }[] = [{ id: plan.start, done: false }];
  const marks: number[] = new Array(plan.nodes.length).fill(0) as number[];
  while (pending.length > 0) {
    const item_ = pending.pop() as { id: number; done: boolean };
    const node = itemAt(plan.nodes, item_.id);
    if (item_.done) {
      let depth = 1;
      let leaf: string | null = null;
      let missing =
        node.operation.kind === 'missing' ||
        node.operation.kind === 'optional' ||
        node.operation.kind === 'union';
      if (node.operation.kind === 'leaf') {
        leaf = node.source;
      }
      for (const id of accessorChildren(node.operation)) {
        const child = itemAt(plan.nodes, id);
        if (child.depth + 1 > depth) {
          depth = child.depth + 1;
        }
        missing = missing || child.may_miss;
        if (child.leaf !== null) {
          if (leaf !== null && leaf !== child.leaf) {
            throw new Error('accessor leaf types differ');
          }
          leaf = child.leaf;
        }
      }
      if (
        depth > 128 ||
        node.depth !== depth ||
        node.may_miss !== missing ||
        (leaf === null) !== (node.leaf === null) ||
        (leaf !== null && leaf !== node.leaf)
      ) {
        throw new Error('accessor derived metadata differs');
      }
      marks[item_.id] = 2;
      continue;
    }
    if (marks[item_.id] === 2) {
      continue;
    }
    if (marks[item_.id] === 1) {
      throw new Error('cyclic accessor');
    }
    marks[item_.id] = 1;
    pending.push({ id: item_.id, done: true });
    const children = accessorChildren(node.operation);
    for (let index = children.length - 1; index >= 0; index -= 1) {
      pending.push({ id: itemAt(children, index), done: false });
    }
  }
  for (const mark of marks) {
    if (mark !== 2) {
      throw new Error('unreachable accessor node');
    }
  }
  admitAccessorTypeFacts(root.types);
  observation.assignment();
  typeFactsValidate(
    observation.types,
    itemAt(observation.plan.nodes, observation.plan.start).leaf as string,
  );
  return observation;
}

export function admitAccessorShape(value: Node, depth: number): void {
  if (depth > 128) {
    throw new Error('accessor shape bound');
  }
  if (!isObject(value)) {
    throw new Error('invalid accessor shape');
  }
  let required = 'kind';
  switch (value.kind) {
    case 'primitive':
      required += ' name';
      break;
    case 'optional':
      required += ' of';
      break;
    case 'object':
    case 'sequence':
      break;
    case 'enum':
      required += ' variants';
      break;
    default:
      throw new Error('invalid accessor shape');
  }
  closed(value, required, '');
  if (value.kind === 'optional') {
    admitAccessorShape(value.of, depth + 1);
    return;
  }
  if (value.kind === 'primitive') {
    switch (value.name) {
      case 'string':
      case 'boolean':
      case 'integer':
      case 'decimal':
      case 'timestamp':
      case 'duration':
      case 'uuid':
      case 'bytes':
        break;
      default:
        throw new Error('unsupported accessor primitive shape');
    }
  }
}

export function accessorShapeAdmits(shape: AccessorShape, value: Node): boolean {
  switch (shape.kind) {
    case 'optional':
      return isNil(value) || (shape.of !== undefined && accessorShapeAdmits(shape.of, value));
    case 'object':
      return isObject(value);
    case 'sequence':
      return Array.isArray(value);
    case 'enum':
      return typeof value === 'string' && (shape.variants ?? []).includes(value);
    case 'primitive':
      return primitive(shape.name, value) === '';
    default:
      return false;
  }
}

export function admitAccessorTypeFacts(value: Node): void {
  const root = closed(value, 'nodes', '');
  const nodes = root.nodes;
  if (!isObject(nodes) || Object.keys(nodes).length > 4096) {
    throw new Error('AccessorResource: observation type nodes');
  }
  let edges = 0;
  for (const key of sortStrings(Object.keys(nodes))) {
    name(key, false);
    const body = (nodes as { [label: string]: Node })[key];
    if (!isObject(body)) {
      throw new Error('invalid nominal observation fact');
    }
    let required = 'kind';
    switch (body.kind) {
      case 'enum':
        break;
      case 'newtype':
        required += ' of';
        break;
      case 'struct':
      case 'union':
        required += ' members';
        break;
      default:
        throw new Error('unknown nominal observation fact');
    }
    closed(body, required, '');
    if (body.kind === 'newtype') {
      text(body.of);
      edges += 1;
    }
    if (body.kind === 'struct' || body.kind === 'union') {
      const members = array(body.members);
      edges += members.length;
      if (edges > 16384) {
        throw new Error('AccessorResource: observation type edges');
      }
      for (const member of members) {
        text(member);
      }
    }
  }
}

interface AccessorTypeVisit {
  source: string;
  nested: boolean;
  done: boolean;
}

export function typeFactsChildren(
  facts_: AccessorTypeFacts,
  source: string,
  nested: boolean,
): AccessorTypeVisit[] {
  if (source === 'Binary64') {
    throw new Error('unsupported Binary64 accessor observation');
  }
  if (accessorPrimitive(source)) {
    return [];
  }
  const [innerOptional, isOptional] = accessorOptional(source);
  if (isOptional) {
    if (nested) {
      throw new Error('AmbiguousOptionalObservation');
    }
    return [{ source: innerOptional, nested: true, done: false }];
  }
  const [innerCollection, isCollection] = accessorCollection(source);
  if (isCollection) {
    return [{ source: innerCollection, nested: false, done: false }];
  }
  name(source, false);
  const body = facts_.nodes[source];
  if (body === undefined) {
    throw new Error('missing nominal observation type facts');
  }
  switch (body.kind) {
    case 'enum':
      return [];
    case 'newtype':
      if (accessorOptional(body.of)[1]) {
        throw new Error('AmbiguousOptionalObservation');
      }
      return [{ source: body.of, nested, done: false }];
    case 'struct':
    case 'union': {
      if (body.members.length > 16384) {
        throw new Error('AccessorResource: observation type edges');
      }
      return body.members.map((member) => ({ source: member, nested: false, done: false }));
    }
    default:
      throw new Error('unknown nominal observation kind');
  }
}

export function typeFactsValidate(facts_: AccessorTypeFacts, source: string): void {
  let root = source;
  for (;;) {
    const [inner, ok] = accessorOptional(root);
    if (!ok) {
      break;
    }
    root = inner;
  }
  const states = new Map<string, number>();
  const used = new Set<string>();
  const pending: AccessorTypeVisit[] = [{ source: root, nested: false, done: false }];
  let edges = 0;
  while (pending.length > 0) {
    const item = pending.pop() as AccessorTypeVisit;
    const key = `${item.nested ? '1' : '0'}\u0000${item.source}`;
    if (item.done) {
      const children = typeFactsChildren(facts_, item.source, item.nested);
      let depth = 1;
      for (const child of children) {
        const next = (states.get(`${child.nested ? '1' : '0'}\u0000${child.source}`) ?? 0) + 1;
        if (next > depth) {
          depth = next;
        }
      }
      if (depth > 128) {
        throw new Error('AccessorResource: observation type operations');
      }
      states.set(key, depth);
      continue;
    }
    if (states.has(key)) {
      if (states.get(key) === 0) {
        throw new Error('AmbiguousOptionalObservation: recursive terminal');
      }
      continue;
    }
    if (states.size >= 4096) {
      throw new Error('AccessorResource: observation type nodes');
    }
    states.set(key, 0);
    if (Object.prototype.hasOwnProperty.call(facts_.nodes, item.source)) {
      used.add(item.source);
    }
    const children = typeFactsChildren(facts_, item.source, item.nested);
    edges += children.length;
    if (edges > 16384) {
      throw new Error('AccessorResource: observation type edges');
    }
    pending.push({ source: item.source, nested: item.nested, done: true });
    for (let index = children.length - 1; index >= 0; index -= 1) {
      pending.push(itemAt(children, index));
    }
  }
  if (used.size !== Object.keys(facts_.nodes).length) {
    throw new Error('unreachable nominal observation facts');
  }
}

// ---- the periodic host ----------------------------------------------------------------------------

/** PeriodicField retains the source type. The authority must re-admit named types and invariants. */
export interface PeriodicField {
  name: string;
  type: string;
  wire?: string;
  display?: string;
  summary?: string;
}

/** PeriodicHost names required authenticated input authority; it carries no credentials. */
export interface PeriodicHost {
  owner: string;
  authority: string;
  eligibility: string;
  context_fields: PeriodicField[];
  read_fields: PeriodicField[];
}

/** PeriodicProfile is the one admitted fixed-rate host-lifetime profile. */
export interface PeriodicProfile {
  every: string;
  anchor: string;
  first: string;
  cadence: string;
  overlap: string;
  missed: string;
  lifetime: string;
  cancellation: string;
  host: PeriodicHost;
}

/** PeriodicSource identifies one required host input phase. */
export interface PeriodicSource {
  kind: string;
  field: string;
}

/** PeriodicCheck requests a controlled fixture of the actual declared host authority. */
export interface PeriodicCheck {
  binding: string;
  command: string;
  periodic: PeriodicProfile;
  mapping: { [target: string]: PeriodicSource };
  fixture: string;
}

/** PeriodicScope is an actual causal origin, including its opaque host lifetime. */
export interface PeriodicScope {
  correlation: string;
  binding: string;
  lifetime: string;
}

/** PeriodicOpen binds the typed authority to a previously marked target clock. */
export interface PeriodicOpen {
  check: PeriodicCheck;
  mark: InstantMark;
}

/** PeriodicOpened acknowledges activation and immutable context. */
export interface PeriodicOpened {
  scope: PeriodicScope;
  anchorMillis: number;
  context: { [field: string]: Node };
}

/** PeriodicObserve holds target time and requests complete new causal records. */
export interface PeriodicObserve {
  scope: PeriodicScope;
  elapsed: ElapsedRequest;
  after: number;
}

/** PeriodicFact is an observed fact, never a target verdict. `kind` selects its populated fields. */
export interface PeriodicFact {
  kind: string;
  ordinal?: number;
  dueMillis?: number;
  atMillis?: number;
  eligible?: boolean;
  invocation?: string;
  command?: string;
  read?: { [field: string]: Node };
  input?: { [field: string]: Node };
  first?: number;
  last?: number;
}

/** PeriodicRecord retains the actual origin even when it differs from the requested scope. */
export interface PeriodicRecord {
  scope: PeriodicScope;
  fact: PeriodicFact;
}

/** PeriodicObservation combines elapsed time with complete append-only causal capture. */
export interface PeriodicObservation {
  elapsedMillis?: number;
  completeThroughMillis?: number;
  cursor?: number;
  records?: PeriodicRecord[];
}

/** PeriodicClosed acknowledges actual quiescence, including in-flight read/apply work. */
export interface PeriodicClosed {
  scope: PeriodicScope;
  atMillis: number;
}

/**
 * PeriodicTarget opens the actual host, re-admitting the typed authority against its model.
 *
 * Named representations, nested values and invariants require host validation before effects.
 * Unsupported authority or controlled observation throws ErrUnsupported, never a passing trace.
 */
export interface PeriodicTarget {
  openPeriodic(open: PeriodicOpen): Answer<PeriodicOpened>;
  observePeriodic(observe: PeriodicObserve): Answer<PeriodicObservation>;
  closePeriodic(scope: PeriodicScope): Answer<PeriodicClosed>;
}

export function periodicSeconds(value: string): number {
  if (!value.startsWith('PT') || !value.endsWith('S')) {
    throw new Error('PeriodicContract: expected PT<seconds>S');
  }
  const digits = value.slice(2, value.length - 1);
  if (digits === '' || (digits.length > 1 && digits[0] === '0')) {
    throw new Error('PeriodicContract: empty period');
  }
  for (const character of digits) {
    if (character < '0' || character > '9') {
      throw new Error('PeriodicContract: noninteger period');
    }
  }
  const parsed = Number(digits);
  if (!Number.isInteger(parsed) || parsed === 0 || parsed > 4294967295 / 5) {
    throw new Error('PeriodicResource: positive five-period witness must fit elapsed');
  }
  return parsed;
}

export function periodicFieldName(value: string): boolean {
  return qualifiedName.test(value) && !value.includes('.') && !value.includes('-');
}

const PERIODIC_PROFILE: { [key: string]: string } = {
  anchor: 'host_activation',
  first: 'after_period',
  cadence: 'fixed_rate',
  overlap: 'serial_per_instance',
  missed: 'one_pending_drop_excess',
  lifetime: 'host_instance',
  cancellation: 'stop_acknowledged',
};

export function admitPeriodic(value: Node): void {
  const root = closed(value, 'binding command periodic mapping fixture', '');
  name(root.binding, true);
  name(root.command, false);
  switch (root.fixture) {
    case 'ready':
    case 'initially_inactive':
    case 'first_read_fails':
    case 'slow_first_read':
      break;
    default:
      throw new Error('PeriodicContract: unknown fixture');
  }
  const profile = closed(
    root.periodic,
    'every anchor first cadence overlap missed lifetime cancellation host',
    '',
  );
  periodicSeconds(text(profile.every));
  for (const key of Object.keys(PERIODIC_PROFILE)) {
    if (profile[key] !== PERIODIC_PROFILE[key]) {
      throw new Error(`PeriodicContract: unsupported ${key}`);
    }
  }
  const host = closed(profile.host, 'owner authority eligibility context_fields read_fields', '');
  name(host.owner, true);
  name(host.authority, true);
  if (host.eligibility !== 'host_boolean') {
    throw new Error('PeriodicContract: eligibility authority');
  }
  const tables: { [phase: string]: Set<string> } = {};
  for (const phase of ['context', 'read']) {
    const fields = host[`${phase}_fields`];
    if (!Array.isArray(fields) || fields.length > 64) {
      throw new Error('PeriodicResource: host fields bound');
    }
    const seen = new Set<string>();
    for (const raw of fields as Node[]) {
      const field = closed(raw, 'name type', 'wire display summary');
      const label = attempt(() => text(field.name));
      if (label === undefined || !periodicFieldName(label) || seen.has(label)) {
        throw new Error('PeriodicContract: duplicate or malformed field');
      }
      seen.add(label);
      accessorType(text(field.type), 0);
      for (const key of ['wire', 'display', 'summary']) {
        if (Object.prototype.hasOwnProperty.call(field, key)) {
          text(field[key]);
        }
      }
    }
    tables[phase] = seen;
  }
  const mapping = root.mapping;
  if (!isObject(mapping) || Object.keys(mapping).length === 0 || Object.keys(mapping).length > 64) {
    throw new Error('PeriodicResource: mapping bound');
  }
  for (const target of Object.keys(mapping)) {
    if (!periodicFieldName(target)) {
      throw new Error('PeriodicContract: input name');
    }
    const source = closed((mapping as { [key: string]: Node })[target], 'kind field', '');
    const kind = typeof source.kind === 'string' ? source.kind : '';
    const field = typeof source.field === 'string' ? source.field : '';
    if (tables[kind] === undefined || !tables[kind].has(field)) {
      throw new Error('PeriodicContract: undeclared host source');
    }
  }
}

export function validatePeriodic(check: PeriodicCheck): void {
  admitPeriodic(strictJSON(goMarshal(check)));
}

export function periodicFields(fields: PeriodicField[], values: { [field: string]: Node }): void {
  if (fields.length !== Object.keys(values).length) {
    throw new Error('PeriodicHost: exact fields required');
  }
  const accepts = (declared: string, value: Node, depth: number): boolean => {
    if (depth > 32) {
      return false;
    }
    const held = declared.trim();
    if (held.startsWith('Optional<')) {
      return (
        isNil(value) || accepts(held.slice('Optional<'.length, held.length - 1), value, depth + 1)
      );
    }
    if (held.startsWith('List<')) {
      return Array.isArray(value);
    }
    if (held.startsWith('Map<')) {
      return isObject(value);
    }
    if (accessorPrimitive(held)) {
      return primitive(held.toLowerCase(), value) === '';
    }
    return true;
  };
  for (const field of fields) {
    if (
      !Object.prototype.hasOwnProperty.call(values, field.name) ||
      !accepts(field.type, values[field.name], 0)
    ) {
      throw new Error(`PeriodicHost: representation of ${field.name}`);
    }
  }
}

interface PeriodicOperation {
  eligible: boolean;
  received: number;
  invoked: boolean;
  failed: boolean;
  completed: boolean;
}

const UINT64_CEILING = 18446744073709551615;

class PeriodicLedger {
  readonly check: PeriodicCheck;
  readonly opened: PeriodicOpened;
  readonly period: number;
  readonly operations = new Map<number, PeriodicOperation>();
  readonly invocations = new Set<string>();
  readonly dropped = new Set<number>();
  cursor = 0;
  through: number;
  lastAt: number;

  constructor(check: PeriodicCheck, opened: PeriodicOpened, period: number) {
    this.check = check;
    this.opened = opened;
    this.period = period;
    this.through = opened.anchorMillis;
    this.lastAt = opened.anchorMillis;
  }

  deadline(ordinal: number): [number, boolean] {
    if (ordinal === 0 || ordinal > (UINT64_CEILING - this.opened.anchorMillis) / this.period) {
      return [0, false];
    }
    return [this.opened.anchorMillis + ordinal * this.period, true];
  }

  observe(observation: PeriodicObservation, hold: number, closedAt: number | null): void {
    const records = observation.records ?? [];
    const cursor = observation.cursor ?? 0;
    const elapsedMillis = observation.elapsedMillis ?? 0;
    const completeThroughMillis = observation.completeThroughMillis ?? 0;
    if (records.length > 4096 || cursor > 4096 || cursor !== this.cursor + records.length) {
      throw new Error('PeriodicResource: capture cursor');
    }
    if (
      elapsedMillis < hold ||
      completeThroughMillis < hold ||
      completeThroughMillis > elapsedMillis ||
      completeThroughMillis < this.through
    ) {
      throw new Error('PeriodicObservation: incomplete held window');
    }
    for (const record of records) {
      if (
        record.scope.correlation !== this.opened.scope.correlation ||
        record.scope.binding !== this.opened.scope.binding ||
        record.scope.lifetime !== this.opened.scope.lifetime
      ) {
        throw new Error('PeriodicOrigin: wrong binding, scenario or lifetime');
      }
      const fact = record.fact;
      const atMillis = fact.atMillis ?? 0;
      if (atMillis < this.lastAt || atMillis <= this.through || atMillis > completeThroughMillis) {
        throw new Error('PeriodicObservation: invalid fact time/order');
      }
      if (closedAt !== null && atMillis >= closedAt && fact.kind !== 'independent') {
        throw new Error('PeriodicLifetime: occurrence after stop');
      }
      this.lastAt = atMillis;
      let busy = false;
      for (const operation of this.operations.values()) {
        if (!operation.completed) {
          busy = true;
        }
      }
      const ordinal = fact.ordinal ?? 0;
      switch (fact.kind) {
        case 'received': {
          const [due, ok] = this.deadline(ordinal);
          if (
            !ok ||
            due !== (fact.dueMillis ?? 0) ||
            atMillis < due ||
            this.operations.has(ordinal) ||
            this.dropped.has(ordinal)
          ) {
            throw new Error('PeriodicOccurrence: early, duplicate or incorrect tick');
          }
          if (busy) {
            throw new Error('PeriodicOverlap: concurrent poll');
          }
          const eligible = !(this.check.fixture === 'initially_inactive' && ordinal === 1);
          if ((fact.eligible ?? false) !== eligible) {
            throw new Error('PeriodicHost: eligibility fixture');
          }
          this.operations.set(ordinal, {
            eligible,
            received: atMillis,
            invoked: false,
            failed: false,
            completed: false,
          });
          break;
        }
        case 'read_failed': {
          const operation = this.operations.get(ordinal);
          if (
            operation === undefined ||
            !operation.eligible ||
            operation.invoked ||
            operation.failed ||
            operation.completed ||
            this.check.fixture !== 'first_read_fails' ||
            ordinal !== 1
          ) {
            throw new Error('PeriodicHost: unexpected read failure');
          }
          operation.failed = true;
          break;
        }
        case 'invoked': {
          const operation = this.operations.get(ordinal);
          const invocation = fact.invocation ?? '';
          if (
            operation === undefined ||
            !operation.eligible ||
            operation.failed ||
            operation.invoked ||
            operation.completed ||
            (fact.command ?? '') !== this.check.command ||
            invocation === '' ||
            this.invocations.has(invocation) ||
            atMillis < operation.received
          ) {
            throw new Error(
              'PeriodicInvocation: duplicated, misattributed or forbidden invocation',
            );
          }
          periodicFields(this.check.periodic.host.read_fields, fact.read ?? {});
          const expected: { [field: string]: Node } = {};
          for (const [target, source] of Object.entries(this.check.mapping)) {
            const table = source.kind === 'context' ? this.opened.context : (fact.read ?? {});
            if (!Object.prototype.hasOwnProperty.call(table, source.field)) {
              throw new Error('PeriodicHost: missing value');
            }
            expected[target] = table[source.field];
          }
          if (!equal(fact.input ?? {}, expected)) {
            throw new Error('PeriodicMapping: invocation differs from current host inputs');
          }
          operation.invoked = true;
          this.invocations.add(invocation);
          break;
        }
        case 'completed': {
          const [third, valid] = this.deadline(3);
          if (
            this.check.fixture === 'slow_first_read' &&
            ordinal === 1 &&
            (!valid || atMillis <= third)
          ) {
            throw new Error(
              'PeriodicHost: first read did not remain busy through both missed deadlines',
            );
          }
          const operation = this.operations.get(ordinal);
          if (
            operation === undefined ||
            operation.completed ||
            (operation.eligible && !operation.invoked && !operation.failed) ||
            (this.check.fixture === 'first_read_fails' && ordinal === 1 && !operation.failed)
          ) {
            throw new Error('PeriodicOccurrence: missing attempt');
          }
          operation.completed = true;
          break;
        }
        case 'dropped': {
          const first = fact.first ?? 0;
          const last = fact.last ?? 0;
          if (
            first === 0 ||
            first > last ||
            last > 5 ||
            this.check.fixture !== 'slow_first_read' ||
            !busy
          ) {
            throw new Error('PeriodicMissed: loss outside busy window');
          }
          for (let n = first; n <= last; n += 1) {
            const [due, ok] = this.deadline(n);
            if (!ok || due > atMillis || this.operations.has(n) || this.dropped.has(n)) {
              throw new Error('PeriodicMissed: invalid dropped ordinal');
            }
            this.dropped.add(n);
          }
          break;
        }
        case 'independent': {
          const invocation = fact.invocation ?? '';
          if (
            invocation === '' ||
            (fact.command ?? '') !== this.check.command ||
            this.invocations.has(invocation)
          ) {
            throw new Error('PeriodicOrigin: invalid independent invocation');
          }
          this.invocations.add(invocation);
          break;
        }
        default:
          throw new Error('PeriodicObservation: unknown fact');
      }
    }
    this.cursor = cursor;
    this.through = completeThroughMillis;

    let liveThrough = this.through;
    if (closedAt !== null) {
      liveThrough = closedAt;
      if (liveThrough > 0) {
        liveThrough -= 1;
      }
    }
    let due = 0;
    if (liveThrough > this.opened.anchorMillis) {
      due = Math.floor((liveThrough - this.opened.anchorMillis) / this.period);
    }
    if (due > 5) {
      throw new Error('PeriodicResource: live observation exceeds five-period witness');
    }
    if (this.check.fixture === 'slow_first_read' && due >= 4) {
      let pending = 0;
      let dropped = 0;
      for (const n of [2, 3]) {
        const operation = this.operations.get(n);
        if (operation !== undefined && operation.completed) {
          pending += 1;
        }
        if (this.dropped.has(n)) {
          dropped += 1;
        }
      }
      if (pending !== 1 || dropped !== 1) {
        throw new Error('PeriodicMissed: exactly one pending and one discarded tick required');
      }
    }
    for (let n = 1; n <= due; n += 1) {
      if (this.check.fixture === 'slow_first_read' && (n === 2 || n === 3)) {
        continue;
      }
      const operation = this.operations.get(n);
      if (operation === undefined) {
        throw new Error('PeriodicLiveness: missing idle occurrence');
      }
      const [deadline] = this.deadline(n);
      if (operation.received !== deadline) {
        throw new Error('PeriodicLateness: idle receipt delayed');
      }
      if (
        !(this.check.fixture === 'slow_first_read' && n === 1 && due < 4) &&
        !operation.completed
      ) {
        throw new Error('PeriodicLiveness: missing completion');
      }
    }
  }
}

function periodicSnapshotTyped<T>(value: T): T {
  return plainNumbers(strictJSON(goMarshal(value))) as T;
}

function periodicSnapshotNode(value: { [field: string]: Node }): { [field: string]: Node } {
  return strictJSON(goMarshal(value)) as { [field: string]: Node };
}

/** checkPeriodic exercises real authority and a controlled target clock without wall sleeps. */
export async function checkPeriodic(
  check: PeriodicCheck,
  correlation: string,
  target: PeriodicTarget,
  clock: Clock,
): Promise<void> {
  validatePeriodic(check);
  const mark: InstantMark = { instant: 'periodic-anchor', correlation };
  await clock.markInstant(mark);
  const requestCheck = periodicSnapshotTyped(check);
  const opened = await target.openPeriodic({ check: requestCheck, mark });
  let stopped = false;
  let outcome: unknown;
  try {
    if (
      opened.scope.correlation !== correlation ||
      opened.scope.binding !== check.binding ||
      opened.scope.lifetime === '' ||
      opened.scope.lifetime.length > 128
    ) {
      throw new Error('PeriodicOrigin: invalid opened scope');
    }
    periodicFields(check.periodic.host.context_fields, opened.context);
    opened.context = periodicSnapshotNode(opened.context);
    if (opened.anchorMillis % 1000 !== 0) {
      throw new Error('whole-second controlled anchor required', { cause: ErrUnsupported });
    }
    const period = periodicSeconds(check.periodic.every);
    const anchor = opened.anchorMillis / 1000;
    if (anchor > 4294967295 - 4 * period) {
      throw new Error('PeriodicResource: anchor overflow');
    }
    const ledger = new PeriodicLedger(check, opened, period * 1000);
    for (const offset of [period - 1, period, 2 * period, 4 * period]) {
      const seconds = anchor + offset;
      const observation = await target.observePeriodic({
        scope: opened.scope,
        elapsed: { instant: mark.instant, hold: seconds, correlation },
        after: ledger.cursor,
      });
      ledger.observe(observation, seconds * 1000, null);
    }
    const closed_ = await target.closePeriodic(opened.scope);
    stopped = true;
    if (
      closed_.scope.correlation !== opened.scope.correlation ||
      closed_.scope.binding !== opened.scope.binding ||
      closed_.scope.lifetime !== opened.scope.lifetime ||
      closed_.atMillis < ledger.through
    ) {
      throw new Error('PeriodicLifetime: invalid stop acknowledgement');
    }
    if (closed_.atMillis > 4294967295 * 1000 - period * 1000) {
      throw new Error('PeriodicResource: closure overflow');
    }
    const hold = Math.floor((closed_.atMillis + period * 1000 + 999) / 1000);
    const observation = await target.observePeriodic({
      scope: opened.scope,
      elapsed: { instant: mark.instant, hold, correlation },
      after: ledger.cursor,
    });
    ledger.observe(observation, hold * 1000, closed_.atMillis);
  } catch (error) {
    outcome = error;
  }
  if (!stopped) {
    try {
      await target.closePeriodic(opened.scope);
    } catch (error) {
      if (outcome === undefined) {
        outcome = error;
      }
    }
  }
  if (outcome !== undefined) {
    throw outcome;
  }
}

// ---- selection: actual declaration facts and original list indices ------------------------------

export interface SelectionDeclaration {
  kind: string;
  of: string;
  fields: AccessorField[];
  /** Absent where the declaration is not an enum or a union, which is the nil raw message. */
  variants?: Node;
  tag: string;
}

export interface SelectionInputSource {
  kind: string;
  field: AccessorField;
  plan: AccessorPlan;
}

export interface SelectionInput {
  name: string;
  source: SelectionInputSource;
  list_type: string;
  item_type: string;
  optional_items: boolean;
  conversion: string | null;
}

export interface SelectionSelectorOperation {
  kind: string;
  excluding: number[];
  predicate: Node;
  reads: { [path: string]: AccessorPlan };
  selections: number[];
}

export interface SelectionSelector {
  name: string;
  input: number;
  operation: SelectionSelectorOperation;
}

/** ByteCounter is the `*int` a nested validation spends against the shared byte limit. */
export interface ByteCounter {
  bytes: number;
}

function makeShape(
  kind: string,
  label = '',
  extra: { variants?: string[]; of?: AccessorShape } = {},
): AccessorShape {
  const shape: AccessorShape = { kind, name: label };
  if (extra.variants !== undefined) {
    shape.variants = extra.variants;
  }
  if (extra.of !== undefined) {
    shape.of = extra.of;
  }
  return shape;
}

function variantList(value: Node): string[] {
  if (!Array.isArray(value)) {
    throw new Error('selection enum variants must be a list');
  }
  return value.map((item: Node) => {
    if (typeof item !== 'string') {
      throw new Error('selection enum variant must be text');
    }
    return item;
  });
}

function variantMap(value: Node): { [label: string]: string } {
  if (!isObject(value)) {
    throw new Error('selection union variants must be an object');
  }
  const result: { [label: string]: string } = {};
  for (const label of Object.keys(value)) {
    const target = value[label];
    if (typeof target !== 'string') {
      throw new Error('selection union variant must be text');
    }
    result[label] = target;
  }
  return result;
}

function decodeSelectionDeclaration(value: Node): SelectionDeclaration {
  const held = isObject(value) ? value : {};
  return {
    kind: typeof held.kind === 'string' ? held.kind : '',
    of: typeof held.of === 'string' ? held.of : '',
    fields: Array.isArray(held.fields) ? held.fields.map(decodeAccessorField) : [],
    variants: held.variants,
    tag: typeof held.tag === 'string' ? held.tag : '',
  };
}

/** selectionJSON is a value put back through the wire, which is where a number loses nothing. */
export function selectionJSON(value: Node): Node {
  return strictJSON(goMarshal(value));
}

export function selectionShapeJSON(shape: AccessorShape): Node {
  const value: { [key: string]: Node } = { kind: shape.kind };
  switch (shape.kind) {
    case 'primitive':
      value.name = shape.name;
      break;
    case 'enum':
      value.variants = shape.variants ?? null;
      break;
    case 'optional':
      if (shape.of !== undefined) {
        value.of = selectionShapeJSON(shape.of);
      }
      break;
    default:
      break;
  }
  return value;
}

export function selectionPlanJSON(plan: AccessorPlan): Node {
  const field = (value: AccessorField): Node => ({ name: value.name, type: value.type });
  const nodes = plan.nodes.map((node) => {
    const operation: { [key: string]: Node } = { kind: node.operation.kind };
    switch (node.operation.kind) {
      case 'field':
        operation.field = field(node.operation.field);
        operation.next = node.operation.next;
        break;
      case 'optional':
      case 'newtype':
        operation.next = node.operation.next;
        break;
      case 'union':
        operation.tag = node.operation.tag;
        operation.variants = node.operation.variants;
        break;
      default:
        break;
    }
    return {
      source: node.source,
      shape: selectionShapeJSON(node.shape),
      position: node.position,
      operation,
      leaf: node.leaf,
      may_miss: node.may_miss,
      depth: node.depth,
    };
  });
  return { segments: plan.segments, root: field(plan.root), start: plan.start, nodes };
}

export function selectionFactsJSON(facts_: AccessorTypeFacts): Node {
  const nodes: { [label: string]: Node } = {};
  for (const [label, body] of Object.entries(facts_.nodes)) {
    const value: { [key: string]: Node } = { kind: body.kind };
    switch (body.kind) {
      case 'newtype':
        value.of = body.of;
        break;
      case 'struct':
      case 'union':
        value.members = body.members;
        break;
      default:
        break;
    }
    nodes[label] = value;
  }
  return { nodes };
}

export function selectionFailure(
  cause: string,
  input: number,
  index: number,
  selector: number,
): Error {
  return new Error(`SelectionFailure:${cause}:input=${input}:index=${index}:selector=${selector}`);
}

/** SelectionObservation is a declared selection over an observed list, and its projection. */
export class SelectionObservation {
  responseMode = false;
  rawNode: Node = null;
  event_type = '';
  plan: { inputs: SelectionInput[]; selectors: SelectionSelector[] } = {
    inputs: [],
    selectors: [],
  };
  declarations: { [name: string]: SelectionDeclaration } = {};
  selector = 0;
  projection: { projection: AccessorPlan; target: string; types: AccessorTypeFacts } = {
    projection: decodeAccessorPlan(undefined),
    target: '',
    types: { nodes: {} },
  };

  constructor(value?: Node) {
    if (value === undefined) {
      return;
    }
    this.rawNode = value;
    const held = plainNumbers(value) as { [key: string]: Node };
    if (!isObject(held)) {
      return;
    }
    this.event_type = typeof held.event_type === 'string' ? held.event_type : '';
    this.selector = decodeNumber(held.selector);
    const plan = isObject(held.plan) ? (held.plan as { [key: string]: Node }) : {};
    this.plan = {
      inputs: (Array.isArray(plan.inputs) ? (plan.inputs as Node[]) : []).map((raw) => {
        const input = isObject(raw) ? raw : {};
        const source = isObject(input.source) ? (input.source as { [key: string]: Node }) : {};
        return {
          name: typeof input.name === 'string' ? input.name : '',
          source: {
            kind: typeof source.kind === 'string' ? source.kind : '',
            field: decodeAccessorField(source.field),
            plan: decodeAccessorPlan(source.plan),
          },
          list_type: typeof input.list_type === 'string' ? input.list_type : '',
          item_type: typeof input.item_type === 'string' ? input.item_type : '',
          optional_items: input.optional_items === true,
          conversion: typeof input.conversion === 'string' ? input.conversion : null,
        };
      }),
      selectors: (Array.isArray(plan.selectors) ? (plan.selectors as Node[]) : []).map((raw) => {
        const selector = isObject(raw) ? raw : {};
        const operation = isObject(selector.operation)
          ? (selector.operation as { [key: string]: Node })
          : {};
        const reads: { [path: string]: AccessorPlan } = {};
        if (isObject(operation.reads)) {
          for (const path of Object.keys(operation.reads as { [key: string]: Node })) {
            reads[path] = decodeAccessorPlan((operation.reads as { [key: string]: Node })[path]);
          }
        }
        return {
          name: typeof selector.name === 'string' ? selector.name : '',
          input: decodeNumber(selector.input),
          operation: {
            kind: typeof operation.kind === 'string' ? operation.kind : '',
            excluding: Array.isArray(operation.excluding)
              ? (operation.excluding as Node[]).map(decodeNumber)
              : [],
            predicate: operation.predicate,
            reads,
            selections: Array.isArray(operation.selections)
              ? (operation.selections as Node[]).map(decodeNumber)
              : [],
          },
        };
      }),
    };
    this.declarations = {};
    if (isObject(held.declarations)) {
      for (const label of Object.keys(held.declarations as { [key: string]: Node })) {
        this.declarations[label] = decodeSelectionDeclaration(
          (held.declarations as { [key: string]: Node })[label],
        );
      }
    }
    const projection = isObject(held.projection)
      ? (held.projection as { [key: string]: Node })
      : {};
    this.projection = {
      projection: decodeAccessorPlan(projection.projection),
      target: typeof projection.target === 'string' ? projection.target : '',
      types: decodeAccessorTypeFacts(projection.types),
    };
  }

  /** forResponse is the observer a response contract validates its declared fields against. */
  static forResponse(declarations: { [name: string]: SelectionDeclaration }): SelectionObservation {
    const observer = new SelectionObservation();
    observer.declarations = declarations;
    observer.responseMode = true;
    return observer;
  }

  transparent(source: string): string {
    const seen = new Set<string>();
    let held = source;
    for (let depth = 0; depth < 128; depth += 1) {
      const body = this.declarations[held];
      if (body === undefined || body.kind !== 'newtype') {
        return held;
      }
      if (seen.has(held)) {
        throw new Error('recursive selection alias');
      }
      seen.add(held);
      held = body.of;
    }
    throw new Error('selection alias bound');
  }

  shape(source: string, depth: number): AccessorShape {
    if (depth > 128) {
      throw new Error('selection shape bound');
    }
    const held = this.transparent(source);
    const [inner, optional] = accessorOptional(held);
    if (optional) {
      const shape = this.shape(inner, depth + 1);
      if (shape.kind === 'optional') {
        return shape;
      }
      return makeShape('optional', '', { of: shape });
    }
    if (accessorPrimitive(held)) {
      return makeShape('primitive', held.toLowerCase());
    }
    if (held.startsWith('List<')) {
      return makeShape('sequence');
    }
    if (held.startsWith('Map<')) {
      return makeShape('object');
    }
    const body = this.declarations[held];
    if (body === undefined) {
      throw new Error('missing selection shape');
    }
    if (body.kind === 'enum') {
      return makeShape('enum', '', { variants: variantList(body.variants) });
    }
    return makeShape('object');
  }

  typeFacts(source: string): AccessorTypeFacts {
    const facts_: AccessorTypeFacts = { nodes: {} };
    const pending: string[] = [source];
    while (pending.length > 0) {
      const held = pending.pop() as string;
      const [innerOptional, optional] = accessorOptional(held);
      if (optional) {
        pending.push(innerOptional);
        continue;
      }
      const [innerCollection, collection] = accessorCollection(held);
      if (collection) {
        pending.push(innerCollection);
        continue;
      }
      if (accessorPrimitive(held)) {
        continue;
      }
      if (Object.prototype.hasOwnProperty.call(facts_.nodes, held)) {
        continue;
      }
      const body = this.declarations[held];
      if (body === undefined) {
        throw new Error('missing selection type fact');
      }
      const node: AccessorTypeBody = { kind: body.kind, of: body.of, members: [] };
      switch (body.kind) {
        case 'newtype':
          pending.push(body.of);
          break;
        case 'struct':
          for (const field of body.fields) {
            node.members.push(field.type);
            pending.push(field.type);
          }
          break;
        case 'union': {
          const variants = variantMap(body.variants);
          for (const label of meaningKeys(variants)) {
            const member = variants[label] as string;
            node.members.push(member);
            pending.push(member);
          }
          break;
        }
        case 'enum':
          break;
        default:
          throw new Error('invalid selection declaration');
      }
      facts_.nodes[held] = node;
      if (Object.keys(facts_.nodes).length > 4096) {
        throw new Error('selection fact bound');
      }
    }
    return facts_;
  }

  checkPlan(plan: AccessorPlan, item: boolean): void {
    if (
      plan.start < 0 ||
      plan.start >= plan.nodes.length ||
      itemAt(plan.nodes, plan.start).leaf === null
    ) {
      throw new Error('selection invalid plan root');
    }
    let target = itemAt(plan.nodes, plan.start).leaf as string;
    if (itemAt(plan.nodes, plan.start).may_miss && !accessorOptional(target)[1]) {
      target = `Optional<${target}>`;
    }
    const facts_ = this.typeFacts(target);
    admitAccessorMode(
      selectionJSON({ plan: selectionPlanJSON(plan), target, types: selectionFactsJSON(facts_) }),
      item,
    );
    for (const node of plan.nodes) {
      const shape = this.shape(node.source, 0);
      if (!deepEqual(shape, node.shape)) {
        throw new Error('selection declared shape disagrees');
      }
      const body = this.declarations[node.source] ?? decodeSelectionDeclaration(undefined);
      const operation = node.operation;
      switch (operation.kind) {
        case 'field': {
          if (body.kind !== 'struct') {
            throw new Error('selection field owner differs');
          }
          let found = false;
          for (const field of body.fields) {
            if (field.name === operation.field.name && field.type === operation.field.type) {
              found = true;
            }
          }
          if (!found) {
            throw new Error('selection undeclared field');
          }
          break;
        }
        case 'newtype':
          if (body.kind !== 'newtype' || body.of !== itemAt(plan.nodes, operation.next).source) {
            throw new Error('selection alias differs');
          }
          break;
        case 'union': {
          const variants =
            body.kind === 'union' ? attempt(() => variantMap(body.variants)) : undefined;
          if (
            body.kind !== 'union' ||
            body.tag !== operation.tag ||
            variants === undefined ||
            Object.keys(variants).length !== Object.keys(operation.variants).length
          ) {
            throw new Error('selection union differs');
          }
          for (const label of Object.keys(operation.variants)) {
            if (
              variants[label] !== itemAt(plan.nodes, operation.variants[label] as number).source
            ) {
              throw new Error('selection variant differs');
            }
          }
          break;
        }
        case 'missing': {
          if (body.kind !== 'struct') {
            throw new Error('selection missing member owner differs');
          }
          for (const field of body.fields) {
            if (field.name === plan.segments[node.position]) {
              throw new Error('selection omitted an existing field');
            }
          }
          break;
        }
        default:
          break;
      }
    }
  }

  checkPredicate(
    condition: Predicate,
    reads: { [path: string]: AccessorPlan },
    count: { n: number },
    used: Set<string>,
  ): void {
    count.n += 1;
    if (count.n > 64) {
      throw new Error('selection predicate bound');
    }
    switch (condition.kind) {
      case 'always':
      case 'never':
        return;
      case 'all':
      case 'any':
        for (const child of condition.children) {
          this.checkPredicate(child, reads, count, used);
        }
        return;
      case 'not':
        if (condition.body === null || condition.body === undefined) {
          throw new Error('selection predicate child missing');
        }
        this.checkPredicate(condition.body, reads, count, used);
        return;
      case 'defined':
      case 'compare': {
        let path = condition.path;
        if (condition.kind === 'compare') {
          if (
            !condition.left.isFact ||
            condition.right.isFact ||
            (condition.op !== '==' && condition.op !== '!=')
          ) {
            throw new Error('selection requires fact/literal Eq/Ne');
          }
          path = condition.left.path;
          const literal = condition.right.literal;
          if (typeof literal !== 'string') {
            throw new Error('selection literal must be text');
          }
          const plan = reads[path];
          if (
            plan === undefined ||
            plan.start < 0 ||
            plan.start >= plan.nodes.length ||
            itemAt(plan.nodes, plan.start).leaf === null
          ) {
            throw new Error('selection read is undeclared');
          }
          let held = itemAt(plan.nodes, plan.start).leaf as string;
          for (let depth = 0; depth < 128; depth += 1) {
            held = this.transparent(held);
            const [inner, optional] = accessorOptional(held);
            if (optional) {
              held = inner;
              continue;
            }
            break;
          }
          const body = this.declarations[held];
          if (body !== undefined && body.kind === 'enum') {
            const variants = variantList(body.variants);
            if (!variants.includes(literal)) {
              throw new Error('selection enum literal is undeclared');
            }
          }
        }
        if (!Object.prototype.hasOwnProperty.call(reads, path) || !path.startsWith('item.')) {
          throw new Error('selection predicate read undeclared');
        }
        used.add(path);
        return;
      }
      default:
        break;
    }
    throw new Error('unsupported selection predicate');
  }

  validateValue(
    source: string,
    value: Node,
    present: boolean,
    counter: ByteCounter,
    depth: number,
  ): void {
    if (depth > 128 || counter.bytes > 1048576) {
      throw new Error('resource');
    }
    const [innerOptional, optional] = accessorOptional(source);
    if (optional) {
      if (!present || isNil(value)) {
        return;
      }
      this.validateValue(innerOptional, value, true, counter, depth + 1);
      return;
    }
    if (!present || isNil(value)) {
      throw new Error('invalid_input');
    }
    const body = this.declarations[source];
    if (body !== undefined) {
      switch (body.kind) {
        case 'newtype':
          this.validateValue(body.of, value, true, counter, depth + 1);
          return;
        case 'enum': {
          const variants = attempt(() => variantList(body.variants));
          if (variants === undefined || typeof value !== 'string') {
            throw new Error('invalid_input');
          }
          if (!variants.includes(value)) {
            throw new Error('invalid_input');
          }
          counter.bytes += value.length;
          return;
        }
        case 'struct': {
          if (!isObject(value)) {
            throw new Error('invalid_input');
          }
          const fields = value as { [key: string]: Node };
          if (this.responseMode) {
            const names = new Set(body.fields.map((field) => field.name));
            for (const key of Object.keys(fields)) {
              if (!names.has(key)) {
                throw new Error('invalid_input');
              }
            }
          }
          for (const field of body.fields) {
            counter.bytes += field.name.length;
            const item = fields[field.name];
            const held = Object.prototype.hasOwnProperty.call(fields, field.name);
            this.validateValue(field.type, item, held, counter, depth + 1);
          }
          return;
        }
        case 'union': {
          if (!isObject(value)) {
            throw new Error('invalid_input');
          }
          const fields = value as { [key: string]: Node };
          const label = fields[body.tag];
          if (typeof label !== 'string') {
            throw new Error('invalid_input');
          }
          const variants = attempt(() => variantMap(body.variants));
          if (variants === undefined) {
            throw new Error('invalid_input');
          }
          if (!Object.prototype.hasOwnProperty.call(variants, label)) {
            throw new Error('invalid_input');
          }
          const key = body.tag === 'value' ? 'content' : 'value';
          if (this.responseMode) {
            for (const member of Object.keys(fields)) {
              if (member !== body.tag && member !== key) {
                throw new Error('invalid_input');
              }
            }
          }
          const item = fields[key];
          this.validateValue(
            variants[label] as string,
            item,
            Object.prototype.hasOwnProperty.call(fields, key),
            counter,
            depth + 1,
          );
          return;
        }
        default:
          break;
      }
    }
    if (source.startsWith('List<') && source.endsWith('>')) {
      if (!Array.isArray(value)) {
        throw new Error('invalid_input');
      }
      if (value.length > 64) {
        throw new Error('resource');
      }
      for (const item of value) {
        this.validateValue(
          source.slice('List<'.length, source.length - 1),
          item,
          true,
          counter,
          depth + 1,
        );
      }
      return;
    }
    if (this.responseMode && source.startsWith('Map<String, ') && source.endsWith('>')) {
      if (!isObject(value)) {
        throw new Error('invalid_input');
      }
      const values = value as { [key: string]: Node };
      if (Object.keys(values).length > 64) {
        throw new Error('resource');
      }
      for (const key of Object.keys(values)) {
        counter.bytes += key.length;
        this.validateValue(
          source.slice('Map<String, '.length, source.length - 1),
          values[key],
          true,
          counter,
          depth + 1,
        );
      }
      return;
    }
    if (accessorPrimitive(source)) {
      if (this.responseMode) {
        if (!responsePrimitiveAdmits(source, value)) {
          throw new Error('invalid_input');
        }
      } else if (source === 'Binary64' || source === 'Decimal') {
        const [number, ok] = asNumber(value);
        if (!ok || Number.isNaN(number) || !Number.isFinite(number)) {
          throw new Error('invalid_input');
        }
      } else if (!accessorShapeAdmits(makeShape('primitive', source.toLowerCase()), value)) {
        throw new Error('invalid_input');
      }
      if (typeof value === 'string') {
        counter.bytes += value.length;
        if (value.length > 4096) {
          throw new Error('resource');
        }
      }
      return;
    }
    throw new Error('unsupported');
  }

  evaluate(payload: { [field: string]: Node }): [Node, boolean] {
    // Admission precedes target execution; direct constructions are checked again here.
    const admitted = admitSelection(this.rawNode);
    // Re-admission preserves admitted meaning without silently repairing a mutated contract.
    const retained = Object.assign(
      Object.create(SelectionObservation.prototype) as SelectionObservation,
      admitted,
    );
    retained.rawNode = this.rawNode;
    if (!deepEqual(this, retained)) {
      throw new Error('selection typed contract differs from original');
    }
    const selection = admitted;
    const inputs: Node[][] = new Array(selection.plan.inputs.length).fill(null) as Node[][];
    const counter: ByteCounter = { bytes: 0 };
    for (let index = 0; index < selection.plan.inputs.length; index += 1) {
      const input = itemAt(selection.plan.inputs, index);
      let value: Node;
      let present = false;
      if (input.source.kind === 'field') {
        present = Object.prototype.hasOwnProperty.call(payload, input.source.field.name);
        value = payload[input.source.field.name];
      } else {
        const plan = input.source.plan;
        let target = itemAt(plan.nodes, plan.start).leaf as string;
        if (itemAt(plan.nodes, plan.start).may_miss && !accessorOptional(target)[1]) {
          target = `Optional<${target}>`;
        }
        try {
          [value, present] = new AccessorObservation({ plan, target }).evaluate(payload);
        } catch {
          throw selectionFailure('invalid_input', index, -1, -1);
        }
      }
      if (!Array.isArray(value) || !present) {
        throw selectionFailure('invalid_input', index, -1, -1);
      }
      if (value.length > 64) {
        throw selectionFailure('resource', index, -1, -1);
      }
      inputs[index] = value;
    }
    const truth: boolean[][] = selection.plan.selectors.map(() => []);
    for (let input = 0; input < inputs.length; input += 1) {
      const values = itemAt(inputs, input);
      for (let index = 0; index < values.length; index += 1) {
        const item = values[index];
        if (isNil(item) && itemAt(selection.plan.inputs, input).optional_items) {
          for (let selector = 0; selector < selection.plan.selectors.length; selector += 1) {
            const plan = itemAt(selection.plan.selectors, selector);
            if (plan.input === input && plan.operation.kind === 'first') {
              itemAt(truth, selector).push(false);
            }
          }
          continue;
        }
        try {
          selection.validateValue(
            itemAt(selection.plan.inputs, input).item_type,
            item,
            true,
            counter,
            0,
          );
        } catch (error) {
          throw selectionFailure(errorText(error), input, index, -1);
        }
        for (let selector = 0; selector < selection.plan.selectors.length; selector += 1) {
          const plan = itemAt(selection.plan.selectors, selector);
          if (plan.input !== input || plan.operation.kind !== 'first') {
            continue;
          }
          const observations: FactSource = new Map<string, Node>();
          for (const path of meaningKeys(
            selectionJSON(plan.operation.reads) as { [key: string]: Node },
          )) {
            const projection = plan.operation.reads[path] as AccessorPlan;
            let target = itemAt(projection.nodes, projection.start).leaf as string;
            if (
              itemAt(projection.nodes, projection.start).may_miss &&
              !accessorOptional(target)[1]
            ) {
              target = `Optional<${target}>`;
            }
            let value: Node;
            let present: boolean;
            try {
              [value, present] = new AccessorObservation({ plan: projection, target }).evaluate({
                item,
              });
            } catch {
              throw selectionFailure('invalid_input', input, index, selector);
            }
            if (typeof value === 'string' && present) {
              counter.bytes += path.length + value.length;
              if (value.length > 4096 || counter.bytes > 1048576) {
                throw selectionFailure('resource', input, index, selector);
              }
              observations.set(path, value);
            }
          }
          const condition = fromNode(plan.operation.predicate);
          const answer = condition.evaluate(observations);
          if (answer === TruthUnknown) {
            throw selectionFailure('unknown', input, index, selector);
          }
          itemAt(truth, selector).push(answer === TruthTrue);
        }
      }
    }
    const selected: number[] = selection.plan.selectors.map(() => -1);
    for (let index = 0; index < selection.plan.selectors.length; index += 1) {
      const selector = itemAt(selection.plan.selectors, index);
      const answers = itemAt(truth, index);
      if (selector.operation.kind === 'first') {
        for (let occurrence = 0; occurrence < answers.length; occurrence += 1) {
          if (!answers[occurrence]) {
            continue;
          }
          let excluded = false;
          for (const prior of selector.operation.excluding) {
            if (selected[prior] === occurrence) {
              excluded = true;
            }
          }
          if (!excluded) {
            selected[index] = occurrence;
            break;
          }
        }
      } else {
        for (const prior of selector.operation.selections) {
          const bound = itemAt(selected, prior);
          if (bound >= 0) {
            selected[index] = bound;
            break;
          }
        }
      }
    }
    const occurrence = itemAt(selected, selection.selector);
    if (occurrence < 0) {
      return [null, false];
    }
    const projection = selection.projection;
    return new AccessorObservation({
      plan: projection.projection,
      target: projection.target,
      types: projection.types,
    }).evaluate({
      item: itemAt(
        itemAt(inputs, itemAt(selection.plan.selectors, selection.selector).input),
        occurrence,
      ),
    });
  }
}

export function admitSelection(value: Node): SelectionObservation {
  const root = closed(value, 'event_type plan declarations selector projection', '');
  name(root.event_type, false);
  const planned = closed(root.plan, 'inputs selectors', '');
  const inputs = attempt(() => array(planned.inputs));
  if (inputs === undefined || inputs.length > 4) {
    throw new Error('selection input bound');
  }
  const selectors = attempt(() => array(planned.selectors));
  if (selectors === undefined || selectors.length > 8) {
    throw new Error('selection selector bound');
  }
  if (accessorCompactBytes(goMarshal(value)) > 1048576) {
    throw new Error('selection byte bound');
  }
  const selection = new SelectionObservation(value);
  if (selection.selector < 0 || selection.selector >= selectors.length) {
    throw new Error('selection output index invalid');
  }
  const declarations = root.declarations;
  if (!isObject(declarations) || Object.keys(declarations).length > 4096) {
    throw new Error('selection declaration bound');
  }
  for (const label of Object.keys(declarations)) {
    name(label, false);
    const body = selection.declarations[label] as SelectionDeclaration;
    let required = 'kind';
    switch (body.kind) {
      case 'newtype':
        required += ' of';
        break;
      case 'struct':
        required += ' fields';
        break;
      case 'enum':
        required += ' variants';
        break;
      case 'union':
        required += ' tag variants';
        break;
      default:
        throw new Error('unsupported selection declaration');
    }
    const fields = closed((declarations as { [key: string]: Node })[label], required, '');
    if (body.kind === 'struct') {
      const members = attempt(() => array(fields.fields));
      if (members === undefined || members.length > 4096) {
        throw new Error('selection field bound');
      }
      const seen = new Set<string>();
      for (const field of members) {
        admitAccessorField(field);
        const written = (field as { [key: string]: Node }).name as string;
        if (seen.has(written)) {
          throw new Error('duplicate selection field');
        }
        seen.add(written);
      }
    }
  }
  let names = new Set<string>();
  for (let index = 0; index < inputs.length; index += 1) {
    const fields = closed(
      itemAt(inputs, index),
      'name source list_type item_type optional_items conversion',
      '',
    );
    const input = itemAt(selection.plan.inputs, index);
    if (!ACCESSOR_SEGMENT.test(input.name) || names.has(input.name)) {
      throw new Error('invalid selection input name');
    }
    names.add(input.name);
    if (input.conversion !== null) {
      throw new Error('selection-input-conversion requires host implementation');
    }
    const list = attempt(() => selection.transparent(input.list_type));
    if (list === undefined || !list.startsWith('List<') || !list.endsWith('>')) {
      throw new Error('selection requires required List');
    }
    const originalItem = list.slice('List<'.length, list.length - 1);
    let item = selection.transparent(originalItem);
    let optional = false;
    const [inner, isOptional] = accessorOptional(item);
    if (isOptional) {
      optional = true;
      item = inner;
    } else {
      item = originalItem;
    }
    if (item !== input.item_type || optional !== input.optional_items) {
      throw new Error('selection item type differs');
    }
    const present = selection.transparent(item);
    const kind = (selection.declarations[present] ?? decodeSelectionDeclaration(undefined)).kind;
    if (kind !== 'struct' && kind !== 'union') {
      throw new Error('selection item requires record');
    }
    const source = fields.source;
    if (!isObject(source)) {
      throw new Error('selection source shape');
    }
    let sourceType = '';
    switch (input.source.kind) {
      case 'field':
        closed(source, 'kind field', '');
        admitAccessorField(source.field);
        sourceType = input.source.field.type;
        break;
      case 'accessor': {
        closed(source, 'kind plan', '');
        selection.checkPlan(input.source.plan, false);
        const plan = input.source.plan;
        sourceType = itemAt(plan.nodes, plan.start).leaf as string;
        if (itemAt(plan.nodes, plan.start).may_miss && !accessorOptional(sourceType)[1]) {
          sourceType = `Optional<${sourceType}>`;
        }
        break;
      }
      default:
        throw new Error('invalid selection source kind');
    }
    if (sourceType !== input.list_type) {
      throw new Error('selection source/list type mismatch');
    }
  }
  names = new Set<string>();
  let total = 0;
  for (let index = 0; index < selectors.length; index += 1) {
    const fields = closed(itemAt(selectors, index), 'name input operation', '');
    const selector = itemAt(selection.plan.selectors, index);
    if (
      !ACCESSOR_SEGMENT.test(selector.name) ||
      names.has(selector.name) ||
      selector.input < 0 ||
      selector.input >= inputs.length
    ) {
      throw new Error('selection identity invalid');
    }
    names.add(selector.name);
    const operation = selector.operation;
    let required = 'kind';
    let prior: number[] = [];
    switch (operation.kind) {
      case 'first':
        required += ' excluding predicate reads';
        prior = operation.excluding;
        break;
      case 'first_present':
        required += ' selections';
        prior = operation.selections;
        if (prior.length === 0) {
          throw new Error('empty first_present');
        }
        break;
      default:
        throw new Error('unsupported selector');
    }
    const written = closed(fields.operation, required, '');
    if (prior.length > 4) {
      throw new Error('selection reference bound');
    }
    const seen = new Set<number>();
    for (const previous of prior) {
      if (
        previous < 0 ||
        previous >= index ||
        seen.has(previous) ||
        itemAt(selection.plan.selectors, previous).input !== selector.input
      ) {
        throw new Error('selection reference is not earlier same input');
      }
      seen.add(previous);
    }
    if (operation.kind === 'first') {
      admitPredicateEnvelope(written.predicate, 0);
      if (Object.keys(operation.reads).length > 64) {
        throw new Error('selection read bound');
      }
      for (const [path, plan] of Object.entries(operation.reads)) {
        if (
          plan.segments.join('.') !== path ||
          plan.root.type !== itemAt(selection.plan.inputs, selector.input).item_type
        ) {
          throw new Error('selection read identity differs');
        }
        selection.checkPlan(plan, true);
        let leaf = selection.transparent(itemAt(plan.nodes, plan.start).leaf as string);
        for (;;) {
          const [inner, optional] = accessorOptional(leaf);
          if (!optional) {
            break;
          }
          leaf = selection.transparent(inner);
        }
        if (leaf !== 'String' && (selection.declarations[leaf]?.kind ?? '') !== 'enum') {
          throw new Error('selection predicate requires String or enum');
        }
      }
      const condition = fromNode(written.predicate);
      const count = { n: 0 };
      const used = new Set<string>();
      selection.checkPredicate(condition, operation.reads, count, used);
      if (used.size !== Object.keys(operation.reads).length) {
        throw new Error('selection contains unused predicate reads');
      }
      total += count.n;
      if (total > 256) {
        throw new Error('selection total predicate bound');
      }
    }
  }
  const projection = closed(root.projection, 'projection target types', '');
  selection.checkPlan(selection.projection.projection, true);
  if (
    selection.projection.projection.root.type !==
    itemAt(selection.plan.inputs, itemAt(selection.plan.selectors, selection.selector).input)
      .item_type
  ) {
    throw new Error('selection projection item differs');
  }
  if (!accessorOptional(selection.projection.target)[1]) {
    throw new Error('selection target requires Optional');
  }
  admitAccessorMode(
    { plan: projection.projection, target: projection.target, types: projection.types },
    true,
  );
  return selection;
}

// ---- the predicate vocabulary a suite version admits -------------------------------------------------

/** Only admitted predicate grammar is visited; payload maps are never interpreted as expressions. */
export function admitPredicateVersion(value: Node, major: number): void {
  admitPredicateEnvelope(value, 0);
  if (major < 8 && predicateNeedsLosslessReader(value)) {
    throw new Error('normalized structured comparison operands require suite/8 or /9');
  }
}

const COMPARISON_OPERATORS = new Set([
  'eq',
  'equals',
  '==',
  'ne',
  'not_equals',
  '!=',
  'lt',
  '<',
  'le',
  'lte',
  '<=',
  'gt',
  '>',
  'ge',
  'gte',
  '>=',
]);

export function predicateNeedsLosslessReader(value: Node): boolean {
  if (Array.isArray(value)) {
    return value.some(predicateNeedsLosslessReader);
  }
  if (isObject(value)) {
    for (const key of Object.keys(value)) {
      const child = value[key];
      switch (key) {
        case 'all':
        case 'and':
        case 'all_of':
        case 'any':
        case 'or':
        case 'none':
        case 'none_of_these':
        case 'not':
          if (predicateNeedsLosslessReader(child)) {
            return true;
          }
          break;
        case 'forall':
        case 'exists':
          if (
            isObject(child) &&
            predicateNeedsLosslessReader((child as { [key: string]: Node }).that)
          ) {
            return true;
          }
          break;
        default:
          if (isObject(child)) {
            const operators = child as { [key: string]: Node };
            for (const operator of Object.keys(operators)) {
              if (!COMPARISON_OPERATORS.has(operator)) {
                continue;
              }
              const raw = operators[operator];
              if (typeof raw === 'string') {
                const parsed = parseOperand(raw);
                if (parsed.isFact || parsed.literal !== raw) {
                  return true;
                }
              }
            }
          }
          break;
      }
    }
  }
  return false;
}
